<template>
    <div class="ai_base mb-4 float-left w-100">       
        <div v-if="loading" class="text-center py-8">
            <div class="flex flex-col items-center">
                <div class="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-500 mb-4"></div>
                <p class="text-gray-500 mb-0">Analyzing project data... Please wait.</p>
                <div class="bd-example mb-2">
                    <div class="spinner-grow text-primary" role="status">
                        <span class="sr-only">Loading...</span>
                    </div>
                    <div class="spinner-grow text-secondary" role="status">
                        <span class="sr-only">Loading...</span>
                    </div>
                    <div class="spinner-grow text-success" role="status">
                        <span class="sr-only">Loading...</span>
                    </div>
                    <div class="spinner-grow text-danger" role="status">
                        <span class="sr-only">Loading...</span>
                    </div>
                    <div class="spinner-grow text-warning" role="status">
                        <span class="sr-only">Loading...</span>
                    </div>
                    <div class="spinner-grow text-info" role="status">
                        <span class="sr-only">Loading...</span>
                    </div>
                </div>
            </div>
        </div>
        <div v-if="error" class="bg-red-100 border border-red-400 text-red-700 px-4 py-3 rounded relative mb-4">
            <strong class="font-bold">Error! </strong>
            <span class="block sm:inline">{{ error }}</span>
        </div>
        <div v-if="analysisResult" class="analysis-results pt-2">
            <div class="p-2 mb-6 text-ai">
                <div class="em_base"><em class="fa fa-suitcase"></em></div>
                <strong>AI Analysis Complete..! Below are the insights and recommendations for your project.</strong>
            </div>
            <div class="analysis-content p-2">
                <div
                    class="whitespace-pre-wrap"
                    :style="analysisContainerStyle"
                    v-html="formatAnalysisResult(analysisResult)"
                ></div>
                <div v-if="showAnalysisToggle" class="text-right mt-2">
                    <a href="javascript:void(0)" @click="toggleAnalysisView">
                        {{ isAnalysisExpanded ? 'Show Less' : 'Show More' }}
                    </a>
                </div>
            </div>
        </div>
    </div>
</template>

<script>
import DataService from "@/services/DataService";

export default {
    name: "AIAnalysisPanel",
    props: {
        projectId: {
            type: Number,
            required: true
        },
        AIAnalysis: {
            type: String,
            required: true
        }
    },
    data() {
        return {
            analysisResult: null,
            loading: true,
            error: null,
            SortBy: '',
            SortExp: '',
            PageSize: 100,
            PageNumber: 1,
            ProjectId: 0,
            ListingData: [],
            ProjectDetailData: [],
            projectData: { name: '', status: '', tasks: [] },
            isAnalysisExpanded: false,
            analysisPreviewLength: 380
        };
    },
    computed: {
        showAnalysisToggle() {
            const plainText = this.getAnalysisPlainText(this.analysisResult);
            return plainText.length > this.analysisPreviewLength;
        },
        analysisContainerStyle() {
            if (!this.showAnalysisToggle || this.isAnalysisExpanded) {
                return {};
            }
            return {
                maxHeight: '52px',
                overflow: 'hidden'
            };
        }
    },
    created: async function () {
        var ths = this;
        ths.ProjectId = ths.projectId;        
        await ths.initializePanelData();
    },
    methods: {
        initializePanelData: async function () {
            await this.FetchTaskList();
            await this.GetProjectDetails();
        },

        FetchTaskList: async function () {
            var vueObj = this;
            var params = `ProjectId=${vueObj.ProjectId}&name=&priority=&SprintId=&Type=&BugType=&StatusId=&Assignee=&sortBy=${vueObj.SortBy}&sortExp=${vueObj.SortExp}&pageSize=${vueObj.PageSize}&pageNumber=${vueObj.PageNumber}&userType=`; 
            await DataService.GetChildSprint(params).then(function (response) {
                if (response.data.result.Data.length > 0) {
                    var updateArray = response.data.result.Data;
                    updateArray.forEach((x) => {
                        var Obj = {
                            name: x.task_name,
                            status: x.status_name,
                            assignedTo: x.Assign != null ? x.Assign : 'Not Assigned',
                            dueDate: x.planned_end_date ? new Date(x.planned_end_date).toISOString().split("T")[0] : 'Not set',
                            notes: x.task_description
                        };
                        vueObj.ListingData.push(Obj);
                    });
                    vueObj.$set(vueObj.projectData, "tasks", vueObj.ListingData);
                } else {
                    vueObj.ListingData = [];
                    vueObj.$set(vueObj.projectData, "tasks", []);
                }
            });
        },
        GetProjectDetails: async function () {
            var vm = this;
            var params = `projectId=${vm.projectId}`;
            await DataService.GetProjectDetails(params).then(function (response) {
                if (response.data.result != null && response.data.result != '') {
                    vm.ProjectDetailData.push(response.data.result.PROJECTOVERVIEW[0]);
                    var ProjectName = vm.ProjectDetailData[0].PROJECT_NAME;
                    var StatusName = vm.ProjectDetailData[0].STATUS_NAME;
                    vm.projectData.name = ProjectName;
                    vm.projectData.status = StatusName;
                    vm.$set(vm.projectData, "tasks", Array.isArray(vm.ListingData) ? vm.ListingData : []);
                    if (vm.AIAnalysis != null) {
                        vm.analysisResult = vm.AIAnalysis;
                        vm.loading=false;
                        vm.isAnalysisExpanded = false;
                    } else {
                        vm.getAIAnalysis();
                    }
                }
            });
        },
        async getAIAnalysis() {
            this.loading = true;
            this.analysisResult = null;
            this.error = null;
            const apiKey = process.env.VUE_APP_GROQ_API_KEY;
            if (!apiKey) {
                this.error = "Groq API key is missing. Add it to your .env file.";
                this.loading = false;
                return;
            }
            const taskDetails = (this.projectData.tasks || [])
                .map(task => `
                - Task: ${task.name || "Untitled"}
                Status: ${task.status || "Unknown"}
                Assigned to: ${task.assignedTo || "Not assigned"}
                Due Date: ${task.dueDate || "Not set"}
                Notes: ${task.notes || "None"}
            `).join("\n") || "No tasks available.";
            const systemPrompt = `You are an expert Project Management AI analyst.`;
            const userPrompt = `Analyze the following project and return ONLY bullet points following these rules:
                - Each bullet must start with one of these emojis:
                ❌ for Critical issues
                ⚠️ for Warnings
                ✅ for Strengths
                💡 for Recommendations (include priority P1/P2/P3 inside parentheses)
                - Format exactly like:
                ❌ Critical: [short headline]. [brief explanation]
                ⚠️ Warning: [short headline]. [brief explanation]
                ✅ Strength: [short headline]. [brief explanation]
                💡 Recommendation (P1): [short headline]. [brief explanation]
                - Do not use any other markdown or grouping.
                Project: ${this.projectData.name || "Unnamed"}
                Overall Status: ${this.projectData.status || "Unknown"}
                --- TASKS ---
                ${taskDetails}`;

            try {
                const response = await fetch("https://api.groq.com/openai/v1/chat/completions", {
                    method: "POST",
                    headers: {
                        "Content-Type": "application/json",
                        "Authorization": `Bearer ${apiKey}`
                    },
                    body: JSON.stringify({
                        model: "llama-3.3-70b-versatile", // or any Groq model
                        messages: [
                            { role: "system", content: systemPrompt },
                            { role: "user", content: userPrompt }
                        ],
                        temperature: 0.3,
                        max_tokens: 1024
                    })
                });
                const result = await response.json();

                if (!response.ok) {
                    const errorMsg = result?.error?.message || result?.message || `HTTP ${response.status}`;
                    throw new Error(`Groq API error: ${errorMsg}`);
                }

                const rawAnalysis = result?.choices?.[0]?.message?.content || "No analysis returned.";
                this.analysisResult = rawAnalysis;
                this.isAnalysisExpanded = false;

                if (!this.AIAnalysis) {
                    // Save one consistent formatted payload instead of saving multiple variants.
                    this.SaveAlAnalysis(this.formatAnalysisResult(rawAnalysis));
                }
            } catch (error) {
                console.error("AI Analysis failed:", error);
                this.error = error.message || "Failed to get AI analysis. Please try again.";
            } finally {
                this.loading = false;
            }
        },
        restoreEmojiMarkers(text) {
            if (!text) return '';
            return text
                // Recover saved HTML icon spans where DB replaced emoji with ? / ??.
                .replace(/(<span[^>]*text-red-500[^>]*>)[^<]*(<\/span>\s*<span>\s*<strong>\s*Critical:)/gim, '$1❌$2')
                .replace(/(<span[^>]*text-yellow-500[^>]*>)[^<]*(<\/span>\s*<span>\s*<strong>\s*Warning:)/gim, '$1⚠️$2')
                .replace(/(<span[^>]*text-green-500[^>]*>)[^<]*(<\/span>\s*<span>\s*<strong>\s*Strength:)/gim, '$1✅$2')
                .replace(/(<span[^>]*text-purple-500[^>]*>)[^<]*(<\/span>\s*<span>\s*<strong>\s*Recommendation\s*\(P[1-3]\):)/gim, '$1💡$2')
                // Recover plain-text markers.
                .replace(/(?:\?\?|\?)\s*Critical:/gim, '❌ Critical:')
                .replace(/(?:\?\?|\?)\s*Warning:/gim, '⚠️ Warning:')
                .replace(/(?:\?\?|\?)\s*Strength:/gim, '✅ Strength:')
                .replace(/(?:\?\?|\?)\s*Recommendation\s*\((P[1-3])\):/gim, '💡 Recommendation ($1):');
        },
        getAnalysisPlainText(text) {
            if (!text) return '';
            const normalizedText = this.restoreEmojiMarkers(text);
            // Strip HTML tags to measure real readable length.
            return normalizedText.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
        },
        toggleAnalysisView() {
            this.isAnalysisExpanded = !this.isAnalysisExpanded;
        },
        formatAnalysisResult(text) {
            if (!text) return '';
            const normalizedText = this.restoreEmojiMarkers(text);
            // If content is already saved as HTML, only restore emoji markers and render as-is.
            if (/<[a-z][\s\S]*>/i.test(normalizedText)) {
                return normalizedText;
            }
            let cleanedText = normalizedText.replace(/\*/g, '').replace(/^• /gm, '');
            let formattedText = cleanedText
                // ❌ Critical
                .replace(/^❌ ([^:]+): (.*)$/gim,
                    '<div class="flex items-start mt-2"><span class="text-red-500 mr-2 font-12">❌</span><span><strong>$1:</strong> $2</span></div>')
                // ⚠️ Warning
                .replace(/^⚠️ ([^:]+): (.*)$/gim,
                    '<div class="flex items-start mt-2"><span class="text-yellow-500 mr-2">⚠️</span><span><strong>$1:</strong> $2</span></div>')
                // ✅ Positive
                .replace(/^✅ ([^:]+): (.*)$/gim,
                    '<div class="flex items-start mt-2"><span class="text-green-500 mr-2">✅</span><span><strong>$1:</strong> $2</span></div>')
                // 💡 Recommendations (P1/P2/P3)
                .replace(/^💡 Recommendation \((P[1-3])\): (.*)$/gim,
                    '<div class="flex items-start mt-2 recommendation"><span class="text-purple-500 mr-2">💡</span><span><strong>Recommendation ($1):</strong> $2</span></div>')
                // Fallback for any remaining bullet lines that start with "-"
                .replace(/^- (.*)$/gim,
                    '<div class="flex items-start mt-1"><span class="mr-2">•</span><span>$1</span></div>');

            // Wrap everything in one parent div
            formattedText = `<div class="space-y-2">${formattedText}</div>`;
            return formattedText;
        },
        SaveAlAnalysis(text) {
            var vm = this;
            var Obj = {
                ProjectId: vm.projectId,
                ProjectAnalysis: text
            };
            var objectPostString = JSON.stringify(Obj);
            DataService.SaveAlAnalysis(objectPostString).then(res => {
              
            }).catch(err => {
                console.error("Failed to save analysis:", err);
            });
        }
    }
}
</script>