<template>
  <section>
    <loader :is-visible="isLoading"></loader>

    <div class="ticketsmallfix theme-primary partition p-actions-expand" style="overflow: visible;">
      <span class="p-name text-white">{{ $t('Refund Policy') }}</span>

      <span class="p-actions float-right">
        <a @click="AddRefundPolicy" href="javascript:;" class="p-action-btn text-white">
          <em class="fa fa-plus pr-2"></em><br />
          <span>{{ $t('Add') }}</span>
        </a>

        <a @click="BackToList" class="p-action-btn text-white float-right">
          <i class="fa fa-angle-double-left"></i><br />
          {{ $t('BacktoList') }}
        </a>
      </span>
    </div>

    <Form ref="form">
      <div class="col-md-12">
        <div class="row">
          <div class="listing mt-2">
            <div class="table-responsive mt-3">
              <table class="table table-bordered dt-responsive nowrap mt-0">
                <thead class="thead-bg">
                  <tr>
                    <th style="min-width:130px;"><span class="float-left">{{ $t('Units') }}</span> <span
                        class="text-danger float-left">*</span></th>
                    <th style="min-width:260px;"><span class="float-left">{{ $t('BeforeEventStart') }}</span> <span
                        class="text-danger float-left">*</span></th>
                    <th style="min-width:200px;"><span class="float-left">{{ $t('Refund') }}{{ $t('Policy') }} {{
                      $t('Type') }}</span> <span class="text-danger float-left">*</span></th>
                    <th style="min-width:190px;"><span class="float-left">{{ $t('Value') }}</span> <span
                        class="text-danger float-left">*</span></th>
                    <th style="min-width:130px;" class="text-center"><span>{{ $t('Delete') }}</span> </th>
                  </tr>
                </thead>

                <tbody>
                  <tr v-for="(value, index) in policylist" :key="index">
                    <!-- Units -->
                    <td class="py-3" style="vertical-align:top;">
                      <Field :name="'units' + index" rules="required" v-slot="{ errors }">
                        <select v-model="value.units" :class="['form-control', { 'is-invalid': errors.length }]">
                          <option value="" selected>Select Hour</option>
                          <option v-for="(option, i) in unitOptions" :key="i" :value="option.value">
                            {{ option.text }}
                          </option>
                        </select>
                        <span class="invalid-feedback">{{ $t('The Units field is required') }}</span>
                      </Field>
                    </td>

                    <!-- Before Event Start (From / To) -->
                    <td class="py-3" style="vertical-align:top;">
                      <div class="col-sm-12 col-md-12 col-lg-12 col-xl-12 float-left p-0">
                        <div class="col-sm-6 col-md-6 col-lg-6 col-xl-6 float-left pl-0">
                          <!-- From -->
                          <Field :name="'refundFrom' + index" rules="required" v-slot="{ errors }">
                            <input type="text" v-model="value.refundFrom" placeholder="From"
                              :class="['form-control mb-2', { 'is-invalid': errors.length }]" />
                            <span class="invalid-feedback">{{ $t('The RefundFrom field is required') }}</span>
                          </Field>
                        </div>
                        <div class="col-sm-6 col-md-6 col-lg-6 col-xl-6 float-left pl-0">
                          <!-- To -->
                          <Field :name="'refundTo' + index" rules="required" v-slot="{ errors }">
                            <input type="text" v-model="value.refundTo" placeholder="To"
                              :class="['form-control', { 'is-invalid': errors.length }]" />

                            <span class="invalid-feedback">{{ $t('The RefundTo field is required') }}</span>
                          </Field>
                        </div>
                      </div>
                    </td>

                    <!-- Refund Policy Type -->
                    <td class="py-3" style="vertical-align:top;">
                      <Field :name="'refundPolicyType' + index" rules="required" v-slot="{ errors }">
                        <select v-model="value.refundPolicyType" @change="GetrefundPolicyType"
                          :class="['form-control', { 'is-invalid': errors.length }]">
                          <option value="" selected>Select Refund Policy Type</option>
                          <option v-for="(option, i) in refundPolicyTypeOptions" :key="i" :value="option.value">
                            {{ option.text }}
                          </option>
                        </select>
                        <span class="invalid-feedback">{{ $t('The Refund Policy Type field is required') }}</span>
                      </Field>
                    </td>

                    <!-- Refund Value -->
                    <td class="py-3" style="vertical-align:top;">
                      <div v-if="value.refundPolicyType === 'partial'"
                        class="col-sm-12 col-md-12 col-lg-12 col-xl-12 float-left p-0">

                        <Field :name="'refundValue' + index" rules="required" v-slot="{ errors }"
                          class="d-flex input-group">
                          <input type="text" v-model="value.refundTypeValue"
                            :class="['form-control', { 'is-invalid': errors.length }]" />
                          <div class="input-group-append">
                            <div class="input-group-text text-info border-radius-0">
                              {{ value.refundType }}
                            </div>
                          </div>
                          <span class="invalid-feedback">{{ $t('The Value field is required') }}</span>
                        </Field>
                      </div>
                    </td>

                    <!-- Delete -->
                    <td class="text-center single-action w-100" style="display: inline-block;">

                      <a v-on:click="deletePolicyRow(index, value)" v-bind:key="index" title="Delete"
                        style="cursor:pointer" class="actions-onclick float-none"><em
                          class="fa fa-trash-o text-danger action-icon"></em></a>

                    </td>

                  </tr>

                </tbody>
              </table>
            </div>
          </div>
        </div>
      </div>
    </Form>

    <div class="text-right mt-3">
      <a id="aSubmit" @click="SubmitRegistrationData" class="btn btn-success formbtn text-white mr-2 " title="Submit"><i
          class="fa fa-save pr-2"></i>{{ $t('Submit') }}</a>
    </div>

  </section>
</template>

<script>
import DataService from '@/services/DataService';
import EventDetailSchema from './EventDetailSchema';

export default {
  name: 'RefundPolicyPortion',
  data() {
    return {
      policylist: [],
      isLoading: false,
      ShowCancelButton: false,
      refundUnits: EventDetailSchema.refundPolicyUnits || [],
      refunData: [],
      unitOptions: [

        { value: 'min', text: 'Minutes' },
        { value: 'hour', text: 'Hours' },
        { value: 'day', text: 'Days' },
        { value: 'week', text: 'Weeks' },
        { value: 'month', text: 'Months' }
      ],
      refundPolicyTypeOptions: [

        { value: 'full', text: 'Full Refund' },
        { value: 'partial', text: 'Partial Refund' },
        { value: 'noRefund', text: 'No Refund' }
      ],
      eventId: 0,
      Grouptype: "",
      setupid: "",
      configurationtype: 1,
      configurationid: "",
      registrationid: "",
      Maxattendess: "",
      Enablegroup: "",
      ticketName: "",
      Pageheadline: "",
      Description: "",
      passwordprotect: "",
      title: "",
      timelimit: "",
      Instructions: "",
      DisplayMessage: "",
      EditInformation: 0,
      AcceptRefunds: 0,
    };
  },
  watch: {
    policylist: {
      handler(newVal) {
        newVal.forEach(item => {
          if (item.refundPolicyType !== 'partial') {
            item.refundValue = '';
          }
        });
      },
      deep: true
    }
  },
  created() {
    this.fetchRefundPolicy();
  },
  methods: {
    async fetchRefundPolicy() {
      try {
        const response = await DataService.GetRefundPolicyDetails(
          `eventId=${this.$route.params.projectId}&companyId=${this.GetUserInfo.CompanyId}&userId=${this.GetUserInfo.ID}`
        );

        if (
          response.data &&
          response.data.result &&
          Array.isArray(response.data.result.refundpolicyData)
        ) {
          this.policylist = response.data.result.refundpolicyData.map(p => ({
            refund_id: p.refund_id,
            units: p.refund_units || '',
            refundFrom: p.refund_from ?? '',
            refundTo: p.refund_to ?? '',
            refundPolicyType: p.refund_policy_type || '',
            refundType: p.refund_type || '',
            refundTypeValue: p.refund_type_value ?? '',
            isDeleted: 0
          }));
        } else {
          this.policylist = [];
        }
        if (this.policylist.length === 0) this.AddRefundPolicy();

      } catch (err) {
        this.policylist = [];
        this.AddRefundPolicy();
      }
    },
    async AddRefundPolicy() {
      var vm = this;
      var url = 'controller=Project&action=AddUpdateRefundPolicy';
      await DataService.CheckPrivilege(url).then(async function (response) {
        if (response.data) {
          this.policylist.push({
            refund_id: 0,
            units: '',
            refundFrom: '',
            refundTo: '',
            refundPolicyType: '',
            refundTypeValue: '',
            refundType: '%',
            isDeleted: 0
          });
        } else {
          vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, "Alert");
        }
      });
    },
    async deletePolicyRow(index, policy) {
      var vm = this;
      var url = 'controller=Project&action=AddUpdateRefundPolicy';
      await DataService.CheckPrivilege(url).then(async function (response) {
        if (response.data) {
          if (policy.id) {
            policy.isDeleted = 1;
          } else {
            this.confirmR(this.$t("ConfirmDelete"), true, (this.$t("Delete") + "  " + this.$t("Group")), function () {
              vm.policylist.splice(index, 1);
            });
          }
        }
        else {
          vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, "Alert");
        }
      })
    },
    async SubmitRegistrationData() {
      var vm = this;
      var url = 'controller=Project&action=AddUpdateRefundPolicy';
      await DataService.CheckPrivilege(url).then(async function (response) {
        if (response.data) {
          const isValid = await this.$refs.form.validate();
          if (!isValid) {
            return false
          }
          this.isLoading = true;
          try {
            var registrationdatablock = {
              userId: vm.GetUserInfo.ID,
              companyId: vm.GetUserInfo.CompanyId,
              eventid: vm.$route.params.projectId,
              setupid: vm.setupid,
              title: vm.title,
              timelimit: vm.timelimit,
              Instructions: vm.Instructions,
              DisplayMessage: vm.DisplayMessage,
              EditInformation: vm.EditInformation,
              AcceptRefunds: vm.AcceptRefunds
            };
            var groupregistrationdatablock = {
              REGISTRATIONID: vm.registrationid,
              TICKET_ID: vm.ticketName,
              GROUP_TYPE_ID: vm.Grouptype,
              MAX_ATTENDES: vm.Maxattendess,
              ENABLE_BY_TICKET: vm.Enablegroup,
              GROUP_PAGE_TITLE: vm.Pageheadline,
              DESCRIPTION: vm.Description,
              IS_ALLOW_PASSWORD_PROTEC: vm.passwordprotect
            };
            var configurationdatablock = {
              CONFIGURATIONTYPE: vm.configurationtype,
              DOMAINURL: 'http://localhost:9000/Project/ProjectOverview/120642',
              CONFIGURATIONID: vm.configurationid
            };
            var finalData = {
              registration: registrationdatablock,
              groupregistration: groupregistrationdatablock,
              configuration: configurationdatablock,
              policylist: vm.policylist.filter(p => p.isDeleted !== 1)
            }
            const postString = JSON.stringify(finalData);
            const response = await DataService.SaveRefundPolicy(postString);
            if (response.data && response.data.status === "Success") {
              this.ShowAlert(this.$t("AddedSuccess"), "success", this.$t('Alert'));
              await this.fetchRefundPolicy();
            } else {
              this.ShowAlert(this.$t("PleaseCorrectHighlightedErrors"), "failure", this.$t('Alert'));
            }

          } catch (error) {

            this.ShowAlert(
              this.$t('SaveError'),
              'failure',
              true,
              this.$t('Alert')
            );

          } finally {
            this.isLoading = false;
          }

        } else {
          vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, "Alert");
        }
      });
    },
    BackToList: function () {
      this.$router.push({ name: 'ProjectList' });
    },
    CancelData() {
      this.fetchRefundPolicy();
    },
    GetrefundPolicyType() {

    }
  }
};
</script>
