<template>
  <div class="my-popups">
        <loader :is-visible="isLoading"></loader>
        <div class="modal d-block">
            <div class="modal-dialog modal-dialog-centered">
                <div class="modal-content">
                    <div class="modal-header theme-primary partition-full  d-flex">
                        <h4 class="modal-title">{{ $t('viewallteammembers') }}</h4>
                        <button type="button" class="close" v-on:click="CloseAllTeam()">
                            <em class="fa fa-times" aria-hidden="true"></em>
                        </button>
                    </div>
                    <div class="modal-body">
                            <tg-list ref="tgList" :listType="['List']" :IsShowAction="false" :showCheckBox="false" ModuleName="PROJECT"
                                SubModuleCode="Task" IdentityColumn="USER_ID" :HeaderText="$t('ProjectTeam')" :LegendArray="[]"
                                :ListData="ListingData" :HeaderData="Headers" :widgets="widgets"
                                :TotalRecords="TotalRecords" :RenderRowActionMethod="renderActions" v-on:LeftsearchButtonClick="leftCommonSearch"
                                :IsSearchFieldsOnTop="false" 
                                :ListDataCallBackFunction="FetchTeamListing" :SortExp="SortExp" :SortBy="SortBy"
                                :NorecordfoundText="$t('NoRecordfound')" v-on:PagerButtonClick="pagerMethod"
                                v-on:HeaderButtonClick="commonHeaderButtonClick" v-on:SortdataButtonClick="sortdata"
                                v-on:ActionButtonClick="actionButtonClick">
                                <template v-slot:slotdata="{ data }">
                                    <template v-if="data.column.COLUMN_NAME == 'Associate/DeAssociate'">                         
                                            <span :title="'Yes'">{{ $t('Yes') }}</span>   
                                    </template>
                                    <template v-if="data.column.COLUMN_NAME == 'LASTTRACKEDHOUR'"> 
                                      <span :title="data.row.TRACK_HOURS ? data.row.TRACK_HOURS : '0'">{{ data.row.TRACK_HOURS ? data.row.TRACK_HOURS : '0' }}</span>                     
                                    </template>
                                    <template v-if="data.column.COLUMN_NAME == 'DEPARTMENT'"> 
                                        {{ data.row.DEPARTMENT ? data.row.DEPARTMENT : '--' }}                        
                                    </template>
                                    <template v-if="data.column.COLUMN_NAME == 'DESIGNATION_NAME'"> 
                                        {{ data.row.DESIGNATION_NAME ? data.row.DESIGNATION_NAME : '--' }}                        
                                    </template>
                                    <template v-if="data.column.COLUMN_NAME == 'ALIASNAME'"> 
                                        {{ data.row.ALIASNAME ? data.row.ALIASNAME : '--' }}                        
                                    </template>
                                    <template v-if="data.column.COLUMN_NAME == 'USER_NAME'">                      
                                        <em v-if= "data.row.USER_TYPE=='User'" class="fa fa-user text-info mr-2"></em>
                                        <em v-else class="fa fa-users text-primary mr-2"></em>                        
                                        {{ data.row.USER_NAME ? data.row.USER_NAME : '--' }}                        
                                    </template>
                                    <template v-if="data.column.COLUMN_NAME == 'RATE'"> 
                                        <span :title="$n(data.row.RATE ? data.row.RATE : 0,'currency',$getLocaleByCurrency(Currency))"> {{$n(data.row.RATE ? data.row.RATE : 0,'currency',$getLocaleByCurrency(Currency))  }}</span>                                                                    
                                    </template>
                                    <template v-if="data.column.COLUMN_NAME == 'TRACK_HOURS'">                      
                                      <span :title="data.row.TRACK_HOURS ? data.row.TRACK_HOURS : '0' ">  {{ data.row.TRACK_HOURS ? data.row.TRACK_HOURS : '0' }}            </span>            
                                    </template>
                                    <template v-if="data.column.COLUMN_NAME == 'coun_task_progress'">
                                        <div   class="user-count-wrapper" >
                                            <span>
                                                <a
                                                    class="text-dark single-action" href="javascript:;">
                                                    <em class="fa fa fa-user"></em>
                                                    <span class="noti-circle noti-green">{{ data.row.coun_task_progress.length>0 ? data.row.coun_task_progress[0].count_assign_task : '0' }}</span>
                                                </a>
                                            </span>                       
                                            
                                        </div>
                                        
                                    </template>
                                </template>
                            </tg-list>  
                            <div class="clearfix"></div>
                                <div class="row flex-row-reverse mt-3">
                                    <div class="col-lg-6 text-right">
                                        <a href="javascript:;" class="submitbtn btn btn-danger formbtn"
                                            v-on:click="CloseAllTeam()" title="Cancel"><i
                                                class="fa fa-close pr-2"></i>{{ $t('Cancel') }} </a>
                                    </div>
                                </div>                      
                    </div>
                </div>
            </div>
        </div>
    </div>
</template>
<script>
import DataService from '../../services/DataService';
import schema from '../../views/Project/Project/ProjectDetailLeftAllTabs/ProjectTeamListingSchema';
export default {
    props: {
        projectId: {
            type: Number,
            require: true,
        },
    },
    data() {   
        return{
            IsType:'Team',  
            TotalRecords: 0,
            isAssociated: false,
            noRecords: false,
            projectName: "",
            isLoading: false,
            CompanyId: null,
            PageSize: 10,
            PageNumber: 1,
            isPaged: 1,
            TotalPages: 0,
            widgets: [],
            SortBy: '',
            SortExp: '',
            taskId: '',
            Headers: schema.TableHeader,
            ListingData: [],
            searchCondition: '',
            Buttons: schema.buttons,
            listActions: schema.listActions,
            ProjectTaskListingpopup: false,
            IsAddTeamShow: false,
            IsEditTeamShow: false,
            logged_usertype:null,
            topsearchField : [             
                {   
                    fieldName: 'Enter User Name' ,               
                    fieldType: "text",
                    fieldSearchConditionName: [''],
                    paramName: "UserName",
                    isSearch: true,
                    value: "",
                    listOptions: []
                },
            ],
            TeamData:[],
            IsUser:false,
            TeamId:0,
            Currency:'' 
        }
    },
    created:function(){
         var ths = this;        
        ths.CompanyId = ths.GetUserInfo.CompanyId;
        ths.userId = ths.GetUserInfo.ID; 
        ths.logged_usertype = ths.GetUserInfo.UserType;
        ths.Currency=ths.GetUserInfo.Currency.replace(/[()]/g, '');
        ths.ProjectOverview();
        Promise.all([
            ths.FetchTeamListing(),
            ths.GetTeamForAssociateProject()
        ])
        .then(([users, teams]) => {
            ths.ListingData = [...users, ...teams]; // ✅ merge results
            ths.TotalRecords = ths.ListingData.length;
            ths.TotalPages = Math.ceil(ths.TotalRecords / ths.PageSize);
            ths.CurrentPage = ths.PageNumber;
            console.log("✅ Loaded records:", ths.TotalRecords);
        })
        .catch(err => {
            console.error("❌ Error loading data:", err);
        });
    },
    methods:{
        CloseAllTeam(){
            this.$emit('CloseAllTeam');
        },
        ProjectOverview:async function(){
            var vm = this;
            var params = `projectId=${vm.projectId}`;
            await DataService.ProjectOverview(params).then(function (response) {                
                if(response.data != null > 0)
                {                    
                    vm.projectName=response.data.projecT_NAME;
                }
            });
        },
        pagerMethod: function (value) {
            this.PageSize = value.PageSize;
            this.PageNumber = value.PageNumber;
            this.FetchTeamListing();
        },
        commonHeaderButtonClick: function (event) {        
            switch (event.callbackfunction) {
                case "Deletedata":
                    this.Deletedata();
                    break;
                case "OpenAddTeamPopup":
                    this.OpenAddTeamPopup();
                    break; 
                case "EditProject":
                  this.EditProject();
                    break;               
                case "BackToList":
                    this.BackToList();
                    break;
            }
        },
        sortdata: function (s) {
            var SortDir = "sort tb_headerSortDown";
            this.SortBy = s;
            if (s === this.SortBy) {
                if (this.SortExp == "") {
                    this.SortExp = "ASC";
                    SortDir = "sort tb_headerSortDown";
                }
                else if (this.SortExp == "ASC") {
                    this.SortExp = "DESC";
                    SortDir = "sort tb_headerSortUp";
                }
                else {
                    this.SortExp = "ASC";
                    SortDir = "sort tb_headerSortDown";
                }
            }
            this.FetchTeamListing();
            $("#" + s + '  span:first-child').attr("class", SortDir);
        },
        FetchTeamListing: function () { 
            var ths = this;
            ths.isLoading = true;
            return new Promise((resolve, reject) => {
                let url = '';
                if (ths.searchCondition !== '') {
                    url = `projectId=${ths.projectId}&projectName=${ths.projectName}&designationId=&sortBy=${ths.SortBy}&sortExp=${ths.SortExp}&pageSize=${ths.PageSize}&pageNum=${ths.PageNumber}&${ths.searchCondition}`;
                } else {
                    url = `projectId=${ths.projectId}&projectName=${ths.projectName}&designationId=&sortBy=${ths.SortBy}&sortExp=${ths.SortExp}&pageSize=${ths.PageSize}&pageNum=${ths.PageNumber}`;
                }
                DataService.GetTeamListing(url)
                    .then((response) => {
                        ths.isLoading = false;    
                        if (response.data?.result?.data?.length > 0) {
                            ths.TotalRecords = response.data.result.data[0].Total_Count;
                            ths.TotalPages = Math.ceil(ths.TotalRecords / ths.PageSize);
                            ths.CurrentPage = ths.PageNumber;
                            resolve(response.data.result.data); // ✅ send data out
                        } else {
                            resolve([]); // ✅ empty array if no records
                        }
                    })
                    .catch((error) => {
                        ths.isLoading = false;
                        reject(error);
                    });
            });
        },
        GetTeamForAssociateProject() {
            var ths = this;
            return new Promise((resolve, reject) => {
                var url = `refId=${ths.projectId}&refCode=TEAM`;
                DataService.GetTeamForAssociateProject(url)
                    .then((response) => {
                        ths.isLoading = false;

                        if (response.data?.result?.length > 0) {
                            resolve(response.data.result); // ✅ Return the raw array
                        } else {
                            resolve([]); // ✅ Return empty array if no data
                        }
                    })
                    .catch((error) => {
                        ths.isLoading = false;
                        reject(error);
                    });
            });
        },
    }
}
</script>