<template>
  <section>
    <div class="row m-0">
      <div class="heading-border"><h5 class="h5"><span>{{ $t('EventDetails') }}</span></h5></div>
      <div class="col-12 p-0 mt-2">
        <div class="row">
          <div class="col-md-6" v-if="detail.imagePath">
            <div class="card border"><img :src="detail.imagePath" class="card-img-top" style="max-height:400px;object-fit:cover" alt="" /></div>
          </div>
          <div class="col-md-6" v-if="detail.description">
            <div class="card border p-3"><div class="event-description" v-html="detail.description"></div></div>
          </div>
        </div>
        <div class="mt-3" v-if="leftViewData && leftViewData.length">
          <div class="border p-3 mb-2" v-for="group in leftViewData" :key="group.group_name">
            <h6 class="text-muted mb-2">{{ group.group_name || group.group_display_name }}</h6>
            <div class="row" v-for="item in (group.LeftViewData || group.items || [])" :key="item.name" v-show="item.form_field_visibility !== 'NO'">
              <div class="col-5 font-weight-bold">{{ item.display_name || item.name }}:</div>
              <div class="col-7">{{ item.value != null ? item.value : '—' }}</div>
            </div>
          </div>
        </div>
        <div v-if="!detail.imagePath && !detail.description && (!leftViewData || !leftViewData.length)" class="text-center py-4"><span class="text-danger no-record">{{ $t('NoRecordfound') }}</span></div>
      </div>
    </div>
  </section>
</template>

<script>
import DataService from '@/services/DataService';

export default {
  name: 'EventDetailsPortion',
  props: { eventId: { type: [Number, String], required: true } },
  data() { return { detail: {}, leftViewData: [] }; },
  created() {
    DataService.GetEventDetails(`projectId=${this.eventId}`).then(res => {
      const d = res.data;
      if (d) {
        this.detail = { imagePath: d.IMAGEPATH || d.imagePath, description: d.GlobalEventDescription || d.description };
        this.leftViewData = d.LEFTDATA || d.leftViewData || [];
      }
    }).catch(() => {});
  }
};
</script>
