<template>
    <section>
        <div>
            <tg-list  
                ref="tgList" 
                :listType="['List']" 
                :IsShowAction="true" 
                :showCheckBox="false" 
                ModuleName="PROJECT" 
                SubModuleCode="Client" 
                IdentityColumn="USERID" 
                :HeaderText="$t('VirtualUserConfiguration')"
                :ListData="ListingData" 
                :HeaderData="Headers" 
                :widgets="widgets" 
                :HeaderButtons="Buttons"
                :TotalRecords="TotalRecords"  
                :RenderRowActionMethod="renderActions"
                :ListDataCallBackFunction="GetVirtualUserConfiguration" 
                :SortExp="SortExp" 
                :SortBy="SortBy" 
                :NorecordfoundText="$t('NoRecordfound')"  
                v-on:PagerButtonClick="pagerMethod"
                v-on:HeaderButtonClick="commonHeaderButtonClick" 
                v-on:ActionButtonClick="actionButtonClick"
                v-on:SortdataButtonClick="sortdata">
                <template v-slot:slotdata="{ data }"> 
                    <template v-if="data.column.COLUMN_NAME == 'VIRTUAL_USER_TRACK_ONLY'">
                        <span v-if="data.row.VIRTUAL_USER_TRACK_ONLY == false"> {{$t("No")}}</span>
                        <span v-else>{{$t("Yes")}}</span>
                    </template>                    
                </template>
            </tg-list>  
        </div>
       <AddVirtual v-if="VirtualListingSachema" :ProjectName="ProjectName"></AddVirtual>
    </section>
</template>
<script>
import AddVirtual from '../../../../components/Modal/AddVirtual.vue';
import DataService from '../../../../services/DataService';
import Schema from './VirtualListingSachema';
export default {
  components: { AddVirtual }, 
   
    props: {
        projectId: {
            type: Number,
            required: true
        }
    },
    data() {
        return {
            TotalRecords: 0,
            noRecord: false,
            isLoading: false,
            CompanyId: null,
            PageSize: 10,
            statusId: '',
            PageNumber: 1,
            isPaged: 1,
            TotalPages: 0,
            widgets: [],
            SortBy: '',
            SortExp: '',
            ProjectName:'',
            taskId: '',
            listActions: Schema.listActions,
            Headers: Schema.TableHeader,
            ListingData: [],
            searchCondition: '',
            Buttons: Schema.buttons,
            IsEditTeamShow: false,
            VirtualListingSachema: false
        };
    },
    created: async function() {   
        this.CompanyId = this.GetUserInfo.CompanyId;
        this.userId = this.GetUserInfo.ID;
        this.GetVirtualUserConfiguration();
    },
    methods: {      
        renderActions: function () {
            var self = this;
            let rtnActionArray = [];
            self.listActions.forEach(actionItem => {
                let action = { ...actionItem };
                switch (action.title) {
                    case 'Delete':
                        action.isVisible =  true;
                        break;             
                    default: {
                        action.isVisible = true;
                    }
                }
                rtnActionArray.push(action);
            });
            return rtnActionArray;
        },
        pagerMethod: function (value) {
            this.PageSize = value.PageSize;
            this.PageNumber = value.PageNumber;
            this.GetVirtualUserConfiguration();
        },
        actionButtonClick: function (callbackfunction, item) {            
            switch (callbackfunction) {              
                case 'DeleteClientData':
                    this.RemoveVirtualUser(item.PROJECT_VIRTUAL_USER_ID);
                    break; 
            }
        },
        commonHeaderButtonClick: async function(event) {
            var vm=this;
            switch (event.callbackfunction) {
                case "VirtualListingSachema":
                    vm.Add(0);
                    break;
                case "EditProject":
                    vm.EditProject();
                    break;
                case "BackToList":
                    this.BackToList();
                    break;
            
            }
        },
        Add: function() {
            var vm=this;
            vm.VirtualListingSachema = true;
        },
        sortdata: function (s) {
            var SortDir = "sort tb_headerSortDown";
            this.SortBy = s;
            if (s === this.SortBy) {
                if (this.SortExp == "") {
                    this.SortExp = "ASC";
                    SortDir = "sort tb_headerSortDown";
                }
                else if (this.SortExp == "ASC") {
                    this.SortExp = "DESC";
                    SortDir = "sort tb_headerSortUp";
                }
                else {
                    this.SortExp = "ASC";
                    SortDir = "sort tb_headerSortDown";
                }
            }
            this.GetVirtualUserConfiguration();
            $("#" + s + '  span:first-child').attr("class", SortDir);
        },
        RemoveVirtualUser: function (id) {            
            var vm = this;           
            vm.isLoading = true;
            if (id >0) {
                vm.confirmR(vm.$t("ConfirmDelete"), true, (vm.$t("Delete") + "  " + vm.$t("Group")), function () {                   
                    var postJSON = {
                        ids: id,
                        moduleName: "PROJECT",
                        refCode: 'TALYGEN_PROJECT_VIRTUAL_USER'
                    };                          
                    var objectPostString = JSON.stringify(postJSON);            
                    DataService.CommonCommonDelete(objectPostString).then(function (response) {
                        vm.isLoading = false;                        
                        if (response.status == 200) {
                            vm.ShowAlert(vm.$t('DeletedSuccess', [vm.$t('Virtual user')]), "success", true, vm.$t("Alert"));
                            vm.GetVirtualUserConfiguration();
                        }
                        else {
                            vm.ShowAlert(vm.$t('DeletedError', [vm.$t('Virtual user')]), "Success", true, vm.$t("Alert"));
                        }
                    });
                });
            }
            else {
                vm.ShowAlert(vm.$t("Selectanyrecordtodelete"));
            }
            vm.isLoading = false;
        }, 
        GetVirtualUserConfiguration: async function () {
            const params = `projectId=${this.projectId}&search=&sortBy=${this.SortBy}&sortExp=${this.SortExp}&pageSize=${this.PageSize}&pageNum=${this.PageNumber}`;
            try {
                const response = await DataService.VirtualUserConfigurationListing(params);
                if (response.data.result.data.length > 0) {
                    this.ListingData = response.data.result.data;
                    this.TotalRecords = response.data.result.data[0].TOTAL_RECORDS;
                    this.TotalPages = Math.ceil(this.TotalRecords / this.PageSize);
                } else {
                    this.TotalRecords = 0;
                    this.TotalPages = 1;
                    this.ListingData = [];
                }
            } catch (error) {
                console.error("Error fetching virtual listing:", error);
            }
        },
        BackToList: function () { 
            this.$router.push({ name: 'ProjectList' });
        },
        EditProject: function () {
            var vm = this;
            vm.$emit('EditProject');
        }    
     
    }
};
</script>

