<template>
    <section>
        <div id="modalEditTask" role="dialog" class="modal my-popups right fade rightmodalcssfixs ">
            <div role="document" class="modal-dialog mw-800">
                <div class="modal-content">
                    <div class="modal-header mheader-user">
                        <button type="button" class="close" v-on:click="CloseTemplate()"><i class="fa fa-times"
                                aria-hidden="true"></i></button>
                        <h4 class="modal-title" id="myModalLabel">
                            <span>{{ $t('EditEpic') }}</span>
                        </h4>
                    </div>
                    <loader :is-visible="isLoading"></loader>
                    <div class="modal-body">
                        <dynamic-form ref="dynamicform" lang="en" :buttons="commentButtons" :schema="FormSchema"
                            v-on:OnSubmit="SaveEpic">
                            <template v-slot:tgslot-EpicDescription="{ data }">
                                <ckeditor :editor="editor"  v-model="EpicDescriptionn"></ckeditor>
                            </template>
                        </dynamic-form>
                        <div class="collapsible-section mt-2" v-if="IsShowSubTask">
                            <div class="collapsible-header" @click="toggleCollapseSubTask()">
                                <h3>
                                    {{ $t("Task") }}
                                    ({{ Tasks && Tasks.length > 0
                                        ? Tasks[0].CompleteTask + '/' + Tasks.length + ' ' + $t('Completed')
                                        : '0'
                                    }})
                                    <small class="float-right font-14"><em
                                            :class="isOpenSubTask ? 'fa fa-chevron-down' : 'fa fa-chevron-left'"></em></small>
                                </h3>
                            </div>
                            <div class="collapsible-content" v-show="isOpenSubTask">
                                <ul class="subtask-list" v-for="(item,index) in Tasks" :key="index">                                 
                                        <li class="subtask-item p-3">                                         
                                                <em v-if="item.status_name == 'Completed' || item.status_name == 'Closed'" class="fa fa-check-circle text-success font-20 mr-2" ></em>
                                                <div v-if="item.task_type=='T'" class="text-primary fa fa-check-square"></div>
                                                <div v-if="item.task_type=='S'" class="text-success fa fa-film"></div>
                                                <span href="javascript:void(0);" class="subtask-link mt-1 ml-2" :style="{ textDecoration: item.status_name === 'Completed' || item.status_name == 'Closed' ? 'line-through' : 'none ' , cursor: 'pointer'}">
                                                    {{ item.task_number }} {{ item.task_name }}
                                                </span>
                                                <span class="float-right ml-3">
                                                    <em class="fa fa-trash-o text-danger font-18" aria-hidden="true"
                                                        @click="DeleteTaskData(item.task_id)"></em>
                                                </span>
                                        </li>
                                    </ul>
                                    <div v-if="Tasks.length == 0"
                                        class="text-center text-danger no_records no-record border p-2 mb-2">
                                        {{ $t('NoRecordfound')}}
                                    </div>
                                <div class="add-subtask d-flex align-items-center p-3">
                                    <div class="d-inline">
                                        <div class="checklist-icon mt-1 mr-2 d-flex">
                                            <div v-if="IsTask" class="text-primary fa fa-check-square mt-1"></div>
                                            <div v-if="IsStory" class="text-success fa fa-film"></div>
                                            <a class="dropdown pl-2">
                                                <em id="dropdownMenu2" data-toggle="dropdown" aria-haspopup="true"
                                                    aria-expanded="false" aria-hidden="true"
                                                    class="fa fa-angle-down"></em>
                                                <div aria-labelledby="dropdownMenu2" class="dropdown-menu" style="">
                                                    <button type="button" @click="TypeCheck('T')"
                                                        class="dropdown-item"><em
                                                            class="fa fa-check-square text-primary pr-2"></em>{{
                                                        $t('Task') }}</button>
                                                    <button type="button" @click="TypeCheck('S')"
                                                        class="dropdown-item"><em
                                                            class="fa fa-film text-success pr-2"></em>{{ $t('Story')
                                                        }}</button>
                                                </div>
                                            </a>
                                        </div>
                                    </div>
                                    <input type="text" class="subtask-input form-control" placeholder="Add a new Story/Task"
                                        v-model="txtAddSubTask" @keydown.enter="SavetxtAddSubTask"
                                        >
                                    <button class="btn btn-success" @click="SavetxtAddSubTask"
                                        :class="{ 'disabled': txtAddSubTask == '' }"
                                        :disabled="txtAddSubTask == ''">{{ $t('Add') }}</button>
                                </div>
                            </div>
                        </div>
                        <div class="collapsible-section">
                            <div class="collapsible-header" @click="toggleCollapseTaskComment()">
                                <h3>{{ $t("TaskComments") }} ({{ TaskCommentDetails.length }})
                                    <small class="float-right font-14"><em
                                            :class="isOpenTaskComment ? 'fa fa-chevron-down' : 'fa fa-chevron-left'"></em></small>
                                </h3>
                            </div>
                            <div class="collapsible-content p-2 float-left w-100 darkfix" v-show="isOpenTaskComment">
                                <div class="comment-form float-left w-100 mb-0">
                                    <textarea class="comment-textarea" placeholder="Add a comment..."
                                        v-model="TaskComment" @keydown.enter="SaveTaskComment"></textarea>
                                    <button type="submit" class="comment-submit float-right mb-3"
                                        :class="{ 'disabled': TaskComment == '' }" :disabled="TaskComment == ''"
                                        @click="SaveTaskComment">{{ $t('PostComment') }}</button>
                                </div>

                                <div class="col-lg-12 mb-3 p-0 float-left">
                                    <div class="heading-border mt-2">
                                        <h5 class="h5"><span>Comments</span></h5>
                                    </div>
                                </div>
                                <ul class="comment-list" v-for="item in TaskCommentDetails" :key="item.id">
                                    <li class="comment-item">
                                        <div class="comment-header">
                                            <div class="comment-avatar">{{ getInitials(UserName) }}</div>
                                            <span class="comment-user">{{ UserName }}</span>
                                            <span class="comment-time">{{ $d(new Date(item.created_at)) }}</span>
                                            <span class="flexauto"><a href="javascript:;" class="float-right font-18"
                                                    @click="DeleteComment(item.id)"><em aria-hidden="true"
                                                        class="fa fa-trash-o text-danger"></em></a>
                                            </span>
                                        </div>
                                        <div class="comment-text decoration">
                                            {{ item.comment }}
                                        </div>
                                    </li>
                                </ul>
                                <div v-if="TaskCommentDetails.length == 0"
                                        class="text-center text-danger no_records no-record">
                                        {{ $t('NoRecordfound')}}
                                </div>
                            </div>
                        </div>
                    </div>

                </div>
            </div>
        </div>
    </section>
</template>
<script>
import DataService from '../../services/DataService';
export default {
    props: {
        EpicDeatils: {
            type: Object,
            required: true
        }
    },
    // watch: {
    //     EpicDeatils: function (val) {
    //         debugger;
    //         if (val != null) {

    //             this.EpicDescriptionn = val.EpicDescription;

    //         }
    //     }
    // },

    data() {
        return {
            isLoading: false,
            FormSchema: [
                {
                    layoutType: "four",
                    group_name: 'General Information',
                    Data: [
                        {
                            astype: "TextField",
                            label: this.$t('EpicName'),
                            name: "EpicName",
                            value: "",
                            visibility: true,
                            validationRules: { "required": true, max: 4000 },
                        },
                        {
                            astype: "DateField",
                            label: this.$t('Start Date'),
                            name: "planned_start_date",
                            value: "",
                            visibility: true,
                            placeholder: this.$t("Start Date"),
                            validationRules: {
                                "required": false
                            },
                            config: { mode: "date", format: "M/D/YYYY" }
                        },
                        {
                            astype: "DateField",
                            label: this.$t("End Date"),
                            name: "planned_end_date",
                            value: "",
                            placeholder: this.$t("End Date"),
                            visibility: true,
                            validationRules: {
                                required: false,
                            },
                            config: { mode: "date", format: "M/D/YYYY" }
                        },
                        {
                            astype: "SelectField",
                            label: this.$t('Status'),
                            visibility: true,
                            name: "StatusId",
                            value: "1001",
                            validationRules: { "required": false, max: 4000 },
                            config: { options: [] }
                        }
                    ]
                },
                {
                    layoutType: "single",
                    group_name: 'Epic Details',
                    Data: [
                        {
                            astype: "SlotField",
                            label: this.$t('Epic Description'),
                            name: "EpicDescription",
                            visibility: true,
                            value: "",
                            placeholder: "",
                            validationRules: {
                                "required": false
                            }
                        }
                    ]
                }
            ],
            commentButtons: [
                {
                    type: "submit",
                    class: "btn btn-success",
                    text: "<i class='fa fa-save pr-2'></i>Save",
                    isVisible: true
                },
                {
                    type: "button",
                    class: "btn btn-danger",
                    text: "<i class='fa fa-close pr-2'></i>Cancel",
                    onClick: this.CloseTemplate,
                }
            ],
            editor: this.CLASSIC_EDITOR,
            EpicDescriptionn: '',
            IsShowSubTask: true,
            isOpenSubTask: true,
            Tasks: [],
            txtAddSubTask: '',
            IssueTypeId: 'T',
            IsTask: true,
            IsStory: false,
            IsPriority: null,
            isOpenTaskComment: true,
            TaskCommentDetails: [],
            TaskComment: '',
            UserName:null

        }
    },
    computed: {
        getEpicDetails() {
            return this.EpicDeatils;
        },        
    },
    created() {
        this.UserName = this.GetUserInfo.Name;
        this.bindEpicDetails();
        this.StatusDropdown();
        this.GetProjectPriority();
        this.TaskList();
        this.GetTaskComment();
    },
    methods: {
        TaskList: function () { 
            var vm = this;
            var url = `SprintId=${vm.EpicDeatils.id}&Type=TimeLineTask&ProjectId=${vm.$route.params.projectId}`;
            DataService.GetSubTaskDetails(url).then((response) => {
                if (response && response.data.result.Data.length > 0) { 
                    vm.Tasks = response.data.result.Data;
                    vm.Tasks.forEach(task => {
                    let completedCount = vm.Tasks.filter(
                        t => t.status_name === "Closed" || t.status_name === "Completed"
                    ).length;
                    task.CompleteTask = completedCount;
                });
                }
               else
               {
                vm.Tasks =[];
               }
            })
        },
        GetTaskComment: function () {
            var vm = this;
            let TaskId = vm.EpicDeatils.id;
            let ProjectId = vm.$route.params.projectId;
            var url = `TaskId=${TaskId}&ProjectId=${ProjectId}`;
            DataService.GetComments(url).then((response) => {
                if (response && response.data.result.Data.length > 0) {
                    vm.TaskCommentDetails = response.data.result.Data;
                }
                else
                {
                    vm.TaskCommentDetails =[];
                }
            })
        },
        SaveTaskComment: function () {          
            var vm = this;
            let Commant = vm.TaskComment;
            if(Commant==""){
                return false;
            }
            var url = `Comment=${Commant}&TaskId=${vm.EpicDeatils.id}&ProjectId=${vm.$route.params.projectId}`;
            DataService.AddCommentToTask(url).then((response) => {                
                if (response && response.data.status == "Success") {
                    vm.ShowAlert(vm.$t('AddedSuccess', [vm.$t('Comment')]), "success", true, vm.$t("Alert"));
                    vm.TaskComment = "";
                    vm.GetTaskComment();
                    vm.isLoading = false;

                } else {
                    vm.ShowAlert(vm.$t("UnknownErrorOccur"), "failure", true, vm.$t('Alert'));
                }
            })
        },
        GetProjectPriority() {
            var url = `id=&moduleName=PROJECT&type=PRIORITY&search=&refId=`;
            DataService.GetDDLData(url).then((response) => {
                if (response.status == 200) {
                    if (response.data.DATA != undefined || response.data.DATA != null) {
                        if (response.data.DATA.length > 0) {
                            this.PriorityData = response.data.DATA;
                            var Pdata = this.PriorityData.filter(item => item.name === 'Low');
                            if (Pdata.length > 0) {
                                this.IsPriority = Pdata[0].value;
                            }
                        }
                    }
                }
            })
        },
        TypeCheck(val) {
            var ths = this;
            if (val == 'T') {
                ths.IsTask = true;
                ths.IsStory = false;
                ths.IssueTypeId = 'T';
            } else {
                ths.IsStory = true;
                ths.IsTask = false;
                ths.IssueTypeId = 'S';
            }
        },
        toggleCollapseSubTask() {
            this.isOpenSubTask = !this.isOpenSubTask;
        },
        toggleCollapseTaskComment() {
            this.isOpenTaskComment = !this.isOpenTaskComment;
        },
        getInitials(name) {
            if (!name) return "";
            return name
                .split(" ")
                .filter(w => w.trim().length > 0)
                .map(w => w[0].toUpperCase())
                .join("");
        },
        StatusDropdown: function () {
            var vm = this;
            var url = `langCode=en&companyId=${vm.CompanyId}&statusType=Project&hasGlobal=true`
            DataService.StatusListing(url).then((response) => {
                if (response.data != null && response.data != "") {
                    response.data.result.data.forEach(element => {
                        var obj = {
                            name: element.STATUS,
                            value: element.STATUS_ID
                        }
                        vm.FormSchema[0].Data[3].config.options.push(obj);
                        vm.$refs.dynamicform.UpdateKeyValue();
                    });

                }
            });
        },
        CloseTemplate() {
            setTimeout(function () {
                $("#modalEditTask").modal("hide");
                $("body").removeClass("modal-open");
                $(".modal-backdrop").remove();
            }, 1000);
            this.$emit('close');
        },
        bindEpicDetails() {
            var ths = this;
            if (ths.EpicDeatils) {
                ths.FormSchema[0].Data[0].value = ths.EpicDeatils.name;
                ths.FormSchema[0].Data[1].value = ths.EpicDeatils.start;
                ths.FormSchema[0].Data[2].value = ths.EpicDeatils.end;
                ths.FormSchema[0].Data[3].value = ths.EpicDeatils?.status || 0;
                ths.EpicDescriptionn = ths.EpicDeatils?.descripton || '';
            }
        },
        SaveEpic() {
            var ths = this
            try {
                ths.isLoading = true;
                var obj = {
                    EpicId: ths.EpicDeatils.id,
                    Project_id: ths.$route.params.projectId,
                    EpicTitle: ths.FormSchema[0].Data[0].value,
                    EpicStart: ths.FormSchema[0].Data[1].value,
                    EpicEnd: ths.FormSchema[0].Data[2].value,
                    StatusId: ths.FormSchema[0].Data[3].value,
                    EpicDescription: ths.EpicDescriptionn
                }
                DataService.SaveEpic(JSON.stringify(obj)).then(response => {
                    ths.isLoading = false;
                    if (response.data.result.DATA.length > 0) {
                        if (response.data.result.DATA[0].VALUE == 'UPDATE') {
                            ths.ShowAlert(ths.$t('UpdatedSuccess', [ths.$t('Epic')]), "success", true, ths.$t("Alert"));
                        } else {
                            ths.ShowAlert(ths.$t('AddedSuccess', [ths.$t('Epic')]), "success", true, ths.$t("Alert"));
                        }
                        ths.$emit('ReloadTimeline',obj);
                        ths.CloseTemplate();
                    } else {
                        ths.ShowAlert(ths.$t("UnknownErrorOccur"), "failure", true, ths.$t('Alert'));
                    }
                })
            } catch (error) {
                console.log("error message", error);
            }
        },
        SavetxtAddSubTask() {
            var ths = this;
            if (!ths.txtAddSubTask || ths.txtAddSubTask.trim() === "") {
                return false;
            }
            var obj = {
                BackLogId: 0,
                Project_id: ths.$route.params.projectId,
                Subject: ths.txtAddSubTask,
                IssueTypeId: ths.IssueTypeId,
                SprintId: null,
                PriorityId: ths.IsPriority,
                StatusId: 1001,
                UserId: null,
                BackLogDescription: '',
                IsBacklog: false,
                EpicId: ths.EpicDeatils.id,
                ParentId: null,
                Type: 'TASK'
            }
            DataService.SaveBackLog(JSON.stringify(obj)).then(function (response) {
                ths.isLoading = false;
                if (response.data.result.DATA.length > 0) {
                    if (response.data.result.DATA[0].VALUE == 'DUPLICATE') {
                        if (ths.IssueTypeId == 'T') {
                            ths.ShowAlert(ths.$t('AlreadyExists', [ths.$t('Task')]), "warning", true, ths.$t("Alert"));
                        } else {
                            ths.ShowAlert(ths.$t('AlreadyExists', [ths.$t('Story')]), "warning", true, ths.$t("Alert"));
                        }
                    } 
                    else {
                        if (ths.IssueTypeId == 'T') {
                            ths.ShowAlert(ths.$t('AddedSuccess', [ths.$t('Task')]), "success", true, ths.$t("Alert"));
                        } else {
                            ths.ShowAlert(ths.$t('AddedSuccess', [ths.$t('Story')]), "success", true, ths.$t("Alert"));
                        }                        
                        ths.TaskList();
                        ths.txtAddSubTask = '';
                        ths.$emit('ReloadTimeline');


                    }
                } else {
                    ths.ShowAlert(ths.$t("UnknownErrorOccur"), "failure", true, ths.$t('Alert'));
                }
            });
        },
        DeleteComment: function (CommentId) {
            var vm = this;
            vm.confirmR(vm.$t("ConfirmDelete"), true, (vm.$t("Delete") + "  " + vm.$t("Project")), function () {
                var postJSON = {
                    ids: CommentId,
                    moduleName: 'Project',
                    subModuleCode: "Project_Detail",
                    refCode: 'TASK_COMMENT',
                    refId: null
                };
                var objectPostString = JSON.stringify(postJSON);
                DataService.CommonCommonDelete(objectPostString).then(function (response) {
                    if (response.data[0].Status == "Success") {
                        vm.ShowAlert(vm.$t('DeletedSuccess', [vm.$t('Comment')]), "success", true, vm.$t("Alert"));
                        vm.GetTaskComment();
                        vm.isLoading = false;
                    }
                    else {
                        vm.ShowAlert(vm.$t('DeleteError'), "warning", true, vm.$t('Alert'));
                    }
                });
            });
        },
        DeleteTaskData: function (id) {            
            var vm = this;          
            vm.isLoading = true;        
            if (id != null) {
                vm.confirmR(vm.$t("ConfirmDelete"), true, (vm.$t("Delete") + "  " + vm.$t("Group")), function () {                   
                    var postJSON = {
                        ids: id,
                        moduleName: "PROJECT",
                        refCode: "TALYGEN_GLOBAL_TASK"
                    };
                    var TaskType=vm.IssueTypeId == 'T'?'Task':'Story';
                    var objectPostString = JSON.stringify(postJSON);
                    DataService.CommonCommonDelete(objectPostString).then(function (response) {                        
                        vm.isLoading = false;
                        if (response.data.length>0) {
                            if(response.data[0].Status=='Success'){
                                if(response.data[0].Code=='TASK_ASSIGN'){
                                    vm.ShowAlert(vm.$t('proceedingwithdeletion', [vm.$t(TaskType)]), "failure", true, vm.$t("Alert"));
                                }else{
                                    vm.ShowAlert(vm.$t('DeletedSuccess', [vm.$t(TaskType)]), "success", true, vm.$t("Alert"));
                                    vm.TaskList();
                                    vm.$emit('ReloadTimeline');
                                }                                        
                            } 
                            else {
                                vm.ShowAlert(vm.$t('DeletedError', [vm.$t(TaskType)]), "failure", true, vm.$t("Alert"));
                            }
                        }
                        else {
                            vm.ShowAlert(vm.$t('DeletedError', [vm.$t(TaskType)]), "failure", true, vm.$t("Alert"));
                        }
                    });
                });
            }
            else {
                vm.ShowAlert(vm.$t("Selectanyrecordtodelete"));
            }
            vm.isLoading = false;
        },
    }
}
</script>

<style>
.rightmodalcssfixs .comment-submit{background: #33ab4e!important;}
.rightmodalcssfixs .subtask-input{padding: 6px 14px!important;}
</style>