<script>
import AIAnalysisPanel from './AIAnalysisPanel.vue'
import DataService from '../../../../services/DataService'
import VueApexCharts from 'vue-apexcharts';
import ViewAllTeam from '../../../../components/Modal/ViewAllTeam.vue';
import ProjectDeatilsOverView from '../../../../components/Modal/ProjectDeatilsOverView.vue';

export default {
    name: 'BugTrackingOverView',
    components: { AIAnalysisPanel, VueApexCharts, ViewAllTeam, ProjectDeatilsOverView },
    props: {
        projectId: {
            type: Number,
            require: true,
        },
        checkPmUser: {
            type: Boolean,
            require: true
        },
        NewTabName: {
            type: String,
            require: true
        },
        TabsArray: {
            type: Array
        },
        Template_Name: {
            type: String,
            require: true
        }
    },
    data() {
        return {
            IsAIAnalysis: false,
            isViewAllTeam: false,
            isProjectDeatil: false,
            AIAnalysis: null,
            Key: 0,
            ProjectId: 0,
            CompanyId: 0,
            UserId: 0,
            logged_usertype: '',
            TimeZone: '',
            CurrencyCode: '',
            ProjectDetailData: [],
            showMoreProjectName: {},
            showMoreDescription: {},
            limit: 50,
            chartKey: 0,
            seriess: [
                { name: "Total Bugs", data: [] },
                { name: "Inprogress Bugs", data: [] },
                { name: "Completed Bugs", data: [] },
                { name: "Closed Bugs", data: [] }
            ],
            chartOptionss: {
                chart: {
                    type: "line",
                    height: 400,
                    toolbar: {
                        show: false
                    }
                },
                colors: ["#FF4560", "#00E396", "#008FFB", "#775DD0"],
                stroke: {
                    width: 3,
                    curve: "smooth"
                },
                markers: {
                    size: 4
                },
                xaxis: {
                    categories: [],
                    title: {
                        text: "Bugs Trend (Days Wise)"
                    }
                },
                yaxis: {
                    title: {
                        text: "Bug Count"
                    }
                },
               legend: {
                    position: 'bottom',
                    fontSize: '15px',
                    itemMargin: {
                        horizontal: 5,
                        vertical: 50
                    },
                },
                tooltip: {
                    shared: true,
                    intersect: false
                }
            },
            seriesss: [
                { name: "Open Bugs", data: [] },
                { name: "Inprogress Bugs", data: [] },
                { name: "Completed Bugs", data: [] },
                { name: "Closed Bugs", data: [] }
            ],
            chartOptionsss: {
                chart: {
                    type: "bar",
                    height: 350,
                    toolbar: {
                        show: false
                    },
                    stacked: false
                },
                colors: ["#FF4560", "#00E396", "#008FFB", "#775DD0"],
                plotOptions: {
                    bar: {
                        horizontal: false,
                        columnWidth: "55%",
                        dataLabels: {
                            position: "top"
                        }
                    }
                },
                dataLabels: {
                    enabled: false
                },
                xaxis: {
                    categories: [],
                    title: {
                        text: "Bugs Trend (Users Wise)"
                    }
                },
                yaxis: {
                    title: {
                        text: "Bug Count"
                    }
                },
                 legend: {
                    position: 'bottom',
                    fontSize: '15px',
                    itemMargin: {
                        horizontal: 5,
                        vertical: 30
                    },
                },
                tooltip: {
                    shared: true,
                    intersect: false
                },
                fill: {
                    opacity: 1
                }
            },
            seriesComponent: [],
            chartOptionComponent: {
                chart: { type: 'donut', height: 350 },
                labels: [],
                plotOptions: {
                    pie: {
                        startAngle: 0,
                        endAngle: 360,
                        donut: {
                            size: '70%',
                            labels: {
                                show: true,
                                total: {
                                    show: true,
                                    label: 'Total',
                                    fontSize: '16px',
                                    fontWeight: 600,
                                    formatter: (w) => {
                                        const total = w.globals.seriesTotals.reduce((a, b) => a + b, 0);
                                        return total;
                                    }
                                }
                            }
                        },
                    },
                },
                legend: {
                    position: 'bottom',
                    fontSize: '15px',
                    itemMargin: {
                        horizontal: 5,
                        vertical: 30
                    },
                },
                tooltip: {
                    y: {
                        formatter: (val) => `${val} Bugs`
                    }
                }
            },
            environments: [],
            GlobalBudget:0,
            chartOptions: {
                chart: { type: 'donut', height: 350 },
                labels: [],
                plotOptions: {
                    pie: {
                        startAngle: 0,
                        endAngle: 360,
                        donut: {
                            size: '70%',
                            labels: {
                                show: true,
                                label: 'Total',
                                fontSize: '20px',
                                color: '#333',
                                formatter: (w) => {
                                    return this.GlobalBudget;
                                },
