<template>
  <div class="my-popups">
    <loader :is-visible="isLoading"></loader>
    <div class="modal d-block">
      <div class="modal-dialog modal-dialog-centered">
        <div class="modal-content">
          <div class="modal-header theme-primary partition-full  d-flex">
            <h4 class="modal-title">{{ $t('Add') }} {{ $t('Priority') }}</h4>
            <button type="button" class="close" v-on:click="ReladSocialMedia">
              <em class="fa fa-times" aria-hidden="true"></em>
            </button>
          </div>
          <div class="modal-body">
            <dynamic-form lang="en" :buttons="buttons" :schema="FormSchema" ref="AssignTagForm"
              :mandatorytext='MandatoryString' v-on:OnSubmit="OnSubmit"></dynamic-form>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>
<script>
import DataService from '../../../../services/DataService';
export default {
  props: {
    SocialMediaId: {
      type: Number
    }
  },
  data() {
    return {
      isLoading: false,
      MandatoryString: 'Fields marked with an asterisk (*) are mandatory.',
      FormSchema: [
        {
          layoutType: "triple",
          Data: [
            {
              astype: "TextField",
              label: this.$t('Name'),
              name: "Name",
              value: "",
              placeholder: this.$t('Select Name'),
              validationRules: { "required": true },
            },
            {
              astype: "TextField",
              label: this.$t('Link'),
              name: "Link",
              value: "",
              placeholder: this.$t('Select Link'),
              validationRules: { "required": true, url: true },
            },
            {
              astype: "SelectField",
              label: this.$t('Icon'),
              name: "Icon",
              value: "",
              config: {
                options: [{ value: '&#xf09a',class:"fa fa-input", name: 'Facebook' }, { value: '&#xf099',class:"fa fa-input", name: 'Twitter' }, { value: '&#xf16d',class:"fa fa-input", name: 'Instagram' }, { value: '&#xf0e1',class:"fa fa-input", name: 'Linkedin' }]
              },
              placeholder: "",
              validationRules: {
                "required": true
              },
              disabled: false,
            }
          ]
        }
      ],
      buttons: [
        {
          type: "submit",
          class: "btn btn-success",
          text: "<i class='fa fa-save pr-2'></i>Save",
          isVisible: true
        },
        {
            type: "button",
            class: "btn btn-danger",
            text: "<i class='fa fa-close pr-2'></i>Cancel",
            onClick: this.ReladSocialMedia,
        },
      ],     
      CompanyId: 0,
      projectId: 0,
      userId: 0,
    }
  },
  created: function () {    
    this.CompanyId = this.GetUserInfo.CompanyId;
    this.projectId = parseInt(this.$route.params.projectId);
    this.userId = this.GetUserInfo.ID;
    if (this.SocialMediaId > 0) {
        this.GetSocialMediaDetails();
    }
  },
  methods: {
    OnSubmit: function () {
      var ths = this;
      ths.isLoading = true;
      var SocialMediaObj = {
        ID: ths.SocialMediaId,
        NAME: ths.FormSchema[0].Data[0].value,
        LINK: ths.FormSchema[0].Data[1].value,
        ICON: ths.FormSchema[0].Data[2].value,
        REFERENCESOURCE: 'EM_EVENT',
        REFERENCEID: ths.projectId,
        COMPANY_ID: ths.CompanyId,
        USER_ID: ths.userId,
        STATUS: 1001
      };
      var objectPostString = JSON.stringify(SocialMediaObj);
      DataService.SaveSocialMedia(objectPostString).then((response) => {
        ths.isLoading = false;
        if (response.data.status == "Success") {
          if (response.data.result == -1) {
            ths.ShowAlert(ths.$t('UpdatedSuccess', [ths.$t('SocialMedia')]), "success", true, ths.$t("Alert"));
          } else {
            ths.ShowAlert(ths.$t('AddedSuccess', [ths.$t('SocialMedia')]), "success", true, ths.$t("Alert"));
          }          
          ths.ReladSocialMedia();          
        } else {
          ths.ShowAlert(ths.$t("Error"), "failure", ths.$t('Alert'));
        }
      });
    },
    ReladSocialMedia() {
      this.$emit('ReladSocialMedia');
    },    
    GetSocialMediaDetails(){
        this.isLoading = true;
        const params = `socialMediaId=${this.SocialMediaId}&referenceId=${this.projectId}&referenceSource=EM_EVENT`;
        DataService.GetSocialMediaDetails(params).then(response => {  
            this.isLoading=false;              
            const data = response.data.result.data;            
            if (data.length > 0) {
                this.FormSchema[0].Data[0].value = response.data.result.data[0].social_media_name;
                this.FormSchema[0].Data[1].value = response.data.result.data[0].social_media_link;
                this.FormSchema[0].Data[2].value = response.data.result.data[0].social_media_icon;
            }
        });
    }
  }
}
</script>