<template>
    <div class="my-popups">
        <loader :is-visible="isLoading"></loader>
        <div class="modal d-block">
            <div class="modal-dialog modal-dialog-centered">
                <div class="modal-content">
                    <div class="modal-header theme-primary partition-full  d-flex">
                        <h4 class="modal-title">{{ $t('viewallmilestones') }}</h4>
                        <button type="button" class="close" v-on:click="CloseMileStone()">
                            <em class="fa fa-times" aria-hidden="true"></em>
                        </button>
                    </div>
                    <div class="modal-body">
                        <tg-list  
                            ref="tgList" 
                            :listType="['List']" 
                            :IsShowAction="false" 
                            :showCheckBox="false" 
                            ModuleName="PROJECT" 
                            SubModuleCode="Client" 
                            IdentityColumn="MILESTONE_ID" 
                            :HeaderText="$t('ProjectMilestones')"
                            :ListData="ListingData" 
                            :HeaderData="Headers" 
                            :widgets="widgets" 
                            :TotalRecords="TotalRecords"  
                            :RenderRowActionMethod="renderActions"
                            :ListDataCallBackFunction="MilestoneListingSchema" 
                            :SortExp="SortExp" 
                            :SortBy="SortBy" 
                            :NorecordfoundText="$t('NoRecordfound')"  
                            v-on:PagerButtonClick="pagerMethod"
                            v-on:HeaderButtonClick="commonHeaderButtonClick" 
                            v-on:SortdataButtonClick="sortdata">
                            <template v-slot:slotdata="{ data }">
                                <template v-if="data.column.COLUMN_NAME == 'STATUS_NAME'"> 
                                    <span v-bind:class="getStatusClass(data.row.STATUS_NAME)">
                                        {{ data.row.STATUS_NAME}}
                                        </span>                       
                                </template>
                                <template v-if="data.column.COLUMN_NAME == 'MILESTONE_PROGRESS'">
                                <div class="time" v-if="data.row.MILESTONE_PROGRESS != null">
                                                <div :class="'c100 small green p' + data.row.MILESTONE_PROGRESS">
                                                    <span>{{ data.row.MILESTONE_PROGRESS }}%</span>
                                                    <div class="slice">
                                                        <div class="bar"></div>
                                                        <div class="fill"></div>
                                                    </div>
                                                </div>
                                            </div>
                                    </template>    
                                    <template v-if="data.column.COLUMN_NAME == 'DUE_DATE'">
                                <span :title=" $options.filters.formatDate(data.row.DUE_DATE)">
                                    {{ $options.filters.formatDate(data.row.DUE_DATE) }}
                                </span>
                            </template>  
                            <template v-if="data.column.COLUMN_NAME == 'DATE_RECEIVED'">
                                <span :title="$options.filters.formatDate(data.row.DATE_RECEIVED)">
                                    {{ $options.filters.formatDate(data.row.DATE_RECEIVED) }}
                                </span>
                            </template> 
                            <template v-if="data.column.COLUMN_NAME == 'AMOUNT_DUE'">
                                <span :title="$n(data.row.AMOUNT_DUE,'currency',$getLocaleByCurrency(Currency))">
                                    {{$n(data.row.AMOUNT_DUE,'currency',$getLocaleByCurrency(Currency)) }}
                                </span>
                            </template> 
                               
                                <template v-if="data.column.COLUMN_NAME == 'ROWNUMBER'">
                                    {{ data.row.ROWNUMBER }} 
                                </template>    
                                <template v-if="data.column.COLUMN_NAME == 'key'">
                                <span>TG-{{ data.row.MILESTONE_ID }}</span>                   
                                </template>                            
                            </template>
                        </tg-list> 
                        <div class="clearfix"></div>
                                <div class="row flex-row-reverse mt-3">
                                    <div class="col-lg-6 text-right">
                                        <a href="javascript:;" class="submitbtn btn btn-danger formbtn"
                                            v-on:click="CloseMileStone()" title="Cancel"><i
                                                class="fa fa-close pr-2"></i>{{ $t('Cancel') }} </a>
                                    </div>
                                </div> 
                    </div>
                </div>
            </div>
        </div>
    </div>
</template>

<script>
import Schema from '../../../src/views/Project/Project/ProjectDetailLeftAllTabs/MilestoneListingSchema';
import DataService from '../../services/DataService';
export default {
     props: {
        projectId: {
            type: Number,
            require: true,
        },
    },
    data() {
        return {
            TotalRecords: 0,
            noRecord: false,
            isLoading: false,
            CompanyId: null,
            PageSize: 10,
            MilestoneID:null,
            milestoneName: '',
            milestoneDesc: '',
            statusId: '',
            PageNumber: 1,
            StatusList:[],
            isPaged: 1,
            TotalPages: 0,
            widgets: [],
            SortBy: '',
            SortExp: '',
            ProjectName:'',
            taskId: '',
            listActions: Schema.listActions,
            Headers: Schema.TableHeader,
            ListingData: [],
            searchCondition: '',
            Buttons: Schema.buttons,
            IsEditTeamShow: false,
            MilestoneListingSchema: false,
            Currency:''
        }
    },
    created: async function() { 
        var ths=this;  
        ths.CompanyId = ths.GetUserInfo.CompanyId;
        ths.userId = ths.GetUserInfo.ID;
        ths.Currency=ths.GetUserInfo.Currency.replace(/[()]/g, '');
        // ths.Headers[11].VISIBLE = false;
        ths.GetStatus(); 
        ths.ProjectOverview();
        await ths.FetchTaskList();
    },   
    methods: {
        ProjectOverview:async function(){
            var vm = this;
            var params = `projectId=${this.projectId}`;
            await DataService.ProjectOverview(params).then(function (response) {                
                   if(response.data != null > 0)
                   {                      
                      vm.ProjectName=response.data.projecT_NAME;
                   }
            });
        },
        getStatusClass(status) {
            let returnClass = '';
            switch (status) {
                case 'Active':
                    returnClass = 'px-2 text-center bg-success text-white d-block';
                    break;
                case 'Inactive':
                    returnClass = 'px-2 text-center bg-danger text-white d-block';
                    break;
                default:
                    returnClass = '';
            }
            return returnClass;
        },
        GetStatus: function(){  
            debugger          
            var vm = this;
            var url = `langCode=en&companyId=${vm.CompanyId}&statusType=Project&hasGlobal=true`;
            DataService.StatusListing(url).then(response => {
                if (response.data.result.data != null && response.data.result.data != "") {
                vm.StatusList = response.data.result.data;                  
            }
            });
        }, 
        renderActions: function (row) {
            var self = this;
            let rtnActionArray = [];
            self.listActions.forEach(actionItem => {
                let action = { ...actionItem };
                switch (action.title) {
                    
                    case 'Edit':
                        action.isVisible = true;
                        break;                      
                    default: {
                        action.isVisible = true;
                    }
                }
                rtnActionArray.push(action);
            });
            return rtnActionArray;
        },
        pagerMethod: function (value) {
            this.PageSize = value.PageSize;
            this.PageNumber = value.PageNumber;
            this.FetchTaskList();
        },
        CloseMileStone() {
            this.$emit('closeMilestone');
        },
        getStatusClass(status) {
            let returnClass = '';
            switch (status) {
                case 'Active':
                    returnClass = 'px-2 text-center bg-success text-white d-block';
                    break;
                case 'Inactive':
                    returnClass = 'px-2 text-center bg-danger text-white d-block';
                    break;
                default:
                    returnClass = '';
            }
            return returnClass;
        },
        FetchTaskList: async function() {   
            this.isLoading = true;
            const params = `projectId=${this.projectId}&milestoneName=${this.milestoneName}&milestoneDesc=${this.milestoneDesc}&statusId=${this.statusId}&projectName=${this.ProjectName}&sortBy=${this.SortBy}&sortExp=${this.SortExp}&pageSize=${this.PageSize}&pageNum=${this.PageNumber}&totalRecords=0`;
            await DataService.MilestoneListing(params).then(response => {
               const data = response.data.result.data;
               if (data.length > 0) {
                    this.ListingData = response.data.result.data;
                    this.TotalRecords = response.data.result.data[0].TOTAL_RECORDS;
                    this.TotalPages = Math.ceil(this.TotalRecords / this.PageSize);
                } else {
                    this.TotalRecords = 0;
                    this.TotalPages = 1;
                    this.ListingData = [];
                }
                this.isLoading = false;
            });
        }
        
    }
}
</script>