<template>
<div class="my-popups">
    <loader :is-visible="isLoading"></loader>
    <div class="modal d-block">
        <div class="modal-dialog modal-dialog-centered mw-800">
            <div class="modal-content">
                <div class="modal-header theme-primary partition-full d-flex">
                    <h4 class="modal-title">Direct Messages</h4>
                    <button type="button" class="close" @click="Close">
                        <em class="fa fa-times" aria-hidden="true"></em>
                    </button>
                </div>
                <div class="modal-body">
                    <div class="card shadow-lg mx-2 my-3" style="max-height: 80vh; display: flex; flex-direction: column;">
                        <div class="card-body">
                            <div class="mb-0 d-lg-block p-2">
                                <div class="input-group customsearchbox">
                                    <input type="text" v-model="searchQuery" placeholder="Search by Name" autocomplete="off" class="form-control searchcustomfilter border-right-0" />
                                    <div class="input-group-append">
                                        <span class="input-group-text bg-transparent bg-white border-left-0">
                                            <i class="fa fa-search"></i>
                                        </span>
                                    </div>
                                </div>
                            </div>
                        </div>
                        <div class="flex-grow-1 overflow-auto">
                            <div class="p-2">
                                <div class="d-flex align-items-center text-muted mb-2">
                                    <em class="fa fa-users mr-2"></em>
                                    Team Members
                                </div>
                                <button v-for="user in users" :key="user.id" class="list-group-item list-group-item-action d-flex align-items-start p-2 mb-1 border-0" type="button" @click="openDirectChat(user.id)">
                                    <div class="position-relative mr-2 mt-3">
                                        <div class="rounded-circle bg-dark text-white d-flex align-items-center justify-content-center" style="width:40px; height:40px;">
                                            {{ getInitials(user.name) }}
                                        </div>
                                        <span class="position-absolute bottom-0 rounded-circle border border-white" :style="{
                                            width: '10px',
                                            height: '10px',
                                            backgroundColor: user.isOnline ? '#10B981' : '#6c757d',
                                            right: '0',
                                            bottom: '0'
                                            }">
                                        </span>
                                    </div>
                                    <div class="flex-grow-1 min-w-0">
                                        <div class="d-flex justify-content-between">
                                            <span class="fw-medium text-truncate">{{ user.name }}</span>
                                            <span class="text-xs text-muted">2 hours ago</span> 
                                        </div>
                                        <div class="text-sm text-muted">{{ user.role }}</div>
                                        <div class="text-sm text-secondary text-truncate mt-1">
                                            {{ user.lastMessage || 'No recent messages' }}
                                        </div>
                                    </div>
                                    <em class="fa fa-eye" style="position: absolute; right: 0; top: 40px;"></em>
                                </button>
                            </div>
                        </div>
                        <div class="card-footer bg-light text-center text-muted text-xs">
                            Direct messages are private conversations between you and another team member
                        </div>
                    </div>
                    <div class="d-flex justify-content-end mt-4">
                        <button type="button" class="btn btn-danger ml-2" @click="Close">Close</button>
                    </div>
                </div>
            </div>
        </div>
    </div>
</div>
</template>

<script>
import DataService from '../../services/DataService';
export default {
    props: {
        projectId: {
            type: Number,
            required: true,
        }
    },
    data() {
        return {
            isLoading: false,
            users: [],
            searchQuery: ''
        }
    },
    created() {       
        this.UserList();
    },
    methods: {
        getInitials(name) {
            if (!name) return '??';
            return name
                .split(' ')
                .map(word => word[0])
                .join('')
                .toUpperCase();
        },
        UserList() {
            var vm = this;
            var url = `projectId=${vm.projectId}`;
            DataService.UserList(url).then(response => {
                if (response.status === 200 && response.data.result.length > 0) {
                    this.users = response.data.result.map(user => ({
                        id: user.user_id,
                        name: user.name,
                        role: user.designation || 'Team Member',
                        lastMessage: user.last_message || '',
                        isOnline: user.is_online || false
                    }));
                } else {
                    this.users = [];
                }
            });
        },
        Close() {
            this.$parent.showDirectMessagePopup = false;
        }
    }
}
</script>