                                    </tbody>
                                </table>
                            </div>
                        </div>
                    </div>
                </div>
                <div class="add-backlog-btn border bg-light float-left w-100" v-if="CheckDisabled()">
                    <a v-if="!IsAddTask" class="p-3 w-100 text-dark float-left" @click="OpenAddTaskPopup()"
                        type="button"><em class="fa fa-plus pr-2"></em>{{
                            $t('Create') }} {{ $t(NewTabName) }}</a>
                    <div class="input-group w-100 pb-3 px-3 pt-3" v-if="IsAddTask">

                        <div class="mr-3">

                            <div class="d-inline">
                                <div class="checklist-icon bg-light position-relative">
                                    <div v-if="IsTask" class="text-primary fa fa-check-square"></div>
                                    <div v-if="IsBug" class="text-danger fa fa-warning"></div>
                                    <div v-if="IsStory" class="text-success fa fa-film"></div>
                                    <a class="dropdown pl-2">
                                        <em class="fa fa-angle-down" id="dropdownMenu2" data-toggle="dropdown"
                                            aria-haspopup="true" aria-expanded="false" aria-hidden="true"></em>
                                        <div class="dropdown-menu" aria-labelledby="dropdownMenu2">
                                            <button @click="TypeCheck('T')" class="dropdown-item" type="button"><em
                                                    class="fa fa-check-square text-primary pr-2"></em>{{ $t('Task')
                                                    }}</button>
                                            <button @click="TypeCheck('B')" class="dropdown-item" type="button"><em
                                                    class="fa fa-warning text-danger pr-2"></em>{{ $t('Issue')
                                                    }}</button>
                                            <button @click="TypeCheck('S')" class="dropdown-item" type="button"><em
                                                    class="fa fa-film text-success pr-2"></em>{{ $t('Story') }}</button>
                                        </div>
                                    </a>
                                </div>
                            </div>

                        </div>
                        <input type="text" @keydown.enter="SaveTask('Task')" v-model="txtTaskTitle"
                            class="form-control px-1 bg-white"
                            :placeholder="`${$t('Enter')} ${$t(NewTabName)} ${$t('Name')}`" aria-label=""
                            aria-describedby="basic-addon1">
                        <div class="col-sm-1 pt-1">
                            <a class="actions-onclick" title="Save" @click="SaveTask('Task')"><em
                                    class="fa fa-save action-icon text-success"></em></a>
                            <a @click="closepopup()" title="Close" class="actions-onclick"><em
                                    class="fa fa-close action-icon text-danger"></em></a>
                        </div>
                    </div>
                </div>
            </div>
        </div>

        <div v-if="IsEditTask">
            <EditTask :MainProjectData="ProjectDetailData" :projectdata.sync="projectdata" :NewTabName="NewTabName"
                :TabsArray="TabsArray" @callbackfunction="FetchListingData" :isHideSprint="isHideSprint"
                :isHideConstruction="isHideConstruction"></EditTask>
        </div>
        <modaltaskprogress v-if="IsUpdateProgress" :TaskItemData="TaskItemData" :Type="IsTaskType"
            @GetTaskList="FetchListingData" @CloseModal="CloseModal"> </modaltaskprogress>
        <AddTeam v-if="IsAssignedUser" :ProjectId="ProjectId" :TaskId="ParentTaskId" :Type="IsType"
            :TabsArray="TabsArray" :ProjectName="ProjectName" @close="IsAssignedUser = false;"
            @callbackfunction="FetchListingData"></AddTeam>



    </section>
</template>
<script>
import DataService from '../../../../services/DataService';
import EditTask from '../../../../components/Modal/EditTask.vue';
import modaltaskprogress from '../../../../components/Modal/modaltaskprogress.vue';
import AddTeam from '../../../../components/Modal/AddTeam.vue'
import projectTaskAddpopup from '../../../../components/Modal/AddProjectTaskmodal.vue';
export default {
    name: 'ActivityList',
    components: { EditTask, modaltaskprogress, AddTeam, projectTaskAddpopup },
    props: {
        isHideSprint: {
            type: Boolean,
            required: true
        },
        isHideConstruction: {
            type: Boolean,
            required: true
        },
        NewTabName: {
            type: String,
            require: true
        },
        TabsArray: {
            type: Array
        },
        checkPmUser: {
            type: Boolean,
            required: true
        },
    },
    data() {
        return {
            ProjectTaskListingpopup: false,
            IsAddTask: false,
            isAddTask: false,
            txtTaskTitle: '',
            IsType: 'Task',
            IsTaskType: 'Project',
            isLoading: false,
            IsAddConstruction: false,
            ProjectId: 0,
            PhaseId: 0,
            userId: null,
            companyId: null,
            UserType: null,
            StatusList: [],
            StatusLists: [],
            ListingData: [],
            TaskListingData: [],
            DepartmentName: '',
            IsEditTask: false,
            projectdata: null,
            activeTaskIndex: null,
            TaskMode: false,
            TaskFieldValue: '',
            projectData: [],
            isDragging: false,
            draggedTask: null,
            sourceStageIndex: null,
            isUpdatingTask: false,
            ProjectDetailData: '',
            SortBy: '',
            SortExp: '',
            PageSize: 10,
            PageNumber: 1,
            IsPriority: null,
            isCollapsed: false,
            Currency: '',
            ProjectName: '',
            projectHours: '',
            IsShowDiv: true,
            TaskItemData: '',
            IsUpdateProgress: false,
            CheckDisableduser: true,
            IsAssignedUser: false,
            ParentTaskId: 0,
            rerenderData: true,
            selectedType: 'List',
            ChkTotalWeightage: 0,
            IsTask: true,
            IsStory: false,
            IsBug: false,
            IssueTypeId: 'T',
            PriorityData:[]
        };
    },
    created: async function () {
        var ths = this;
        ths.userId = ths.GetUserInfo.ID;
        ths.ProjectId = ths.$route.params.projectId;
        ths.Currency = ths.GetUserInfo.Currency.replace(/[()]/g, '');
        ths.UserType = ths.GetUserInfo.UserType;
        await ths.GetProjectDetails();
        ths.GetProjectPriority();
        ths.StatusDropdown();
        ths.FetchProjectStageListing();
        ths.CheckDisabled();
    },
    methods: {
        CommonPriortyUpdate(data, evt) { 
            var vm = this;
            var postJSON = {
                ID: data.task_id,
                StatusId: evt.target.value,
                IsFor: 'UPDATE_PROJECT_PRIORTY'
            };
            var objectPostString = JSON.stringify(postJSON);
            DataService.CommonUpdateStatus(objectPostString).then(function (response) {
                if (response.data != null) {
                    if (response.data.status === 'Success') {
                        vm.FetchTaskList();
                        vm.ShowAlert(vm.$t("RecordUpdatedSuccessfully"), "success", vm.$t('Alert'));
                    } else {
                        vm.ShowAlert(vm.$t("UnknownErrorOccur"), "failure", true, vm.$t('Alert'));
                    }
                } else {
                    vm.ShowAlert(vm.$t("UnknownErrorOccur"), "failure", true, vm.$t('Alert'));
                }

            }, function () {

            });
        },
        TypeCheck(val) {
            var ths = this;
            if (val == 'B') {
                ths.IsTask = false;
                ths.IsBug = true;
                ths.IsStory = false;
                ths.IssueTypeId = 'B';
            } else if (val == 'T') {
                ths.IsTask = true;
                ths.IsBug = false;
                ths.IsStory = false;
                ths.IssueTypeId = 'T';
            } else {
                ths.IsTask = false;
                ths.IsBug = false;
                ths.IsStory = true;
                ths.IssueTypeId = 'S';
            }
        },
        changeView(type) {
            this.ChkTotalWeightage = 0;
            this.selectedType = type;
            if (type == 'List') {
                this.FetchProjectStageListing();
                this.IsShowDiv = true
            }
            else {
                this.FetchTaskList();
                this.ProjectOverview();
                this.IsShowDiv = false
            }
        },
        FetchListingData() {
            this.selectedType == 'List' ? this.FetchProjectStageListing() : this.FetchTaskList()
        },
        closepopup() {
            this.IsAddTask = false;
        },
        toggleTaskExpansion(item) {
            this.$set(this.TaskListingData, item.task_number, !this.TaskListingData[item.task_number]);
        },
        taskExpanded(item) {
            return this.TaskListingData[item.task_number] || false;
        },
        OpenAddTaskPopup: async function () {
            var vm = this;
            vm.IsAddTask = true;
        },
        GetProjectDetails: async function () {
            var vm = this;
            var params = `projectId=${vm.projectId}`;
            await DataService.GetProjectDetails(params).then(function (response) {
                if (response.data.result != null && response.data.result != '') {
                    vm.ProjectDetailData = (response.data.result.PROJECTOVERVIEW[0]);
                }
            });
        },
        async ParentTask(ths) {
            var vm = this;
            var url = 'controller=Task&action=Update'
            await DataService.CheckPrivilege(url).then(async function (response) {
                if (response.data) {
                    vm.$emit('EditTask', ths);
                    vm.projectdata = ths;
                    vm.projectdata.Ispm = vm.CheckDisabled();
                    vm.MainProjectData = vm.MainProjectData;
                    vm.IsEditTask = true;
                    setTimeout(function () {
                        $("#modalEditTask").modal("show");
                    }, 1000);
                } else {
                    vm.isLoading = false;
                    vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, "Alert");
                }
            });
        },
        showAssignUser(itm) {
            if (itm.AssignUser != '') {
                this.$set(itm, 'ispopover', true);
            }
        },
        OpenAssignedUser: function (TaskId) {
            var vm = this;
            vm.ParentTaskId = TaskId;
            vm.IsAssignedUser = true;
        },
        hideAssignUser(itm) {
            this.$set(itm, 'ispopover', false);
        },
        CheckDisabled() {
            if ((this.UserType == 'CL' || this.UserType == 'NU') && this.checkPmUser) {
                return this.CheckDisableduser = true;
            }
            else {
                if (this.UserType == 'CA' || this.UserType == 'PM') {
                    return this.CheckDisableduser = true;
                }
                else {
                    return this.CheckDisableduser = false;
                }
            }
        },
        ProjectOverview: async function () {
            var vm = this;
            var params = `projectId=${this.ProjectId}`;
            await DataService.ProjectOverview(params).then(function (response) {
                if (response.data != null > 0) {
                    vm.ProjectName = response.data.projecT_NAME;
                    vm.projectHours = response.data.estimateD_HOURS
                }
            });
        },
        StatusDropdown: function () {
            var vm = this;
            var url = `langCode=en&companyId=${vm.CompanyId}&statusType=Project&hasGlobal=true`
            DataService.StatusListing(url).then((response) => {
                if (response.data != null && response.data != "") {
                    vm.StatusList = response.data.result.data;
                }
            });
        },
        UpdateProgress(data) {
            this.TaskItemData = data;
            this.IsUpdateProgress = true;
        },
        CloseModal() {
            this.IsUpdateProgress = false;
        },
        EditActivity(ths) {
            debugger
            this.projectdata = ths;
            this.projectdata.TotalWeightage = this.ChkTotalWeightage;
            this.projectdata.child = {};
            this.IsEditTask = true;
            setTimeout(function () {
                $("#modalEditTask").modal("show");
            }, 1000);
        },
        UpdateTask(val) {
            var vm = this;
            vm.FetchProjectStageListing();
            setTimeout(function () {
                $("#modalEditTask").modal("hide");
                $("body").removeClass("modal-open");
                $(".modal-backdrop").remove();
            }, 1000);
        },
        DeleteActivity: function (id, type) {
            var vm = this;
            var val = id;
            vm.isLoading = true;
            if (val != null) {
                vm.confirmR(vm.$t("ConfirmDelete"), true, (vm.$t("Delete") + "  " + vm.$t("Group")), function () {
                    var postJSON = {
                        ids: val,
                        moduleName: "PROJECT",
                        refCode: type == 'Task' ? "TALYGEN_GLOBAL_TASK" : "TALYGEN_ACTIVITY_TASK"
                    };
                    var objectPostString = JSON.stringify(postJSON);
                    DataService.CommonCommonDelete(objectPostString).then(function (response) {
                        if (response.data[0].Code == 'BACKLOG_ASSIGN') {
                            vm.ShowAlert(vm.$t('Assignbacklog', [vm.$t('Backlock')]), "failure", true, vm.$t("Alert"));
                        }
                        if (response.data[0].Code == 'TASK_ASSIGN') {
                            vm.ShowAlert(vm.$t('Taskhavealready', [vm.$t('Task')]), "failure", true, vm.$t("Alert"));
                        }
                        else if (response.data[0].Code == 'PROGRESS') {
                            vm.ShowAlert(vm.$t('Tasksubtaskdeleted', [vm.$t(vm.NewTabName)]), "failure", true, vm.$t("Alert"));
                        }
                        else if (response.status == 200) {
                            vm.ShowAlert(vm.$t('DeletedSuccess', [vm.$t('Task')]), "success", true, vm.$t("Alert"));
                            type == 'Task' ? vm.FetchTaskList() : vm.FetchProjectStageListing()

                        }
                        else {
                            vm.ShowAlert(vm.$t('DeletedError', [vm.$t('Task')]), "warning", true, vm.$t("Alert"));
                        }
                    });
                });
            }
            else {
                vm.ShowAlert(vm.$t("Selectanyrecordtodelete"));
            }
            vm.isLoading = false;
        },
        GetProjectPriority() {
            var url = `id=&moduleName=PROJECT&type=PRIORITY&search=&refId=`;
            DataService.GetDDLData(url).then((response) => {
                if (response.status == 200) {
                    if (response.data.DATA != undefined || response.data.DATA != null) {
                        if (response.data.DATA.length > 0) {                            
                            this.PriorityData = response.data.DATA;
                            var Pdata = this.PriorityData.filter(item => item.name === 'Low');
                            if (Pdata.length > 0) {
                                this.IsPriority = Pdata[0].value;
                            }
                        }
                    }
                }
            })
        },
        AddTask(item, index) {
            var vueObj = this;
            item.isAddTask = true;
            item.txtTaskTitle = '';
            vueObj.ListingData = [...vueObj.ListingData];
        },
        IsHideAddTask(item, index) {
            var vueObj = this;
            item.isAddTask = false;
            item.txtTaskTitle = '';
            vueObj.ListingData = [...vueObj.ListingData];
        },
        EditProject: function () {
            var vm = this;
            vm.$emit('EditProject');
        },
        BackToList() {
            this.$router.push({ name: 'ProjectList' });
        },
        FetchTaskList: async function () {
            var vueObj = this;
            vueObj.isLoading = true;
            var params = `ProjectId=${vueObj.ProjectId}&name=&priority=&SprintId=&Type=&BugType=&StatusId=&Assignee=&sortBy=${vueObj.SortBy}&sortExp=${vueObj.SortExp}&pageSize=${vueObj.PageSize}&pageNumber=${vueObj.PageNumber}1&userType=${vueObj.UserType}`;
          //  var params = `ProjectId=${vueObj.ProjectId}&SprintId=&Type=&BugType=&StatusId=0&Assignee=0&sortBy=${vueObj.SortBy}&sortExp=${vueObj.SortExp}&pageSize=${vueObj.PageSize}&pageNumber=${vueObj.PageNumber}&userType=${vueObj.UserType}`;
            await DataService.GetChildSprint(params).then(function (response) {
                if (response.data.result.Data.length > 0) {
                    var updateArray = response.data.result.Data;
                    updateArray.forEach((x) => {
                        if (x.planned_start_date != null) {
                            x.planned_start_date = new Date(x.planned_start_date);
                        }
                        if (x.planned_end_date != null) {
                            x.planned_end_date = new Date(x.planned_end_date);
                        }
                        if (x.task_description != null) {
                            x.task_description = x.task_description != '' ? x.task_description.replace(/<[^>]*>/g, '') : ''
                        }
                        x.ispopover = false;
                        x.AssignUser = x.Assign != null ? x.Assign.split(',') : '';
                        x.child = {
                            onExpandChild: vueObj.onExpandChild,
                            isShowChild: false,
                            isShowExpandButton: true,
                            data: [],
                            Header: []
                        }
                    });
                    vueObj.TaskListingData = updateArray;
                    vueObj.TotalRecords = response.data.result.Data[0].TOTAL_RECORDS;
                    vueObj.TotalPages = Math.ceil(vueObj.TotalRecords / vueObj.PageSize);
                    vueObj.$emit('callbackWidgets');
                } else {
                    vueObj.TotalRecords = 0;
                    vueObj.TotalPages = 1;
                    vueObj.TaskListingData = [];
                }
                vueObj.isLoading = false;
            });
        },
        FetchProjectStageListing: async function () {
            var vueObj = this;
            vueObj.isLoading = true;
            var params = `projectId=${vueObj.ProjectId}&sortBy=${vueObj.SortBy}&sortExp=${vueObj.SortExp}&pageSize=${vueObj.PageSize}&pageNum=${vueObj.PageNumber}`;
            await DataService.StageListing(params).then(function (response) {
                vueObj.isLoading = false;
                if (response.data.result.data.length > 0) {
                    vueObj.ListingData = response.data.result.data;
                    vueObj.ListingData.forEach((x) => {
                        x.isExpanded = false,
                            x.tasks = []
                    });
                    vueObj.onExpandChild(vueObj.ListingData[0], 0, 'Activity');
                } else {
                    vueObj.ListingData = [];
                }
                vueObj.isLoading = false;
            });
        },
        onExpandChild: function (item, index, type) {
            var vueObj = this;
            vueObj.ChkTotalWeightage = 0;
            if (type === 'Activity') {
                var url = `ProjectId=${vueObj.ProjectId}&StageId=${item.STAGE_ID}`;
                DataService.GetChildStageTaskChild(url).then((response) => {

                    if (response.data.result.DATA.length > 0) {
                        item.tasks = response.data.result.DATA;
                        item.tasks.forEach(element => {
                            vueObj.ChkTotalWeightage += element.weightage;
                        });
                        item.TotalWeightage = vueObj.ChkTotalWeightage;
                        item.isExpanded = !item.isExpanded;
                        vueObj.ListingData = [...vueObj.ListingData];
                        vueObj.isLoading = false;
                    } else {
                        item.tasks = [];
                        item.isExpanded = !item.isExpanded;
                        vueObj.ListingData = [...vueObj.ListingData];
                        vueObj.isLoading = false;
                    }
                });
            } else {
                var url = `ProjectId=${vueObj.ProjectId}&name=&priority=&SprintId=${item.task_id}&Type=SubTask&BugType=&StatusId=&Assignee=&sortBy=&sortExp=&pageSize=10000&pageNumber=1&userType=`;
                //var url = `ProjectId=${vueObj.ProjectId}&SprintId=${item.task_id}&Type=SubTask`;
                DataService.GetChildSprint(url).then((response) => {
                    if (response.data.result.Data.length > 0) {
                        item.child.data = response.data.result.Data;
                        item.child.data.forEach((x) => {
                            if (x.planned_start_date != null) {
                                x.planned_start_date = new Date(x.planned_start_date);
                            }
                            if (x.planned_end_date != null) {
                                x.planned_end_date = new Date(x.planned_end_date);
                            }
                            vueObj.$set(x, 'ispopover', false);
                            vueObj.$set(x, 'AssignUser', x.Assign != null ? x.Assign.split(',') : '');
                            vueObj.$set(x, 'Current_Progress', parseInt(x.Current_Progress) || 0);
                        });
                        item.isExpanded = !item.isExpanded;
                        vueObj.TaskListingData = [...vueObj.TaskListingData];
                        vueObj.isLoading = false;
                    } else {
                        item.child.data = [];
                        item.isExpanded = !item.isExpanded;
                        vueObj.TaskListingData = [...vueObj.TaskListingData];
                        vueObj.isLoading = false;
                    }
                });
            }
        },
        SaveTask(itm) {
            var ths = this;
            if (itm === 'Task') {
                if (!ths.txtTaskTitle || ths.txtTaskTitle.trim() === "") {
                    return false;
                }
                itm = {
                    txtTaskTitle: ths.txtTaskTitle,
                    STAGE_ID: null,
                    TYPE: 'TASK'
                };
            } else {
                if (!itm.txtTaskTitle || itm.txtTaskTitle.trim() === "") {
                    return false;
                }
                itm.TYPE = 'StageTask';
            }
            ths.isLoading = true;
            var obj = {
                BackLogId: 0,
                Project_id: ths.ProjectId,
                Subject: itm.txtTaskTitle,
                IssueTypeId: ths.IssueTypeId ?? 'T',
                SprintId: null,
                PriorityId: ths.IsPriority,
                StageId: itm.STAGE_ID,
                StatusId: 1001,
                UserId: null,
                BackLogDescription: '',
                IsBacklog: false,
                EpicId: null,
                ParentId: null,
                Type: itm.TYPE
            };
            DataService.SaveBackLog(JSON.stringify(obj)).then(function (response) {
                ths.isLoading = false; // Stop loading                
                if (response.data.result.DATA.length > 0) {
                    if (response.data.result.DATA[0].VALUE === "TASK") {
                        ths.ShowAlert(ths.$t('AddedSuccess', [ths.$t('Task')]), "success", true, ths.$t("Alert"));
                        ths.FetchTaskList();
                    }
                    if (response.data.result.DATA[0].VALUE === "STAGETASK") {
                        ths.ShowAlert(ths.$t('AddedSuccess', [ths.$t('Task')]), "success", true, ths.$t("Alert"));
                        ths.FetchProjectStageListing();
                    }

                    if (response.data.result.DATA[0].VALUE === "DUPLICATE") {
                        ths.ShowAlert(ths.$t('AlreadyExists', [ths.$t('Task')]), "warning", true, ths.$t("Alert"));
                    }

                    itm.isAddTask = false;
                    itm.txtTaskTitle = '';
                    ths.txtTaskTitle = '';
                    ths.IsAddTask = false;
                } else {
                    ths.ShowAlert(ths.$t("UnknownErrorOccur"), "failure", true, ths.$t('Alert'));
                }
            }).catch(function (error) {
                ths.isLoading = false;
                ths.ShowAlert(ths.$t("UnknownErrorOccur"), "failure", true, ths.$t('Alert'));
            });
        },
        GetProjectDetails: async function () {
            var vm = this;
            var params = `projectId=${vm.ProjectId}`;
            await DataService.GetProjectDetails(params).then(function (response) {
                if (response.data.result != null && response.data.result != '') {
                    vm.ProjectDetailData = (response.data.result.PROJECTOVERVIEW[0]);
                }
            });
        },
        CloseAddBacklog() {
            this.IsAddConstruction = false;
        },
        EditProject: function () {
            var vm = this;
            vm.$emit('EditProject');
        },
        BacktoList() {
            this.$router.push({ name: 'ProjectList' });
        },
        OpenEditTaskModel(ths) {
            //this.$emit('EditTask', ths);
            this.projectdata = ths;
            this.projectdata.project_id = this.ProjectId;
            this.projectdata.child = {};
            this.IsEditTask = true;
            setTimeout(function () {
                $("#modalEditTask").modal("show");
            }, 1000);
        },
        // AddTask(data, index) {
        //     this.TaskMode = true;
        //     this.activeTaskIndex = index; 
        //     this.projectData = data;
        // },
        Close() {
            this.TaskFieldValue = "";
            this.TaskMode = false;
        },
        EditTask(itm) {
            var vm = this;
            vm.projectdata = itm;
            vm.projectdata.child = {
                onExpandChild: vm.onExpandChild,
                isShowChild: false,
                isShowExpandButton: true,
                data: [],
                Header: []
            };
            vm.IsEditTask = true;
            vm.isHideConstruction = true;
            setTimeout(function () {
                $("#modalEditTask").modal("show");
            }, 1000);
        },
    }
}
</script>

