<template>
    <div class="col-md-12 p-0">
        <loader :is-visible="isLoading"></loader>
        <div class="ticketsmallfix theme-primary partition p-actions-expand " style="overflow: visible;">
            <span class="p-name text-white">{{ $t("Construction Board") }}</span>
            <span class="p-actions float-right">
                <a v-if="!IsStageView" :title="$t('AddTask')" href="javascript:;" class="p-action-btn text-white"
                    @click="AddConstruction()">
                    <em class="fa fa-plus pr-2 "></em> <br><span>{{ $t('AddTask') }}</span></a>
                <a :title="$t('AddBoard')" href="javascript:;" class="p-action-btn text-white" @click="AddStatus()"
                    v-if="IsStageView">
                    <em class="fa fa-plus pr-2 "></em> <br><span>{{ $t('AddBoard') }}</span></a>
                <a :title="$t('StageView')" href="javascript:;" class="p-action-btn text-white" @click="ChangeView('Stage')"
                    v-if="IsStageView">
                    <em class="fa fa-th pr-2 "></em><br><span>{{ $t('StageView') }}</span></a>
                <a :title="$t('StatusView')" href="javascript:;" class="p-action-btn text-white" @click="ChangeView('Task')"
                    v-if="!IsStageView">
                    <em class="fa fa-th pr-2 "></em> <br><span>{{ $t('StatusView') }}</span></a>
                <a :title="$t('BacktoList')" href="javascript:;" class="p-action-btn text-white" @click="BacktoList">
                    <em class="fa fa-angle-double-left pr-2 "></em> <br><span>{{ $t('BacktoList') }}</span></a>
            </span>
        </div>
        <div class="listing mt-2 thispagebod-full" v-if="IsStagetaskView">
            <div class="onlyd-view ht_630">
                <ul class="canvan-view-list vuejs kvlistview proj_kv newdes_kvlist mt-2">
                    <li v-for="(stem, sindex) in StatusList[0]" :key="sindex">
                        <div class="list-group h-auto">
                            <div class="tasknames_newdes">
                                <h3>
                                    <span class="float-left">
                                        <div class="roundball_des" :style="{ backgroundColor: stem.color_code }"
                                            :title="stem.stage_name"></div>
                                        {{ TruncateStr(stem.stage_name, 16) }} <span class="float-right count_des">{{
                                            stem.count }} {{ $t("Total") }}</span>
                                    </span>
                                    <a class="float-right text-success"><em class="fa fa-plus"
                                            @click="AddTask(stem, sindex)"></em></a>
                                </h3>
                            </div>



                            <div class="w-100 float-left my-0" v-if="TaskMode && activeTaskIndex === sindex">
                                <div class="add-backlog-btn border bg-light float-left w-100">
                                    <div class="input-group w-100 pb-3 px-3 pt-3">
                                        <div class="input-group-prepend border-right-0">
                                            <span id="basic-addon1" class="input-group-text bg-white px-2">
                                                <em class="fa fa-check-square epic-timeline"></em>
                                            </span>
                                        </div>
                                        <input type="text" placeholder="Enter task" aria-label=""
                                            aria-describedby="basic-addon1"
                                            class="form-control px-1 bg-white border-left-0 newdescolor"
                                            v-model="TaskFieldValue" @keydown.enter="SaveTaskt" />
                                        <div class="col-sm-2 d-flex pt-2 px-1" @click="SaveTaskt">
                                            <a title="Save" class="actions-onclick px-1">
                                                <em class="fa fa-save action-icon text-success font-18"></em>
                                            </a>
                                            <a title="Close" class="actions-onclick " @click="Close">
                                                <em class="fa fa-close action-icon text-danger font-18"></em>
                                            </a>
                                        </div>
                                    </div>
                                </div>
                            </div>

                            <!-- Task Cards -->
                            <div v-for="(ttem, tindex) in stem.tasks" :key="ttem.task_id || tindex"
                                class="card-box my-2 h-auto pb-1 task-card" :data-task-id="ttem.task_id">
                                <a href="javascript:void(0)"
                                    style="color: inherit; display: block; text-decoration: none;"
                                    @click.prevent="OpenEditTaskModel(ttem)">


                                    <div class="taskname_newdes w-100 float-left mb-2 font-16 font-weight-medium">
                                        Task Name -
                                        <span>{{ ttem.task_number }} {{ TruncateStr(ttem.task_name, 20) }}</span>
                                    </div>

                                    <div
                                        class="taskdate_newdes w-100 float-left mb-2 font-13 font-weight-medium d-flex">
                                        <span class="mr-2">
                                            {{
                                                ttem.planned_start_date !== ""
                                                    ? $options.filters.formatDate(ttem.planned_start_date)
                                                    : "N/A"
                                            }}
                                        </span>

                                        <span class="mr-2">
                                            {{
                                                ttem.planned_end_date !== ""
                                                    ? $options.filters.formatDate(ttem.planned_end_date)
                                                    : "N/A"
                                            }}
                                        </span>

                                        <div class="taskpriority_newdes w-100 float-left mb-2">
                                            <span :style="{ backgroundColor: ttem.color_code }">
                                                {{ ttem.priority_name !== "" ? ttem.priority_name : "N/A" }}
                                            </span>

                                        </div>
                                    </div>

                                    <div class="taskphoto_newdes w-100 float-left mb-2 font-13 font-weight-medium">
                                        <div class="profileicon proj pt-1"
                                            style="background: rgb(24, 82, 63); color: white;"
                                            v-if="ttem.Assign && ttem.Assign !== '' && ttem.Assign !== null">
                                            <span class="initials">
                                                {{ ttem.Assign.split(" ")[0]?.charAt(0) }}{{ ttem.Assign.split("")[1]?.charAt(0) }}
                                            </span>
                                        </div>
                                        <span v-else>N/A</span>
                                    </div>
                                </a>
                            </div>
                        </div>
                    </li>

                    <!-- <li v-for="n in 4 - StatusList.length" v-if="StatusList.length < 4" :key="'add-section-' + n">
                        <div class="list-group h-auto addsection text-center" @click="AddConstruction()">
                        <a>
                            <em class="fa fa-plus mr-2"></em>Add Section
                        </a>
                        </div>
                    </li> -->

                </ul>

                <div v-if="StatusList.length == 0" class="mt-3">
                    <div class="text-center text-danger">
                        {{ $t('NoRecordfound') }}
                    </div>
                </div>
            </div>
        </div>
        <div class="listing mt-2 thispagebod-full" v-if="!IsStagetaskView">
            <div class="onlyd-view ht_630">
                <ul class="canvan-view-list vuejs kvlistview proj_kv newdes_kvlist mt-2">
                    <li v-for="(stem, sindex) in StatusList" :key="sindex">
                        <draggable class="list-group h-auto" :style="{ borderColor: stem.board_color }"
                            v-model="stem.tasks" :group="{ name: 'taskList', pull: true, put: true }" :sort="true"
                            :animation="200" ghost-class="ghost-task" chosen-class="chosen-task"
                            drag-class="dragging-task" :data-board-name="stem.board_name" :data-board-id="stem.board_id"
                            @start="onDragStartt" @end="onDragEndd" @add="onDragAddd">
                            <div class="tasknames_newdes">
                                <h3>
                                    <span class="float-left">
                                        <div class="roundball_des" :style="{ backgroundColor: stem.board_color }"></div>
                                        {{ stem.board_name }} <span class="float-right count_des">{{ stem.count }} {{
                                            $t("Total") }}</span>
                                    </span>
                                    <a class="float-right text-danger"><em class="fa fa-trash-o"
                                            @click="DeleteStatus(stem)"></em></a>
                                    <a class="float-right text-info mr-2"><em class="fa fa-pencil"
                                            @click="AddStatus(stem)"></em></a>
                                    <a class="float-right text-success mr-2"><em class="fa fa-plus"
                                            @click="AddTask(stem, sindex)"></em></a>
                                </h3>
                            </div>
                            <div class="w-100 float-left my-0" v-if="TaskMode && activeTaskIndex === sindex">
                                <div class="add-backlog-btn border bg-light float-left w-100">
                                    <div class="input-group w-100 pb-3 px-3 pt-3 ">
                                        <div class="input-group-prepend border-right-0 flex-grow-1">
                                            <span id="basic-addon1" class="input-group-text bg-white px-2">
                                                <em class="fa fa-check-square epic-timeline"></em>
                                            </span>
                                            <input type="text" placeholder="Enter task" aria-label=""
                                                aria-describedby="basic-addon1"
                                                class="form-control px-1 bg-white border-left-0 newdescolor"
                                                v-model="TaskFieldValue" @keydown.enter="SaveTaskBoard" />
                                        </div>

                                        <div class=" d-flex pt-2" @click="SaveTaskBoard">
                                            <a title="Save" class="actions-onclick">
                                                <em class="fa fa-save action-icon text-success font-18"></em>
                                            </a>
                                            <a title="Close" class="actions-onclick" @click="Close">
                                                <em class="fa fa-close action-icon text-danger font-18"></em>
                                            </a>
                                        </div>
                                    </div>
                                </div>
                            </div>
                            <div v-for="(ttem, tindex) in stem.tasks" :key="ttem.task_id || tindex"
                                class="card-box my-2 h-auto pb-1 task-card" :data-task-id="ttem.task_id">
                                <a href="javascript:void(0)"
                                    style="color: inherit; display: block; text-decoration: none;"
                                    @click.prevent="OpenEditTaskModel(ttem)">
                                    <div class="taskname_newdes w-100 float-left mb-2 font-16 font-weight-medium">
                                        {{ ttem.ParentTask != null ? 'Sub Task Name -' : ' Task Name -' }}
                                        <span class="font-weight-normal" :title="ttem.task_name">{{ ttem.task_number }}
                                            {{ TruncateStr(ttem.task_name, 28) }}</span>
                                    </div>
                                    <div
                                        class="taskdate_newdes w-100 float-left mb-1 font-13 font-weight-medium d-flex">
                                        <span class="mr-2 mt-1">
                                            {{
                                                ttem.planned_start_date !== ""
                                                    ? $options.filters.formatDate(ttem.planned_start_date)
                                                    : "N/A"
                                            }}
                                        </span>
                                        <span class="mt-1 mr-1"> - </span>
                                        <span class="mr-2 mt-1">
                                            {{
                                                ttem.planned_end_date !== ""
                                                    ? $options.filters.formatDate(ttem.planned_end_date)
                                                    : "N/A"
                                            }}
                                        </span>
                                        <div class="taskpriority_newdes w-100 float-left ">
                                            <span :style="{ backgroundColor: ttem.color_code }">
                                                {{ ttem.priority_name !== "" ? ttem.priority_name : "N/A" }}
                                            </span>
                                        </div>
                                    </div>
                                    <div class="taskphoto_newdes w-100 float-left mb-2 font-13 font-weight-medium">
                                        <div class="profileicon proj pt-1"
                                            style="background: rgb(24, 82, 63); color: white;"
                                            v-for="(item, index) in ttem.Assign" :key="index">
                                            <span class="initials">
                                                {{ item.split(" ")[0]?.charAt(0) }}{{ item.split(" ")[1]?.charAt(0) }}
                                            </span>
                                        </div>
                                    </div>
                                </a>
                            </div>
                        </draggable>
                    </li>
                    <li v-if="StatusList.length < 4">
                        <div class="list-group h-auto addsection text-center" @click="AddStatus()">
                            <a>
                                <em class="fa fa-plus mr-2"></em>Add Section
                            </a>
                        </div>
                    </li>
                </ul>

                <div v-if="StatusList.length == 0" class="mt-3">
                    <div class="text-center text-danger">
                        {{ $t('NoRecordfound') }}
                    </div>
                </div>
            </div>
        </div>
        <AddConstructionBoard v-if="IsAddConstruction" @CloseAddBacklog="CloseAddBacklog"
            @FetchConstructionTask="FetchConstructionTask"></AddConstructionBoard>
        <EditTask v-if="IsEditTask" :MainProjectData="ProjectDetailData" :projectdata.sync="projectdata"
            @callbackfunction="FetchConstructionTask" :isHideConstruction="isHideConstruction"></EditTask>
        <AddStatus v-if="IsAddStatus" :projectId="ProjectId" :projectdata="EditDetail"></AddStatus>
    </div>
</template>
<script>
import AddConstructionBoard from '../../../../components/Modal/AddConstructionBoard.vue';
import EditTask from '../../../../components/Modal/EditTask.vue';
import DataService from '../../../../services/DataService'
import draggable from 'vuedraggable';
import AddStatus from '../../../../components/Modal/AddStatus.vue';
export default {
    components: { AddConstructionBoard, draggable, EditTask, AddStatus },
    props: {
        isHideConstruction: {
            type: Boolean,
            required: true
        }
    },
    data() {
        return {
            isLoading: false,
            IsAddConstruction: false,
            ProjectId: 0,
            PhaseId: 0,
            userId: null,
            companyId: null,
            UserType: null,
            StatusList: [],
            ListingData: [],
            DepartmentName: '',
            IsEditTask: false,
            projectdata: null,
            activeTaskIndex: null,
            TaskMode: false,
            TaskFieldValue: '',
            projectData: [],
            isDragging: false,
            draggedTask: null,
            sourceStageIndex: null,
            isUpdatingTask: false,
            ProjectDetailData: '',
            IsStagetaskView: true,
            IsStageView: false,
            StatusTaskData: [],
            IsAddStatus: false,
            EditDetail: [],
            sourceBoardIndex: null,
            isUpdatingTask: false
        }
    },
    created: async function () {
        var vm = this;
        vm.userId = vm.GetUserInfo.ID;
        vm.ProjectId = this.$route.params.projectId;
        vm.companyId = vm.GetUserInfo.CompanyId;
        vm.UserType = vm.GetUserInfo.UserType;
        await vm.GetProjectDetails();
        if (vm.IsStagetaskView) {
            vm.FetchConstructionTask();
        }

    },
    methods: {
        GetProjectDetails: async function () {
            var vm = this;
            var params = `projectId=${vm.ProjectId}`;
            await DataService.GetProjectDetails(params).then(function (response) {
                if (response.data.result != null && response.data.result != '') {
                    vm.ProjectDetailData = (response.data.result.PROJECTOVERVIEW[0]);
                }
            });
        },
        AddConstruction() {
            this.IsAddConstruction = true;
        },
        CloseAddBacklog() {
            this.IsAddConstruction = false;
        },
        EditProject: function () {
            var vm = this;
            vm.$emit('EditProject');
        },
        BacktoList() {
            this.$router.push({ name: 'ProjectList' });
        },
        OpenEditTaskModel(ths) {
            this.projectdata = ths;
            this.projectdata.project_id = this.ProjectId;
            this.projectdata.child = {};
            this.IsEditTask = true;
            setTimeout(function () {
                $("#modalEditTask").modal("show");
            }, 1000);
        },
        AddTask(data, index) {
            this.TaskMode = true;
            this.activeTaskIndex = index;
            this.projectData = data;
        },
        SaveTaskBoard()
        {
           
           var vm=this;
           var textboxvalue=vm.TaskFieldValue;
           var data=vm.projectData;
           var vm = this;
            if (!textboxvalue || textboxvalue.trim() === "") {                
                return false; 
            }
            vm.isAddDisabled = true;
            var obj = {
                BackLogId: null,
                Project_id:vm.ProjectId,
                Subject: textboxvalue,
                IssueTypeId: 'T',
                SprintId: null,
                PriorityId: 54589,
                StatusId: data.board_status[0].status_id,
                UserId: null,
                BackLogDescription: null,
                IsBacklog: false,
                EpicId: null,
                ParentId: 0,
                Type: 'task'
            }
            DataService.SaveBackLog(JSON.stringify(obj)).then(function (response) {
                vm.isLoading = false;
                if (response.data.status == "Success") {
                    if (response.data.result.DATA[0].VALUE == "TASK") {
                        vm.ShowAlert(vm.$t('AddedSuccess', [vm.$t('Task')]), "success", true, vm.$t("Alert"));
                        vm.TaskFieldValue = "";
                        vm.TaskData();
                    }
                    
                    if (response.data.result.DATA[0].VALUE == "DUPLICATE") {
                        vm.ShowAlert(vm.$t('AlreadyExists', [vm.$t('Task')]), "warning", true, vm.$t("Alert"));
                        vm.TaskFieldValue = "";
                        vm.TaskData();
                    }
     
                } else {
                    vm.ShowAlert(vm.$t("Error"), "failure",vm.$t('Alert'));  
                }
                 vm.TaskMode = false;
            })

        }, 
        SaveTaskt() {
            var vm = this;
            var textboxvalue = vm.TaskFieldValue;
            var data = vm.projectData;

            if (!textboxvalue || textboxvalue.trim() === "") {
                return false;
            }
            vm.isLoading = true;
            var obj = {
                BackLogId: null,
                Project_id: vm.ProjectId,
                Subject: textboxvalue,
                StageId: data.stage_id,
                UserId: null,
                Date: null,
                PriorityId: 54589,
                IssueTypeId: 'T',
                ConstructionManager: null,
                Quality: 'Pass',
                Duration: null,
                StatusId:1001,
                BackLogDescription: null,
                Type: 'ConstructionTask'
            };
            DataService.SaveBackLog(JSON.stringify(obj)).then(function (response) {
                vm.isLoading = false;
                if (response.data.result.DATA && response.data.result.DATA.length > 0) {
                    if (response.data.result.DATA[0].VALUE == "CONSTRUCTIONTASK") {
                        vm.ShowAlert(vm.$t('AddedSuccess', [vm.$t('Task')]), "success", true, vm.$t("Alert"));
                        vm.TaskFieldValue = "";
                        vm.FetchConstructionTask();
                    } else if (response.data.result.DATA[0].VALUE == "DUPLICATE") {
                        vm.ShowAlert(vm.$t('AlreadyExists', [vm.$t('Task')]), "warning", true, vm.$t("Alert"));
                        vm.TaskFieldValue = "";
                        vm.FetchConstructionTask();
                    } else {
                        vm.ShowAlert(vm.$t("Error"), "failure", true, vm.$t('Alert'));
                    }
                } else {
                    vm.ShowAlert(vm.$t("Error"), "failure", true, vm.$t('Alert'));
                }
                vm.TaskMode = false;
            }).catch(function (error) {
                vm.isLoading = false;
                vm.ShowAlert(vm.$t("Error"), "failure", true, vm.$t('Alert'));
                vm.TaskMode = false;
                console.error('Error saving task:', error);
            });
        },
        Close() {
            this.TaskFieldValue = "";
            this.TaskMode = false;
        },
        EditTask(itm) {
            var vm = this;
            vm.projectdata = itm;
            vm.projectdata.child = {
                onExpandChild: vm.onExpandChild,
                isShowChild: false,
                isShowExpandButton: true,
                data: [],
                Header: []
            };
            vm.IsEditTask = true;
            vm.isHideConstruction = true;
            setTimeout(function () {
                $("#modalEditTask").modal("show");
            }, 1000);
        },
        UpdateTask() {
            var vm = this;
            setTimeout(function () {
                $("#modalEditTask").modal("hide");
                $("body").removeClass("modal-open");
                $(".modal-backdrop").remove();
            }, 1000);
            vm.FetchConstructionTask();
        },
        FetchConstructionTask() {
            debugger
            var vm = this;
            var url = `ProjectId=${vm.ProjectId}`;
            DataService.FetchConstructionTask(url).then((response) => {
                var statusList = [];
                if (response.data.result.STATUS_FINAL_JSON && response.data.result.STATUS_FINAL_JSON.length > 0) {
                    statusList = response.data.result.STATUS_FINAL_JSON.map(element => {
                        return {
                            ...element,
                            tasks: [],
                            count: 0
                        };
                    });
                    if (response.data.result.Data && response.data.result.Data.length > 0) {
                        response.data.result.Data.forEach(element => {

                            var statusIndex = statusList.findIndex(ele => ele.stage_id == element.stage_id && element.task_id != null);
                            if (statusIndex !== -1) {
                                statusList[statusIndex].tasks.push(element);
                                statusList[statusIndex].count++;
                            }
                        });
                    } else {
                        vm.ListingData = [];
                    }
                } else {
                    vm.ListingData = [];
                }
                vm.StatusList = Array(statusList);
            }).catch(function (error) {
                console.error('Error fetching construction tasks:', error);
                vm.StatusList = [];
                vm.ListingData = [];
            });
        },        
        ChangeView(type) {
            debugger
            var ths = this;
            ths.IsStagetaskView = !ths.IsStagetaskView;
            ths.IsStageView = !ths.IsStageView
            if (type == 'Task') {
                ths.TaskData();
            } else {
                ths.FetchConstructionTask();
            }
        },
        TaskData: function () {
            debugger
            var vm = this;
             var url = `ProjectId=${vm.ProjectId}&name=&priority=&SprintId=&Type=Board&BugType=&StatusId=&Assignee=&sortBy=&sortExp=&pageSize=&pageNumber&userType=`;
                      
           // var url = `ProjectId=${vm.ProjectId}&SprintId=&Type=Board`;
            DataService.GetChildSprint(url).then((response) => {
                if (response.data.result.STATUS_FINAL_JSON.length > 0) {
                    vm.StatusList = [];
                    vm.StatusList = response.data.result.STATUS_FINAL_JSON;
                    vm.StatusList.forEach(element => {
                        element.tasks = [];
                        element.count = 0;
                    });
                }
                if (response.data.result.Data.length > 0) {
                    vm.StatusTaskData = response.data.result.Data;
                    vm.StatusTaskData.forEach(element => {
                        vm.StatusList.forEach(ele => {
                            if (ele.board_id == element.board_id) {
                                if (element.Assign != '' && element.Assign != null) {
                                    element.Assign = element.Assign.split(',');
                                }
                                ele.tasks.push(element);
                                ele.count++;
                            }
                        })
                    })
                }
                else {
                    vm.StatusTaskData = [];
                }
            });
        },
        AddStatus: function (data) {
            var vm = this;
            vm.IsAddStatus = true;
            vm.EditDetail = data;
        },
        DeleteStatus: function (data) {
            debugger
            var id = data.board_id;
            var vm = this;
            var val = "";
            vm.isLoading = true;
            if (id == null) {
                $('.chkItems:checkbox:checked').not("[id^='chkAll_0']").each(function () {
                    if (val.length > 0)
                        val += ',';
                    val += $(this).val();
                });
            }
            else {
                val = id;
            }
            if (val != null) {
                vm.confirmR(vm.$t("ConfirmDelete"), true, (vm.$t("Delete") + "  " + vm.$t("Group")), function () {
                    var postJSON = {
                        ids: val,
                        moduleName: "PROJECT",
                        refCode: "TALYGEN_GLOBAL_BOARD"
                    };
                    var objectPostString = JSON.stringify(postJSON);
                    debugger
                    DataService.CommonCommonDelete(objectPostString).then(function (response) {
                        debugger
                        vm.isLoading = false;
                        if (response.data[0].Status == "Success") {
                            vm.ShowAlert(vm.$t('DeletedSuccess', [vm.$t('Board')]), "success", true, vm.$t("Alert"));
                            vm.TaskData();
                        }
                        else {
                            vm.ShowAlert(vm.$t('DeletedError', [vm.$t('Board')]), "warning", true, vm.$t("Alert"));
                        }
                    });
                });
            }
            else {
                vm.ShowAlert(vm.$t("Selectanyrecordtodelete"));
            }
            vm.isLoading = false;
        },
        onDragStartt(evt) {
            debugger
            var vm = this;
            vm.isDragging = true;
            // Get source board index
            var sourceElement = evt.from;
            var sourceBoardName = sourceElement.getAttribute('data-board-name');
            if (sourceBoardName) {
                vm.sourceBoardIndex = vm.StatusList.findIndex(board => board.board_name === sourceBoardName);
            }
            // Get dragged task data
            var taskElement = evt.item;
            vm.draggedTask = this.getTaskDataFromElement(taskElement);
            // Add visual feedback
            document.body.classList.add('dragging');
        },

        onDragAddd(evt) {
            debugger
            // Task was added to a new board, handle the move
            var vm = this;

            // Prevent duplicate calls
            if (vm.isUpdatingTask) {
                return;
            }

            var targetBoardName = evt.to.getAttribute('data-board-name');
            var targetBoardId = evt.to.getAttribute('data-board-id');

            // Get task data from the element if draggedTask is not available
            var taskData = vm.draggedTask;
            if (!taskData && evt.item) {
                taskData = vm.getTaskDataFromElement(evt.item);
            }

            if (targetBoardName && taskData && taskData.task_id) {
                vm.isUpdatingTask = true;
                vm.handleTaskMove(taskData, targetBoardName, targetBoardId, evt.newIndex);
            }
        },
        onDragEndd(evt) {
            debugger
            var vm = this;
            // Remove visual feedback
            document.body.classList.remove('dragging');
            // If task was moved within the same board, no status update needed
            var sourceBoardName = evt.from.getAttribute('data-board-name');
            var targetBoardName = evt.to.getAttribute('data-board-name');
            if (sourceBoardName === targetBoardName) {
                // Task moved within same board, just refresh
                vm.isDragging = false;
                vm.draggedTask = null;
                vm.sourceBoardIndex = null;
                vm.isUpdatingTask = false;
                vm.TaskData();
                return;
            }
            // Task moved to different board - this should be handled by onDragAdd
            // But we'll also handle it here as a fallback if onDragAdd didn't fire
            if (!vm.isUpdatingTask && targetBoardName && evt.item) {
                var taskData = vm.getTaskDataFromElement(evt.item);
                if (taskData && taskData.task_id) {
                    var targetBoardId = evt.to.getAttribute('data-board-id');
                    vm.isUpdatingTask = true;
                    vm.handleTaskMove(taskData, targetBoardName, targetBoardId, evt.newIndex);
                } else {
                    // Clean up if no valid task data
                    vm.isDragging = false;
                    vm.draggedTask = null;
                    vm.sourceBoardIndex = null;
                    vm.isUpdatingTask = false;
                    vm.TaskData(); // Refresh to restore state
                }
            } else {
                // Clean up drag state (onDragAdd is handling the update)
                vm.isDragging = false;
                vm.draggedTask = null;
                vm.sourceBoardIndex = null;
            }
        },
        handleTaskMove(taskData, targetBoardName, targetBoardId, newIndex) {
            var vm = this;

            if (!taskData || !taskData.task_id) {
                console.error('Invalid task data for move operation');
                vm.TaskData(); // Refresh to restore state
                return;
            }

            // Find the target board from StatusList
            var targetBoard = null;
            if (targetBoardId) {
                targetBoard = vm.StatusList.find(board => board.board_id == targetBoardId);
            }
            if (!targetBoard) {
                targetBoard = vm.StatusList.find(board => board.board_name === targetBoardName);
            }

            if (!targetBoard || !targetBoard.board_status || targetBoard.board_status.length === 0) {
                console.error('Target board not found or has no statuses');
                vm.TaskData(); // Refresh to restore state
                return;
            }

            // Get the first status from the target board's board_status array
            var firstStatus = targetBoard.board_status[0];

            if (!firstStatus || !firstStatus.status_id) {
                console.error('Target board has no valid first status');
                vm.TaskData(); // Refresh to restore state
                return;
            }

            // Prepare task update object
            var updateData = {
                task_id: taskData.task_id,
                StatusId: firstStatus.status_id,
                status_name: firstStatus.status_name || targetBoardName,
                status_bg_color: firstStatus.status_bg_color || firstStatus.STATUS_BG_COLOR || '#24a5ff',
                IsFor: 'TASKLISTING'
            };

            // Update task status via API
            vm.updateTaskStatus(updateData);
        },
        updateTaskStatus(itm) {
            var vm = this;
            var obj = {
                ID: itm.task_id,
                StatusId: itm.StatusId,
                IsFor: itm.IsFor
            };
            var objectPostString = JSON.stringify(obj);

            DataService.CommonUpdateStatus(objectPostString).then(function (response) {
                // Reset update flag
                vm.isUpdatingTask = false;
                vm.isDragging = false;
                vm.draggedTask = null;
                vm.sourceBoardIndex = null;

                if (response.data.result == '0') {
                    // Success - refresh task data
                    vm.TaskData();
                    vm.ShowAlert(vm.$t('UpdatedSuccess', [vm.$t('Task')]), "success", true, vm.$t("Alert"));
                } else {
                    // Error - refresh to restore state
                    vm.TaskData();
                    vm.ShowAlert(vm.$t("Error"), "failure", true, vm.$t("Alert"));
                }
            }).catch(function (error) {
                // Error - refresh to restore state
                vm.isUpdatingTask = false;
                vm.isDragging = false;
                vm.draggedTask = null;
                vm.sourceBoardIndex = null;
                vm.TaskData();
                vm.ShowAlert(vm.$t("Error"), "failure", true, vm.$t("Alert"));
                console.error('Error updating task status:', error);
            });
        },
        getTaskDataFromElement(element) {
            debugger
            var vm = this;
            // Try multiple ways to get task data from the dragged element
            var taskData = null;

            // Method 1: From Vue component instance (_underlying_vm_)
            if (element._underlying_vm_ && element._underlying_vm_.task_id) {
                taskData = element._underlying_vm_;
            }
            // Method 2: From Vue __vue__ property
            else if (element.__vue__) {
                // Try $attrs first
                if (element.__vue__.$attrs && element.__vue__.$attrs.task_id) {
                    taskData = element.__vue__.$attrs;
                }
                // Try component data
                else if (element.__vue__.$data && element.__vue__.$data.task_id) {
                    taskData = element.__vue__.$data;
                }
            }
            // Method 3: From data attribute (dataset)
            else if (element.dataset && element.dataset.taskId) {
                var taskId = parseInt(element.dataset.taskId);
                taskData = vm.findTaskByIdd(taskId);
            }
            // Method 4: From the actual element's data-task-id attribute
            else {
                var taskIdAttr = element.getAttribute ? element.getAttribute('data-task-id') : null;
                if (taskIdAttr) {
                    var taskId = parseInt(taskIdAttr);
                    taskData = vm.findTaskByIdd(taskId);
                }
            }

            // If still no task data, try to find by searching all boards
            if (!taskData && element) {
                // Try to get task_id from any nested element
                var taskIdElement = element.querySelector ? element.querySelector('[data-task-id]') : null;
                if (taskIdElement) {
                    var taskId = parseInt(taskIdElement.getAttribute('data-task-id'));
                    taskData = vm.findTaskByIdd(taskId);
                }
            }

            return taskData;
        },
        findTaskByIdd(taskId) {
            debugger
            // Search through all boards to find the task
            for (var i = 0; i < this.StatusList.length; i++) {
                var board = this.StatusList[i];
                if (board.tasks && board.tasks.length > 0) {
                    var task = board.tasks.find(t => t.task_id === taskId);
                    if (task) {
                        return task;
                    }
                }
            }
            return null;
        },
    }
}
</script>
