

<template>
    <div class="my-popups">
        <loader :is-visible="isLoading"></loader>
        <div class="modal d-block">
            <div class="modal-dialog modal-dialog-centered">
                <div class="modal-content">
                    <div class="modal-header theme-primary partition-full  d-flex">
                        <h4 class="modal-title">{{ projectdata == null ? 'Add Board' : 'Edit Board'}}</h4>
                        <button type="button" class="close" v-on:click="Close">
                            <em class="fa fa-times" aria-hidden="true"></em>
                        </button>
                    </div>
                    <div class="modal-body">
                        <dynamic-form ref="AssignTagForm" lang="en" :mandatorytext="$t('MandatoryString')" :buttons="buttons" :schema="FormSchema" v-on:OnSubmit="AddStatus()">
                        </dynamic-form>
                    </div>
                </div>
            </div>
        </div>
    </div>
</template>
<script>

import DataService from '../../services/DataService.js';
export default { 
    props: {
        projectId: {
            type: Number,
            require: true
        },
        projectdata:{
           type:Object,
           require:false
        }
    },  
    data() {
        return {
            userId: null,
            companyId: null,
            UserType: null,
            isLoading:false,
            FormSchema: [
                {
                    layoutType: "double",
                    Data: [
                        {
                            astype: "TextField",
                            label: this.$t('Board Name'),
                            name: "BoardName",
                            value: "",
                            placeholder: "Enter Board Name",
                            validationRules: {
                                "required": true
                            },
                            disabled: false,
                        },
                        {
                            astype: "MultiSelectField",
                            label: this.$t('Status Code'),
                            name: "Status Code",
                            value: "",
                            mode: "tag",
                            placeholder: "Select Status Code",
                            validationRules: {
                                "required": true                                
                            },
                            config: {
                                options: []
                            }, 
                            disabled: false,
                        },                        
                        {
                            astype: "ColorField",
                            label: this.$t('Color Code'),
                            name: "Color Code",
                            value: "",
                            placeholder: "",
                            validationRules: {
                                "required": true
                            },
                            disabled: false,
                        },
                        {
                            astype: "NumericField",
                            label: this.$t('Wip Limit'),
                            name: "Wiplimit",
                            value: "",
                            placeholder: "",
                            validationRules: {
                                "required": true,
                                max: 2
                            },
                            disabled: false,
                        }                 
                                               
                    ],
                    
                },
                {
                    layoutType: "single",
                    Data: [
                    {
                            astype: "TextAreaField",
                            label: this.$t('Description'),
                            name: "Description",
                            value: "",
                            placeholder: "",
                            validationRules: {
                                "required": true
                            },
                            disabled: false,
                        } 
                    ]
                }

            ],
            buttons: [
                {
                    type: "submit",
                    class: "btn btn-success",
                    text: "<i class='fa fa-save pr-2'></i>Save",
                    isVisible: true
                },
                {
                    type: "button",
                    class: "btn btn-danger",
                    text: "<i class='fa fa-close pr-2'></i>Cancel",
                    onClick: this.Close,
                },
            ],  
            EditData:[],      
             BoardId:0,
             displayOrder:0
        }
    },
       
    created: async function () {
        var vm = this;
        vm.GetProjectStatus();               
        vm.userId = vm.GetUserInfo.ID;        
        vm.companyId = vm.GetUserInfo.CompanyId;
        vm.UserType = vm.GetUserInfo.UserType; 
        if(vm.projectdata != null)
           {
            vm.EditData=vm.projectdata;  
            vm.BindEditValue(vm.EditData);   
        } 
          
    },
    methods: {
        Close: function () {
            var vm = this;
            vm.$parent.IsAddStatus = false;
        },
        BindEditValue(data) {
            var vm = this;
            vm.BoardId = data.board_id;
            vm.FormSchema[0].Data[0].value = data.board_name;
            vm.FormSchema[0].Data[2].value = data.board_color;
            vm.FormSchema[0].Data[3].value = data.wip_limit;
            vm.FormSchema[1].Data[0].value = data.board_description;
            vm.displayOrder = data.display_order||0;
            var NewArray = [];
            data.board_status.forEach((element) => {
                let obj = {
                    value: element.status_id,
                    label: element.status_name
                };
                NewArray.push(obj);
            });
            vm.FormSchema[0].Data[1].value = NewArray;
        },
        GetProjectStatus(){
            var vm = this;
            var url=`langCode=en&companyId=${vm.companyId}&statusType=Project&hasGlobal=true`
            DataService.StatusListing(url).then((response)=>{                
                if (response.data != null && response.data != "") { 
                    var StatusList = response.data.result.data; 
                    StatusList.forEach((element)=>{
                        let obj={
                            value:element.STATUS_ID,
                            name:element.STATUS
                        }                        
                        vm.FormSchema[0].Data[1].config.options.push(obj);
                    }); 
                    vm.$refs.AssignTagForm.UpdateKeyValue();                
                }
            });
        },
        
        AddStatus: function() { 
    var vm = this;
    var StatusName = vm.FormSchema[0].Data[0].value;           
    var val = "";           
    vm.FormSchema[0].Data[1].value.forEach((itm) => {                               
        val += itm.value;
        val += ',';
    });
    var BoardId = vm.BoardId != null ? vm.BoardId : 0;
    var StatusCode = val;
    var Description = vm.FormSchema[1].Data[0].value;
    var ColorCode = encodeURIComponent(vm.FormSchema[0].Data[2].value);
    var Viplimit= vm.FormSchema[0].Data[3].value;
    var url = `BoardId=${BoardId}&StatusName=${StatusName}&ProjectId=${vm.projectId}&StatusCode=${StatusCode}&Description=${Description}&ColorCode=${ColorCode}&Viplimit=${Viplimit}&DisplayOrder=${vm.displayOrder}`;

    DataService.AddStatus(url).then((response) => {
            const resultJson = JSON.parse(response.data[0].Result);
            var result = resultJson.DATA[0].VALUE;
            const result2 = resultJson.DATA?.[0]?.VALUE || '';         
            if (result === 'EXISTS' ) {
                vm.ShowAlert(vm.$t('AlreadyExists', [vm.$t('Board')]), "failure", true, vm.$t('Alert'));
            } else if (result === 'INSERT') {
                vm.ShowAlert(vm.$t('AddedSuccess', [vm.$t('Status')]), "success", true, vm.$t("Alert"));
                vm.$parent.IsAddStatus = false;
                vm.$parent.TaskData();
            }
            else if (result === 'UPDATE' || result==null) {
                vm.ShowAlert(vm.$t('UpdatedSuccess', [vm.$t('Status')]), "success", true, vm.$t("Alert"));
                vm.$parent.IsAddStatus = false;
                vm.$parent.TaskData();
            } 
            else if (typeof result2 === 'string' || result.trim() !== '' && result.includes(',')) {
                vm.ShowAlert([vm.$t("StatusalreadyusedinBoard"), `"${result}"`],"failure",vm.$t('Alert'));
            } else {
                vm.ShowAlert(vm.$t("UnknownErrorOccur"), "failure", vm.$t('Alert'));
            }
         
    });
}

    }
   
}
</script>
<style>
#color-picker-arrow{
    position: absolute;
    bottom: 8px!important;
    right: 11px!important;
}
</style>