<template>
    <section>
        <loader :is-visible="isLoading"></loader>
        <tg-list ref="tgList" :listType="listType" :IsShowAction="true" :showCheckBox="false" ModuleName="PROJECT"
            SubModuleCode="File" IdentityColumn="FILE_ID" :ListData="ListingData" :HeaderText="$t(NewTabName)"
            :HeaderData="Headers" :TotalRecords="TotalRecords" :SearchFields="false" :IsSearchFieldsOnTop="false"
            SearchPosition="top" :HeaderButtons="listheaderbuttons" :RenderRowActionMethod="renderActions"
            :ListDataCallBackFunction="GetFilesListing" :routeInfo="$router" :SortExp="SortExp" :SortBy="SortBy"
            :NorecordfoundText="$t('NoRecordfound')" v-on:HeaderButtonClick="commonHeaderButtonClick"
            v-on:PagerButtonClick="pagerMethod" v-on:ActionButtonClick="actionButtonClick"
            v-on:SortdataButtonClick="sortdata" :key="Key">

            <!-- ── LIST VIEW SLOTS ── -->
            <template v-slot:slotdata="{ data }">
                <template v-if="data.column.COLUMN_NAME === 'filepreview'">
                    <div class="ls-preview-cell" @click="previewFile(data.row)" title="Preview">
                        <img v-if="isImageFile(data.row._ext)"
                            :src="data.row.FILE_THUMB_PATH && data.row.FILE_THUMB_PATH.trim() !== '' ? data.row.FILE_THUMB_PATH : data.row.BlobUrl"
                            class="ls-thumb" />
                        <div v-else class="ls-icon-wrap"
                            :style="{ background: getFileBgColor(data.row._ext) }">
                            <i :class="['fa fa-lg', getFileIconClass(data.row._ext)]"
                                :style="{ color: getFileIconColor(data.row._ext) }"></i>
                        </div>
                    </div>
                </template>

                <template v-if="data.column.COLUMN_NAME === 'FILE_TITLE'">
                    <div class="ls-title-cell">
                        <span class="ls-ext-dot"
                            :style="{ background: getFileIconColor(data.row._ext) }"></span>
                        <span class="ls-cell-text" :title="data.row.FILE_TITLE">
                            {{ data.row.FILE_TITLE || '—' }}
                        </span>
                    </div>
                </template>

                <template v-if="data.column.COLUMN_NAME === 'LATEST_FILE_NAME'">
                    <span class="ls-cell-text" :title="data.row.LATEST_FILE_NAME">
                        {{ data.row.LATEST_FILE_NAME }}
                    </span>
                </template>

                <template v-if="data.column.COLUMN_NAME === 'FILE_DESC'">
                    <span class="ls-cell-text" :title="data.row.FILE_DESC">
                        {{ displayDescription(data.row.FILE_DESC, 40) || '—' }}
                    </span>
                </template>
            </template>

            <!-- ── CARD VIEW SLOT ── -->
            <template v-slot:customcard="{ data }">
                <div class="fc-card" :style="getCardTopBorder(data.row._ext)" @click="previewFile(data.row)">

                    <!-- Header: ext badge + actions menu -->
                    <div class="fc-card-header">
                        <span class="fc-ext-badge"
                            :style="{ background: getFileIconColor(data.row._ext) }">
                            {{ (data.row._ext || 'FILE').toUpperCase() }}
                        </span>
                        <div class="fc-menu-wrap" @click.stop>
                            <button class="fc-menu-btn" @click.stop="toggleMenu(data.row.ROWNUMBER)" title="More actions">
                                <i class="fa fa-ellipsis-v"></i>
                            </button>
                            <div v-if="activeMenu === data.row.ROWNUMBER" class="fc-dropdown">
                                <button class="fc-dropdown-close" @click.stop="closeMenu">
                                    <i class="fa fa-times"></i>
                                </button>
                                <!-- <a class="fc-dd-item" @click="previewFile(data.row)">
                                    <i class="fa fa-eye text-info"></i> Preview
                                </a> -->
                                <a class="fc-dd-item" @click="OldVersion(data.row)">
                                    <i class="fa fa-clock-o text-success"></i> Old Version
                                </a>
                                <a class="fc-dd-item" @click="UploadNewVersion(data.row)">
                                    <i class="fa fa-upload text-success"></i> Upload New Version
                                </a>
                            </div>
                        </div>
                    </div>

                    <!-- Preview area -->
                    <div class="fc-preview-area">
                        <img v-if="isImageFile(data.row._ext)"
                            :src="data.row.FILE_PATH && data.row.FILE_PATH.trim() !== '' ? data.row.FILE_PATH : data.row.BlobUrl"
                            class="fc-thumb" :alt="data.row.FILE_TITLE" />
                        <div v-else class="fc-icon-area"
                            :style="{ background: getFileBgColor(data.row._ext) }">
                            <i :class="['fa fa-4x', getFileIconClass(data.row._ext)]"
                                :style="{ color: getFileIconColor(data.row._ext) }"></i>
                        </div>
                        <div class="fc-preview-overlay">
                            <i class="fa fa-search-plus"></i>
                        </div>
                    </div>

                    <!-- File info -->
                    <div class="fc-body">
                        <p class="fc-title" :title="data.row.FILE_TITLE">
                            {{ data.row.FILE_TITLE || data.row.LATEST_FILE_NAME }}
                        </p>
                        <p class="fc-filename" :title="data.row.LATEST_FILE_NAME">
                            <i class="fa fa-paperclip"></i>
                            {{ TruncateStr(data.row.LATEST_FILE_NAME, 24) }}
                        </p>
                        <p v-if="displayDescription(data.row.FILE_DESC, 38)" class="fc-desc"
                            :title="data.row.FILE_DESC">
                            {{ displayDescription(data.row.FILE_DESC, 38) }}
                        </p>
                    </div>

                    <!-- Quick-action footer -->
                    <div class="fc-footer">
                        <button class="fc-action-btn" @click.stop="DownloadFiles(data.row)" :title="$t('Download')">
                            <i class="fa fa-download"></i>
                        </button>
                        <button class="fc-action-btn" @click.stop="ShareFiles(data.row)" :title="$t('Share')">
                            <i class="fa fa-share-alt"></i>
                        </button>
                        <button class="fc-action-btn fc-action-danger" @click.stop="DeleteFiles(data.row)"
                            :title="$t('Delete')">
                            <i class="fa fa-trash-o"></i>
                        </button>
                    </div>

                </div>
            </template>
        </tg-list>

        <!-- Preview Modal -->
        <div v-if="isPreviewVisible" class="file-preview-modal" @click.self="closePreview">
            <div class="file-preview-dialog">
                <div class="file-preview-header">
                    <h5 class="file-preview-title" :title="fileName">{{ fileName || $t('Preview') }}</h5>
                    <button type="button" class="file-preview-close" @click="closePreview" aria-label="Close">
                        <i class="fa fa-times"></i>
                    </button>
                </div>

                <div class="file-preview-body">
                    <img v-if="previewType === 'image'" :src="previewSrc" class="preview-image" :alt="fileName" />

                    <iframe v-else-if="previewType === 'pdf'" :src="previewSrc" class="preview-frame"></iframe>

                    <video v-else-if="previewType === 'video'" class="preview-video" controls autoplay>
                        <source :src="previewSrc" />
                    </video>

                    <iframe v-else-if="previewType === 'doc'" :src="googleDocsViewerSrc" class="preview-frame"></iframe>

                    <div v-else class="preview-unsupported">
                        <i class="fa fa-file-o fa-3x mb-2"></i>
                        <div class="mb-2">{{ $t('PreviewNotAvailable') || 'Preview not available for this file type.' }}</div>
                        <button class="btn btn-primary btn-sm" @click="DownloadFiles(fileContent)">
                            <i class="fa fa-download pr-1"></i>{{ $t('Download') }}
                        </button>
                    </div>
                </div>
            </div>
        </div>

        <!-- Upload Modals -->
        <UploadFile v-if="IsFileUploadModalShow" :Screen="Files" :ProjectId="ProjectId" @GetFilesListing="GetBlobUrl">
        </UploadFile>
        <UploadNewVersion v-if="IsNewVersionUpload" :ProjectId="ProjectId" :FileId="FileId"></UploadNewVersion>
        <OldFileVersionAndDeleteFiles v-if="IsOldVersionShow" :ProjectId="ProjectId" :FileId="FileId"
            :IsOldVersionOrDeleteFiles="IsOldVersionOrDeleteFiles"></OldFileVersionAndDeleteFiles>
        <ShareFiles v-if="IsShareFileShow" :ProjectId="ProjectId" :FileId="FileId"></ShareFiles>
    </section>
</template>

<script>
import UploadFile from '../../../../components/Modal/UploadFile.vue';
import DataService from '../../../../services/DataService';
import UploadNewVersion from '../../../../components/Modal/UploadNewVersion.vue';
import OldFileVersionAndDeleteFiles from '../../../../components/Modal/OldFileVersionAndDeleteFiles.vue';
import ShareFiles from '../../../../components/Modal/ShareFiles.vue';

export default {
    components: { UploadFile, UploadNewVersion, OldFileVersionAndDeleteFiles, ShareFiles },
    props: {
        projectId: { type: Number, required: true },
        checkPmUser: { type: Boolean, required: true },
        NewTabName: { type: String, required: true }
    },
    data() {
        return {
            Headers: [
                {
                    COLUMN_NAME: 'filepreview',
                    DATA_TYPE: 'string',
                    SORTABLE: false,
                    VISIBLE: true,
                    DISPLAY_NAME: 'Preview',
                    DISPLAY_ORDER: 1,
                    settings: { isInSlot: true }
                },
                {
                    COLUMN_NAME: 'FILE_TITLE',
                    DATA_TYPE: 'string',
                    SORTABLE: false,
                    VISIBLE: true,
                    DISPLAY_NAME: 'Title',
                    DISPLAY_ORDER: 2,
                    settings: { isInSlot: true }
                },
                {
                    COLUMN_NAME: 'LATEST_FILE_NAME',
                    DATA_TYPE: 'string',
                    SORTABLE: false,
                    VISIBLE: true,
                    DISPLAY_NAME: 'File Name',
                    DISPLAY_ORDER: 3,
                    settings: { isInSlot: true }
                },
                {
                    COLUMN_NAME: 'FILE_DESC',
                    DATA_TYPE: 'string',
                    SORTABLE: false,
                    VISIBLE: true,
                    DISPLAY_NAME: 'Description',
                    DISPLAY_ORDER: 4,
                    settings: { isInSlot: true }
                }
            ],
            actionButttons: [
                { title: 'OldVersion',       href: 'javascript:void(0)', callbackfunction: 'OldVersion',       icon: 'fa fa-clock-o text-success' },
                { title: 'Share',            href: 'javascript:void(0)', callbackfunction: 'ShareFiles',       icon: 'fa fa-share-alt text-primary' },
                { title: 'Download',         href: 'javascript:void(0)', callbackfunction: 'DownloadFiles',    icon: 'fa fa-download' },
                { title: 'UploadNewVersion', href: 'javascript:void(0)', callbackfunction: 'UploadNewVersion', icon: 'fa fa-upload text-success' },
                { title: 'Delete',           href: 'javascript:void(0)', callbackfunction: 'DeleteFiles',      icon: 'fa fa-trash-o text-danger' }
            ],
            listheaderbuttons: [
                {
                    title: 'Upload a File',
                    iconClass: 'fa fa-plus pr-2',
                    callbackfunction: 'OpenFileModal',
                    additionalClass: '',
                    isdisabled: false,
                    isvisible: true,
                    checkPrivilege: true,
                    id: 'OpenFileModal',
                    isEnabledOnSelectedRow: true
                },
                {
                    title: 'BacktoList',
                    iconClass: 'fa fa-angle-double-left pr-2',
                    callbackfunction: 'BackList',
                    additionalClass: '',
                    isdisabled: false,
                    isvisible: true,
                    id: 'BacktoList'
                }
            ],
            /* icon/color maps */
            iconMap: {
                doc: 'fa-file-word-o',  docx: 'fa-file-word-o',
                pdf: 'fa-file-pdf-o',
                mp4: 'fa-file-video-o', webm: 'fa-file-video-o', mov: 'fa-file-video-o', avi: 'fa-file-video-o',
                jpg: 'fa-file-image-o', jpeg: 'fa-file-image-o', png: 'fa-file-image-o', gif: 'fa-file-image-o',
                xlsx: 'fa-file-excel-o', xls: 'fa-file-excel-o',
                txt: 'fa-file-text-o',
                ppt: 'fa-file-powerpoint-o', pptx: 'fa-file-powerpoint-o'
            },
            colorMap: {
                doc: '#2b579a', docx: '#2b579a',
                pdf: '#dc2626',
                mp4: '#7c3aed', webm: '#7c3aed', mov: '#7c3aed', avi: '#7c3aed',
                jpg: '#059669', jpeg: '#059669', png: '#059669', gif: '#059669',
                xlsx: '#217346', xls: '#217346',
                txt: '#374151',
                ppt: '#d24726', pptx: '#d24726'
            },
            bgColorMap: {
                doc: '#e8f0fb', docx: '#e8f0fb',
                pdf: '#fde8e8',
                mp4: '#ede8fb', webm: '#ede8fb', mov: '#ede8fb', avi: '#ede8fb',
                jpg: '#e6f7f1', jpeg: '#e6f7f1', png: '#e6f7f1', gif: '#e6f7f1',
                xlsx: '#e6f4ec', xls: '#e6f4ec',
                txt: '#eef0f1',
                ppt: '#fdf0eb', pptx: '#fdf0eb'
            },
            /* state */
            Key: 0,
            isLoading: false,
            ListingData: [],
            TotalRecords: 0,
            SortBy: '',
            SortExp: '',
            PageNumber: 1,
            PageSize: 10,
            ProjectId: 0,
            userId: null,
            companyId: null,
            UserType: null,
            ContainerName: '',
            BlobUrl: '',
            /* modal flags */
            IsFileUploadModalShow: false,
            IsNewVersionUpload: false,
            IsOldVersionShow: false,
            IsOldVersionOrDeleteFiles: null,
            IsShareFileShow: false,
            FileId: null,
            /* view / preview */
            listType: ['Card', 'List'],
            isPreviewVisible: false,
            previewSrc: '',
            previewType: '',
            fileContent: null,
            fileName: '',
            activeMenu: null
        };
    },

    mounted() {
        document.addEventListener('click', this.closeMenu);
    },

    beforeDestroy() {
        document.removeEventListener('click', this.closeMenu);
    },

    computed: {
        googleDocsViewerSrc() {
            if (!this.previewSrc) return '';
            return `https://view.officeapps.live.com/op/embed.aspx?src=${encodeURIComponent(this.previewSrc)}`;
        }
    },

    created: async function () {
        var vm = this;
        vm.userId = vm.GetUserInfo.ID;
        vm.ProjectId = vm.projectId;
        vm.companyId = vm.GetUserInfo.CompanyId;
        vm.UserType = vm.GetUserInfo.UserType;
        vm.ContainerName = vm.GetUserInfo.ContainerName;
        vm.CheckDisabled();
        vm.GetBlobUrl();
    },

    methods: {
        /* ── header button handler ── */
        commonHeaderButtonClick(event) {
            switch (event.callbackfunction) {
                case 'OpenFileModal': this.OpenFileModal(); break;
                case 'BackList':      this.BackList();      break;
            }
        },

        /* ── action button handler ── */
        actionButtonClick(callbackfunction, item) {
            switch (callbackfunction) {
                case 'OldVersion':       this.OldVersion(item);       break;
                case 'ShareFiles':       this.ShareFiles(item);       break;
                case 'DownloadFiles':    this.DownloadFiles(item);    break;
                case 'UploadNewVersion': this.UploadNewVersion(item); break;
                case 'DeleteFiles':      this.DeleteFiles(item);      break;
            }
        },

        renderActions(row) {
            return this.actionButttons.map(a => ({ ...a, isVisible: true }));
        },

        /* ── pager / sort ── */
        pagerMethod(value) {
            this.PageSize   = value.PageSize;
            this.PageNumber = value.PageNumber;
            this.GetFilesListing();
        },

        sortdata(s) {
            this.SortBy = s;
            if (this.SortExp === '' || this.SortExp === 'DESC') {
                this.SortExp = 'ASC';
            } else {
                this.SortExp = 'DESC';
            }
            this.GetFilesListing();
        },

        /* ── menu ── */
        toggleMenu(index) {
            this.activeMenu = this.activeMenu === index ? null : index;
        },
        closeMenu() {
            this.activeMenu = null;
        },

        /* ── file type helpers ── */
        getFileExtension(filename) {
            if (!filename) return '';
            const parts = filename.split('.');
            return parts.length > 1 ? parts.pop().toLowerCase() : '';
        },

        getFileIconClass(ext) {
            return this.iconMap[ext] || 'fa-file-o';
        },

        getFileIconColor(ext) {
            return this.colorMap[ext] || '#6b7280';
        },

        getFileBgColor(ext) {
            return this.bgColorMap[ext] || '#f3f4f6';
        },

        getCardTopBorder(ext) {
            return { borderTop: `4px solid ${this.getFileIconColor(ext)}` };
        },

        isImageFile(ext) {
            return ['jpg', 'jpeg', 'png', 'gif', 'bmp'].includes(ext);
        },

        /* ── text helpers ── */
        TruncateStr(str, length) {
            if (!str) return '';
            return str.length > length ? str.substring(0, length) + '…' : str;
        },

        isJsonFileDesc(desc) {
            try {
                const obj = JSON.parse(desc);
                return !!(obj.ContentType && obj.Size && obj.Extension);
            } catch (e) {
                return false;
            }
        },

        displayDescription(desc, length) {
            if (!desc || this.isJsonFileDesc(desc)) return '';
            return this.TruncateStr(desc, length || 30);
        },

        getPreviewPath(file) {
            return (file.FILE_PATH && file.FILE_PATH.trim() !== '' && file.FILE_PATH) ||
                (file.FILE_THUMB_PATH && file.FILE_THUMB_PATH.trim() !== '' && file.FILE_THUMB_PATH) ||
                file.BlobUrl || '';
        },

        /* ── preview ── */
        previewFile(file) {
            var vm = this;
            vm.isLoading  = true;
            vm.fileContent = file;
            vm.fileName   = file.FILE_TITLE || file.LATEST_FILE_NAME;
            var ext  = (file._ext || vm.getFileExtension(file.LATEST_FILE_NAME || '')).toLowerCase();
            var path = vm.getPreviewPath(file);
            vm.previewSrc = path;

            if (['jpg', 'jpeg', 'png', 'gif', 'bmp'].includes(ext)) {
                vm.previewType = 'image';
            } else if (ext === 'pdf') {
                vm.previewType = 'pdf';
            } else if (['mp4', 'webm', 'ogg', 'mov', 'avi'].includes(ext)) {
                vm.previewType = 'video';
            } else if (['doc', 'docx', 'xls', 'xlsx', 'ppt', 'pptx'].includes(ext)) {
                vm.previewType = 'doc';
            } else {
                vm.previewType = 'unsupported';
            }
            if (!path) vm.previewType = 'unsupported';
            vm.isLoading        = false;
            vm.isPreviewVisible = true;
        },

        closePreview() {
            this.isPreviewVisible = false;
            this.previewSrc  = '';
            this.previewType = '';
            this.fileContent = null;
            this.fileName = '';
        },

        /* ── privilege check ── */
        CheckDisabled() {
            if ((this.UserType === 'CL' || this.UserType === 'NU') && this.checkPmUser) return true;
            return this.UserType === 'CA' || this.UserType === 'PM';
        },

        /* ── data loading ── */
        GetBlobUrl() {
            var vm = this;
            DataService.GetBlobUrl().then(response => {
                if (response.data.length > 0) {
                    vm.BlobUrl = response.data[0].CONFIG_DATA_VALUE + vm.ContainerName + '/Upload/UserProfileImage/';
                } else {
                    vm.BlobUrl = 'https://talygenv.github.io/Vue-UI-Content/images/user_avtar.png';
                }
                vm.GetFilesListing();
            });
        },

        GetFilesListing: async function () {
            var vm = this;
            vm.isLoading = true;
            var privilegeUrl = 'controller=ProjectFiles&action=Index';
            await DataService.CheckPrivilege(privilegeUrl).then(async response => {
                if (response.data) {
                    var params = `projectId=${vm.ProjectId}&pageSize=${vm.PageSize}&pageNum=${vm.PageNumber}&viewType=projectfiles`;
                    await DataService.GetFilesDetails(params).then(res => {
                        if (res.data.result.data.length > 0) {
                            vm.ListingData = res.data.result.data.map(item => ({
                                ...item,
                                BlobUrl: vm.BlobUrl + item.AVATAR,
                                _ext: vm.getFileExtension(item.LATEST_FILE_NAME)
                            }));
                            vm.TotalRecords = res.data.result.data[0].TOTAL_COUNT;
                        } else {
                            vm.ListingData  = [];
                            vm.TotalRecords = 0;
                        }
                    });
                } else {
                    vm.ShowAlert(vm.$t('NotAuthorizedSection'), 'failure', true, 'Alert');
                }
            });
            vm.isLoading = false;
        },

        /* ── modal openers ── */
        OpenFileModal: async function () {
            var vm = this;
            vm.isLoading = true;
            await DataService.CheckPrivilege('controller=ProjectFiles&action=Create').then(async response => {
                if (response.data) {
                    vm.IsFileUploadModalShow = true;
                } else {
                    vm.ShowAlert(vm.$t('NotAuthorizedSection'), 'failure', true, 'Alert');
                }
            });
            vm.isLoading = false;
        },

        BackList() {
            this.$router.push({ name: 'ProjectList' });
        },

        EditProject() {
            this.$emit('EditProject');
        },

        DownloadFiles: async function (obj) {
            var vm = this;           
            await DataService.CheckPrivilege('controller=ProjectFiles&action=downloadfile').then(async response => {
                if (response.data) {
                    await DataService.DownloadSingleFile(`fileId=${obj.FILE_VERSION_ID}&IsVersion=${obj.LATEST_VERSION}`).then(res => {
                        if (res.data != null) {
                            var url  = window.URL.createObjectURL(new Blob([res.data]));
                            var link = document.createElement('a');
                            link.href = url;
                            link.setAttribute('download', obj.LATEST_FILE_NAME);
                            document.body.appendChild(link);
                            link.click();
                            document.body.removeChild(link);
                        } else {
                            vm.ShowAlert(vm.$t('FileNotDownload'), 'warning', true, vm.$t('Alert'));
                        }
                    });
                } else {
                    vm.ShowAlert(vm.$t('NotAuthorizedSection'), 'failure', true, 'Alert');
                }
            });
          //  vm.isLoading = false;
        },

        UploadNewVersion: async function (item) {
            var vm = this;
            await DataService.CheckPrivilege('controller=ProjectFiles&action=UploadNewVersion').then(async response => {
                if (response.data) {
                    vm.FileId = item.FILE_ID;
                    vm.IsNewVersionUpload = true;
                } else {
                    vm.ShowAlert(vm.$t('NotAuthorizedSection'), 'failure', true, 'Alert');
                }
            });
        },

        OldVersion: async function (item) {
            var vm = this;
            vm.isLoading = true;
            await DataService.CheckPrivilege('controller=ProjectFiles&action=OldVersions').then(async response => {
                if (response.data) {
                    vm.FileId = item.FILE_ID;
                    vm.IsOldVersionOrDeleteFiles = 'OldVersion';
                    vm.IsOldVersionShow = true;
                } else {
                    vm.ShowAlert(vm.$t('NotAuthorizedSection'), 'failure', true, 'Alert');
                }
            });
            vm.isLoading = false;
        },

        DeleteFiles: async function (item) {
            var vm = this;
            vm.isLoading = true;
            await DataService.CheckPrivilege('controller=ProjectFiles&action=DeleteOption').then(async response => {
                if (response.data) {
                    vm.FileId = item.FILE_ID;
                    vm.IsOldVersionOrDeleteFiles = 'DeleteFiles';
                    vm.IsOldVersionShow = true;
                } else {
                    vm.ShowAlert(vm.$t('NotAuthorizedSection'), 'failure', true, 'Alert');
                }
            });
            vm.isLoading = false;
        },

        ShareFiles: async function (item) {
            var vm = this;
            vm.isLoading = true;
            await DataService.CheckPrivilege('controller=ProjectFiles&action=ShareFile').then(async response => {
                if (response.data) {
                    vm.FileId = item.FILE_ID;
                    vm.IsShareFileShow = true;
                } else {
                    vm.ShowAlert(vm.$t('NotAuthorizedSection'), 'failure', true, 'Alert');
                }
            });
            vm.isLoading = false;
        }
    }
};
</script>

<style>
/* ═══════════════════════════════════════════════
   FILE CARD — Card View
═══════════════════════════════════════════════ */
.fc-card {
    /* background: #ffffff; */
    border: 1px solid #e2e8f0;
    border-radius: 10px;
    display: flex;
    flex-direction: column;
    height: 100%;
    overflow: hidden;
    transition: box-shadow 0.25s ease, transform 0.25s ease;
}

.fc-card:hover {
    box-shadow: 0 6px 24px rgba(0, 0, 0, 0.10);
    transform: translateY(-2px);
}

/* Header row */
.fc-card-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 10px 12px 6px;
}

.fc-ext-badge {
    display: inline-block;
    color: #ffffff;
    font-size: 10px;
    font-weight: 700;
    letter-spacing: 0.5px;
    padding: 2px 8px;
    border-radius: 20px;
    text-transform: uppercase;
}

/* Menu trigger */
.fc-menu-wrap {
    position: relative;
}

.fc-menu-btn {
