<template>
<div>
  <loader :is-visible="isLoading"></loader>
  <transition name="modal">
    
    <div class="my-popups">
      <div class="modal d-block">
        <div class="modal-dialog modal-dialog-centered">
          <div class="modal-content">
            <div class="modal-header">
              <h4 class="modal-title">
                {{ meetingId ? $t("Edit") : $t("Add") }} {{ $t("Meetings") }}
              </h4>
              <button type="button" class="close" @click="Close">
                <i class="fa fa-times"></i>
              </button>
            </div>
            <div class="modal-body">
              <dynamic-form lang="en" :buttons="buttons" :schema="FormSchema" ref="AssignTagForm"
               >
              </dynamic-form>
              <!-- // member invite section  -->
              <div v-if="showMemberInviteSection" class="listing mt-2 col-md-12 mb-3">
                <div class="table-responsive">
                  <table id="tblMembers" class="table table-bordered dt-responsive nowrap mt-0" style="width: 100%">
                    <thead class="thead-bg">
                      <tr>
                        <th>
                          <div class="custom-control custom-checkbox">
                            <input
                              id="chkAll_3"
                              type="checkbox"
                              name="checkbox"
                              class="chkItems custom-control-input"
                                v-model="allMembersSelected"
                            /><label
                              class="custom-control-label universal-custom-control-label pt-1"
                              for="chkAll_3"
                            ></label>
                          </div>
                        </th>
                        <th class="font-weight-bold">
                          <span>Check Availability</span>
                        </th>
                        <th class="font-weight-bold"><span>User Name</span></th>
                        <th class="font-weight-bold" style="min-width: 250px">
                          <span>Email</span>
                        </th>
                        <th class="font-weight-bold">
                          <span>Designation</span>
                        </th>
                        <th class="font-weight-bold">
                          <span>Department</span>
                        </th>
                      </tr>
                    </thead>
                    <tbody>
                      <tr v-if="EventMembersList.length === 0">
                        <td colspan="6" class="text-danger text-center no-record">
                          No record(s) found
                        </td>
                      </tr>

                      <tr v-for="item in EventMembersList" :key="item.USER_ID">
                        <td>
                          <div class="custom-control custom-checkbox">
                            <input
  type="checkbox"
  class="chkItems custom-control-input"
  :id="'chk_' + item.USER_ID"
  :disabled="item.isCheckBoxDisabled"
  v-model="selectedMemberList"
:value="item.USER_ID"
/>
                            <label
                              class="custom-control-label universal-custom-control-label pt-1"
                              :for="'chk_' + item.USER_ID"
                            ></label>
                          </div>
                        </td>

                        <td class="text-center">-</td>

                        <td>{{ item.USER_NAME }}</td>

                        <td>{{ item.ALIASNAME }}</td>

                        <td>{{ item.DESIGNATION_NAME || "-" }}</td>

                        <td>{{ item.DEPARTMENT || "-" }}</td>
                      </tr>
                    </tbody>
                  </table>
                </div>
              </div>

              <!-- // client invite section -->
              <div v-if="showClientInviteSection" class="listing mt-2 col-md-12 mb-3">
                <div class="table-responsive">
                  <table id="tblInviteClients" class="table table-bordered dt-responsive nowrap mt-0"
                    style="width: 100%">
                    <thead class="thead-bg">
                      <tr>
                        <th>
                          <div class="custom-control custom-checkbox">
                            <input
                              type="checkbox"
                              name="checkbox"
                              class="chkItems custom-control-input"
                              id="chk_5"
                              v-model="allClientsSelected"
                            /><label
                              class="custom-control-label universal-custom-control-label pt-1"
                              for="chk_5"
                            ></label>
                          </div>
                        </th>
                        <th class="text-center font-weight-bold">
                          <span>Check Availability</span>
                        </th>
                        <th class="font-weight-bold"><span>User Name</span></th>
                        <th class="font-weight-bold" style="min-width: 250px">
                          <span>Email</span>
                        </th>
                        <th class="font-weight-bold"><span>Status</span></th>
                      </tr>
                    </thead>
                    <tbody>
                      <tr v-if="EventClientsList.length === 0">
                        <td colspan="5" class="text-danger text-center no-record">
                          No record(s) found
                        </td>
                      </tr>

                      <tr v-for="item in EventClientsList" :key="item.USER_ID">
                        <td>
                          <div class="custom-control custom-checkbox">
                          <input
                              type="checkbox"
                              class="chkItems custom-control-input"
                              :id="'chk_client_' + item.USER_ID"
                              :value="item.USER_ID"
                               v-model="selectedClientList"
                            />
                            <label
                              class="custom-control-label universal-custom-control-label pt-1"
                              :for="'chk_client_' + item.USER_ID"
                            ></label>
                          </div>
                        </td>

                        <td class="text-center">-</td>

                        <td>{{ item.CLIENTNAME }}</td>

                        <td>{{ item.EMAIL_ID }}</td>

                        <td>{{ item.COUNTRYNAME || "-" }}</td>
                      </tr>
                    </tbody>
                  </table>
                </div>
              </div>
              <div class="row"><div class="col-6"><div class="py-2"><span class="mandatory">Fields marked with an asterisk (*) are mandatory.</span></div></div><!----><div class="text-end text-right col-6"><button type="submit" @click="OnSubmit" class="btn btn-success"><i class="fa fa-save pr-2"></i>Save</button><!----><!----><button type="button" @click="Close" class="btn btn-danger" style="margin-left: 5px;"><i class="fa fa-close pr-2"></i>Cancel</button></div></div>
            </div>
          </div>
        </div>
      </div>
    </div>
  </transition>
</div>
</template>

<script>
import DataService from "@/services/DataService";
export default {
  name: "ModalAddMeeting",
  props: {
    meetingId: {
      type: String || Number,
      Request: false
    }
  },
  data() {
    return {
      isLoading : false,
      isVenue: 0,
      MandatoryString: "Fields marked with an asterisk (*) are mandatory.",
      FormSchema: [
        {
          layoutType: "triple",
          Data: [
            {
              astype: "TextField",
              label: this.$t("Subject"),
              name: "Subject",
              value: "",
              placeholder: this.$t("Subject"),
              validationRules: { required: true, max: 100 },
            },
            {
              astype: "TextField",
              label: this.$t("Agenda"),
              name: "Agenda",
              value: "",
              placeholder: this.$t("Agenda"),
              validationRules: { required: false, max: 100 },
            },
            {
              astype: "TextField",
              label: this.$t("Speaker"),
              name: "Speaker",
              value: "",
              placeholder: this.$t("Speaker"),
              validationRules: { required: false, max: 100 },
            },
            {
              astype: "CheckBoxField",
              label: this.$t("EventIsAllDay"),
              name: "ExpenseAllowed",
              value: "",
              placeholder: "",
              config: {
                options: [
                  {
                    name: "",
                    value: "1",
                  },
                ],
                showAddIcon: false,
                onChange: this.GetCheckBoxValue,
              },
            },
            {
              astype: "RadioField",
              label: "Accessibility",
              name: "Accessibility",
              value: "1",
              placeholder: "",
              disabled: false,
              chktxtIndex: 0,
              value: '1',
              config: {
                options: [
                  { value: "1", name: "Public" },
                  { value: "2", name: "Private" },
                ],
                onchange: this.GetChangeAccessibility,
              },
              validationRules: "required",
            },
            {
              astype: "DateField",
              label: this.$t("StartDate"),
              disabled: false,
              name: "StartDate",
              value: new Date(),
              placeholder: this.$t("StartDate"),
              validationRules: {
                required: true,
              },
              config: {
                mode: "date",
                format: "M/D/YYYY",
              },
            },
            {
              astype: "DateField",
              label: this.$t("EndDate"),
              disabled: false,
              name: "EndDate",
              value: new Date(),
              placeholder: this.$t("EndDate"),
              validationRules: {
                required: true,
              },
              config: {
                mode: "date",
                format: "M/D/YYYY",
              },
            },
            {
              astype: "TextField",
              label: this.$t("ContactPerson"),
              name: "ContactPerson",
              value: "",
              placeholder: this.$t("ContactPerson"),
              validationRules: { required: false, max: 100 },
            },
            {
              astype: "NumericField",
              label: this.$t("PhoneNumber"),
              name: "PhoneNumber",
              value: "",
              placeholder: this.$t("PhoneNumber"),
              validationRules: { required: false, max: 100 },
            },
            {
              astype: "TextField",
              label: this.$t("Email"),
              name: "Email",
              value: "",
              placeholder: this.$t("Email"),
              validationRules: { required: true, max: 100, email: true },
            },
            {
              astype: "TextField",
              label: this.$t("Venue"),
              name: "Venue",
              value: "",
              placeholder: this.$t("Venue"),
              validationRules: { required: true, max: 100 },
              visibility: false, // 🔥 default false

            },
            {
              astype: "SelectField",
              label: this.$t("Recurring"),
              name: "Recurring",
              value: "1",
              config: {
                options: [
                  { value: 1, name: "Single" },
                  { value: 2, name: "Daily" },
                  { value: 3, name: "Weekly" },
                  { value: 4, name: "Monthly" },
                  { value: 5, name: "Annually" },
                ],
              },
              placeholder: this.$t("Select Recurring"),
              validationRules: { required: true, max: 100 },
            },
            {
              astype: "SelectField",
              label: this.$t("Meeting Reminder"),
              name: "Meeting Reminder",
              value: "",
              config: {
                options: [
                  { value: 1, name: "Rem_No_Reminder" },
                  { value: 2, name: "Rem_5_Minutes" },
                  { value: 3, name: "Rem_10_Minutes" },
                  { value: 4, name: "Rem_15_Minutes" },
                  { value: 5, name: "Rem_30_Minutes" },
                  { value: 6, name: "Rem_1_Hour" },
                ],
              },
              placeholder: this.$t("Select Meeting Reminder"),
              validationRules: { required: true, max: 100 },
            },
            {
              astype: "SelectField",
              label: this.$t("Priority"),
              name: "Priority",
              value: "",
              config: {
                options: [],
              },
              placeholder: this.$t("Select Priority"),
              validationRules: { required: true, max: 100 },
            },
            {
              astype: "CheckBoxField",
              label: this.$t("Invite_Member"),
              name: "Invite_Member",
              value: "",
              placeholder: "",
              config: {
                options: [
                  {
                    name: "",
                    value: "1",
                  },
                ],
                showAddIcon: false,
                onChange: this.GetCheckBoxValue,
              },
            },
            {
              astype: "CheckBoxField",
              label: this.$t("Invite_Client"),
              name: "Invite_Client",
              value: "",
              placeholder: "",
              config: {
                options: [
                  {
                    name: "",
                    value: "1",
                  },
                ],
                showAddIcon: false,
                onChange: this.GetCheckBoxValue,
              },
            },
          ],
        },
        {
          layoutType: "single",
          Data: [
            {
              astype: "TextAreaField",
              label: this.$t("Description"),
              name: "Description",
              value: "",
              validationRules: { required: false },
              config: {
                rows: 5,
              },
            },
          ],
        },
      ],
      buttons: [
        {
          type: "submit",
          class: "btn btn-success",
          text: "<i class='fa fa-save pr-2'></i>Save",
          isVisible: false
        },
        {
          type: "button",
          class: "btn btn-danger",
          text: "<i class='fa fa-close pr-2'></i>Cancel",
          isVisible: false,
          onClick: this.Close,
        },
      ],
      EventClientsList: [],
      EventMembersList: [],
      selectedClientList : [],
      selectedMemberList : [],
      IfAvailable: 0,
      IfAvailableUserId: 0,
      showMemberInviteSection: false,
      showClientInviteSection: false,
      ProjectId:0,
    };
  },

  watch: {
    isVenue: {
      immediate: true,
      handler(val) {
        const venueField = this.FormSchema[0].Data.find(
          f => f.name === "Venue"
        );

        if (venueField) {
          this.$set(venueField, "visibility", val == 1);
        }
      }
    }
  },
  created() {
    debugger
    var vm=this;
    vm.ProjectId=parseInt(vm.$route.params.projectId);
    this.GetProjectPriority();
    this.GetEventMembers();
    this.GetEventClients();
    this.meetingId ? this.GetMettingbyId(this.meetingId) : '';
  },
  computed: {
  allMembersSelected: {
    get() {
      return (
        this.EventMembersList.length > 0 &&
        this.selectedMemberList.length === this.EventMembersList.length
      );
    },
    set(value) {
      if (value) {
        this.selectedMemberList = this.EventMembersList.map(
          item => item.USER_ID
        );
      } else {
        this.selectedMemberList = [];
      }
    }
  },
    allClientsSelected: {
    get() {
      return (
        this.EventClientsList.length > 0 &&
        this.selectedClientList.length === this.EventClientsList.length
      );
    },
    set(value) {
      if (value) {
        this.selectedClientList = this.EventClientsList.map(
          item => item.USER_ID
        );
      } else {
        this.selectedClientList = [];
      }
    }
  }
},
  methods: {
    handleMemberSelection(event, userId) {
  if (event.target.checked) {
    if (!this.selectedMemberList.includes(userId)) {
      this.selectedMemberList.push(userId);
    }
  } else {
    this.selectedMemberList = this.selectedMemberList.filter(
      id => id !== userId
    );
  }

  
},

handleClientSelection(event, userId) {
  if (event.target.checked) {
    if (!this.selectedClientList.includes(userId)) {
      this.selectedClientList.push(userId);
    }
  } else {
    this.selectedClientList = this.selectedClientList.filter(
      id => id !== userId
    );
  }

  
},
   GetCheckBoxValue(fieldName, value) {
  if (value.name === "Invite_Member") {
    const isChecked = value.value && value.value.length > 0;

    this.showMemberInviteSection = isChecked;

    if (!isChecked) {
      this.selectedMemberList = [];   // 🔥 clear selection
    }
  }

  if (value.name === "Invite_Client") {
    const isChecked = value.value && value.value.length > 0;

    this.showClientInviteSection = isChecked;

    if (!isChecked) {
      this.selectedClientList = [];   // 🔥 clear selection
    }
  }
},

    async GetEventMembers() {
      // const postString = JSON.stringify({ eventId: this.eventId });
      // const postString  = `?projectId=${this.$router.params.projectId }`
      const postString = `projectId=${this.ProjectId}&pageSize=100&pageNum=1`;
      try {
        const response = await DataService.GetTeamListing(postString);
        this.EventMembersList = response?.data?.result?.data || [];
      } catch (error) {
      }
    },
    async GetEventClients() {
       try {
               const postString = `projectId=${this.ProjectId}&pageSize=10&pageNum=1`;
      const response = await DataService.GetClientListing(postString);
      this.EventClientsList = response?.data?.result?.data || [];
       } catch (error) {
         
       }

    },

    GetProjectPriority() {
      var url = `id=&moduleName=PROJECT&type=PRIORITY&search=&refId=`;
      DataService.GetDDLData(url).then((response) => {
        if (response.status == 200) {
          if (response.data.DATA != undefined || response.data.DATA != null) {
            if (response.data.DATA.length > 0) {
              var PriorityData = response.data.DATA;
              PriorityData.forEach((element) => {
                let obj = {
                  name: element.name,
                  value: element.value,
                };
                this.FormSchema[0].Data[13].config.options.push(obj);
              });
              this.$refs.AssignTagForm.UpdateKeyValue();
            }
          }
        }
      });
    },
    async GetMettingbyId(id) {
  const vm = this;
  this.isLoading = true;

  try {
    const response = await DataService.GetMeetingDataById(`id=${id}`);

    if (response.data && response.data.data.length > 0) {
      const meeting = response.data.data[0];

      vm.MeetingId = meeting.MEETING_ID;
      vm.FormSchema[0].Data[0].value = meeting.SUBJECT;
      vm.FormSchema[0].Data[1].value = meeting.AGENDA;
      vm.FormSchema[0].Data[2].value = meeting.SPEAKER;
      vm.FormSchema[0].Data[3].value = meeting.IS_ALL_DAY;
      vm.FormSchema[0].Data[4].value = meeting.ACCESSIBILITY;
      vm.FormSchema[0].Data[5].value = vm.$d(new Date(meeting.START_DATE_TIME));
      vm.FormSchema[0].Data[6].value = vm.$d(new Date(meeting.END_DATE_TIME));
      vm.FormSchema[0].Data[7].value = meeting.CONTACT_PERSON;
      vm.FormSchema[0].Data[8].value = meeting.PHONE_NUMBER;
      vm.FormSchema[0].Data[9].value = meeting.EMAIL;
      vm.FormSchema[0].Data[10].value = meeting.VENUE;
      vm.FormSchema[0].Data[11].value = meeting.RECURRING;
      vm.FormSchema[0].Data[12].value = meeting.MEETING_REMINDER;
      vm.FormSchema[0].Data[13].value = meeting.PRIORITY;
      // vm.FormSchema[0].Data[14].value = 1;
      vm.FormSchema[0].Data[15].value = meeting.DESCRIPTION;

      // 🔥 Handle Members
         if (meeting.MEMBERS_LIST && meeting.MEMBERS_LIST !== "") {
              this.showMemberInviteSection = true;

  this.selectedMemberList = meeting.MEMBERS_LIST
    .split(",")
    .map(id => Number(id)); // convert to number

  // also update dynamic form checkbox
  const inviteMemberField = this.FormSchema[0].Data.find(
    f => f.name === "Invite_Member"
  );

  if (inviteMemberField) {
    inviteMemberField.value = ["1"]; // checkbox expects array
  }
}

// 🔥 Handle Clients
if (meeting.CLIENT_LIST && meeting.CLIENT_LIST !== "") {
  this.showClientInviteSection = true;

  this.selectedClientList = meeting.CLIENT_LIST
    .split(",")
    .map(id => Number(id));

  const inviteClientField = this.FormSchema[0].Data.find(
    f => f.name === "Invite_Client"
  );

  if (inviteClientField) {
    inviteClientField.value = ["1"];
  }
}

      // Optional members logic
      // if (meeting.MEMBERS_LIST && meeting.MEMBERS_LIST !== '[]') {
      //   vm.isSelected(meeting.MEMBERS_LIST);
      //   vm.FormSchema[0].Data[15].value = 1;
      // }
    }
  } catch (error) {
    console.error("Error fetching meeting by ID:", error);
    // vm.$toast?.error?.("Failed to load meeting data");
  } finally {
    this.isLoading = false;
  }
},
    //   isSelected(userId) {
    //     debugger
    //   return this.MEMBERS_LIST.split(',').includes(userId.toString());
    // },
    Close() {
      this.$emit('close')
    },
    async OnSubmit() {


  const isValid = await this.$refs.AssignTagForm.validateForm.validate();

  if(!isValid)
  {
    return null
  }
  
   
  // 🔥 collect form data

  const formfields = Object.fromEntries(
  this.FormSchema.flatMap(group =>
    group.Data.map(field => [field.name, field.value])
  )
);

  console.log("Form Data:", formfields);

  const body = {
    EVENT_ID: this.meetingId || 0,
    PROJECT_ID: this.ProjectId,
    PARENT_ID : 0,
    COMPANY_ID : this.GetUserInfo.CompanyId,
    USER_ID : this.GetUserInfo.ID,
    LOCATION_ID : 0,
    LOCATION_NAME :"",

    SUBJECT: formfields.Subject,
    AGENDA: formfields.Agenda,
    VENUE: this.isVenue == 1 ? formfields.Venue : null,

    PRIORITY: formfields.Priority,
    RECURRING: formfields.Recurring,
    MEETING_REMINDER: formfields["Meeting Reminder"],

    DESCRIPTION: formfields.Description,

    IS_ALL_DAY: formfields.ExpenseAllowed ? true : false,
    SPEAKER: formfields.Speaker,
    ACCESSIBILITY: formfields.Accessibility,

    START_DATE: formfields.StartDate,
    END_DATE: formfields.EndDate,

    CONTACT_PERSON: formfields.ContactPerson,
    PHONE_NUMBER: formfields.PhoneNumber,
    EMAIL: formfields.Email,

    MEMBERS_LIST: this.showMemberInviteSection
      ? this.selectedMemberList.join(",")
      : "",

    CLIENT_LIST: this.showClientInviteSection
      ? this.selectedClientList.join(",")
      : ""
  };

     this.isLoading = true
     
     try {
          let response  = await DataService.SaveMeeting(JSON.stringify(body))
            if(response?.data?.status.toLowerCase() == 'failure')
            {
               this.ShowAlert("Something went wrong", "error", true, this.$t("Alert"));
               return null
            }

            if (response?.data?.status.toLowerCase() == 'success')
            {        this.$emit('saved')
                     this.$emit('close')
            }
         
     } catch (error) {
           this.ShowAlert("Something went wrong", "error", true, this.$t("Alert"));
     } finally {
       this.isLoading = false
     }
      
    },
    },
  
};
</script>
