<template>
<section>
    <loader :is-visible="isLoading"></loader>
    <div id="modalAddView" role="dialog" class="modal my-popups right fade rightmodalcssfixs">
     
        <div role="document" class="modal-dialog mw-800">
                <div class="modal-content">
                    <div class="modal-header mheader-user">
                        <h4 class="modal-title">{{ $t('Add') }} {{ $t('View') }} </h4>
                        <button type="button" class="close" v-on:click="CloseAddView">
                            <em class="fa fa-times" aria-hidden="true"></em>
                        </button>
                    </div>
                    <div class="modal-body">
                           <div class="bg-white border p-4 float-left w-100">
                        <div class="row">
                            <div class="col-12 p-0">
                                <ul
                                    class="shortcuts-menu pb-3 connectedSortable advancedsetup newaddprojects innertabs_bases">
                                    <li class="position-relative clients" id="selectviewtab"
                                        v-for="(item, index) in Tablistingdata" :key="index"
                                        title="" @click="Selectedtabs(item)">
                                        <a href="javascript:;"
                                            :class="['short-menu-item', { 'gen-templateadded': item.isActive,'mandatoryy': item.isActive && item.isMandatory }]">
                                            <span><em
                                                    :class="['fa', item.feature_icon, 'mr-2']"></em></span>                                            
                                             <span class="short-item-name">{{ $t(getTabDisplayName(item.feature)) }}</span>
                                            <span v-if="item.isActive"
                                                :class="['state-check', item.isMandatory ? 'active-check' : 'mandatory-check ']"
                                                aria-hidden="true">
                                                <em class="fa fa-check"></em>
                                            </span>
                                        </a>
                                    </li>
                                </ul>
                            </div>
                        </div>
                       <div class="row flex-row-reverse mt-3">
                            <div class="col-md-12 text-right">
                                <a href="javascript:;" title="Save" v-on:click="SaveView" class="submitbtn btn btn-success formbtn detailview mr-2">
                                    <i class="fa fa-save pr-2"></i>{{ $t('Save') }}
                                </a>
                                <a href="javascript:;" title="Cancel" v-on:click="CloseAddView" class="btn btn-danger formbtn widthhalf">
                                    <i class="fa fa-close pr-2"></i>{{ $t('Cancel') }}
                                </a>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    </div> 
</section>
</template>
<script>
import DataService from '../../../../services/DataService'
export default {
    name: 'AddView',
    props: {
        TemplateIndustryTypeId:{
            type: Object
        },
        ProjectIndusrtyType:{
            type:String
        },
        TemplateId:{
            type:Number
        }
    },
    data() {
        return {
            isLoading: false,
            ShowSelectedIndustry: '',
            Tablistingdata:[],
            ExistTabsData:[],
            ProjectId:0
        }
    },
    created:function() {
        var ths=this;            
        ths.ProjectId = ths.$route.params.projectId;
        ths.GetTemplatesByProjectId();

    },
    methods: {
        getTabDisplayName(tabFeature){            
            var ShowSelectedIndustry=this.ProjectIndusrtyType;
            let tabname = ''; 
            if (ShowSelectedIndustry === 'Construction') {
                if (tabFeature === 'Project Phase') {
                    tabname = 'Phase';
                } else if (tabFeature === 'Project Stage') {
                    tabname = 'Stage';
                } else if (tabFeature === 'Milestones') {
                    tabname = 'Milestone';                
                } else if (tabFeature === 'Team') {
                    tabname = 'WorkCrew';                   
                } else if (tabFeature === 'Files') {
                    tabname = 'Documents';
                }
            }
            // Marketing industry type mappings
            else if (ShowSelectedIndustry === 'Marketing') {                
                if (tabFeature === 'BackLog') {
                    tabname = 'campaignplan';
                } else if (tabFeature === 'Sprint') {
                    tabname = 'CampaignCycle';
                } else if (tabFeature === 'Project Phase') {
                    tabname = 'CampaignPhase';
                } else if (tabFeature === 'Project Stage') {
                    tabname = 'CampaignStep';
                } else if (tabFeature === 'Tasks') {
                    tabname = 'campaigntask';
                } else if (tabFeature === 'Milestones') {
                    tabname = 'campaignmilestone';
                } else if (tabFeature === 'Team') {
                    tabname = 'marketingteam';
                }
            }
            else if (ShowSelectedIndustry === 'Design') {                
                if (tabFeature === 'BackLog') {
                    tabname = 'DesignBacklog';
                }else if (tabFeature === 'Sprint') {
                    tabname = 'UXSprint';
                } 
                else if (tabFeature === 'Project Phase') {
                    tabname = 'UIDesignPhase';
                } else if (tabFeature === 'Project Stage') {
                    tabname = 'UXStage';
                } else if (tabFeature === 'Tasks') {
                    tabname = 'DesignTask';
                } else if (tabFeature === 'Milestones') {
                    tabname = 'DesignMilestone';
                } else if (tabFeature === 'Team') {
                    tabname = 'UIDesignTeam';
                }
            }

            else if (ShowSelectedIndustry === 'Sales') {
                if (tabFeature === 'BackLog') {
                    tabname = 'DealBacklog';
                }else if (tabFeature === 'Sprint') {
                    tabname = 'SalesCycle';
                } 
                else if (tabFeature === 'Project Phase') {
                    tabname = 'PipelinePhase';
                } else if (tabFeature === 'Project Stage') {
                    tabname = 'DealStage';
                } else if (tabFeature === 'Tasks') {
                    tabname = 'SalesTask';
                } else if (tabFeature === 'Milestones') {
                    tabname = 'DealMilestone';
                } else if (tabFeature === 'Team') {
                    tabname = 'SalesTeam';
                }
            } 
            return tabname !== '' ? tabname : tabFeature;
        },
        Selectedtabs(item) {
            if (item.is_required == 0) {
                item.isActive = !item.isActive;
                item.isSelected = item.isActive;
            }
        },
        CloseAddView() {
            this.$emit('CloseAddView');
        },
        SaveView() {            
            this.isLoading = true;                   
          var newtabArray= this.Tablistingdata.filter(item => item.isSelected);            
          var Obj={
            tabs:newtabArray,
            ProjectId:this.ProjectId,
            TemplateId:this.TemplateIndustryTypeId.TemplateId
          }
          var url=JSON.stringify(Obj);
          DataService.SaveProjectView(url).then((response) =>{             
              if (response.data.result == 'SUCCESS') {
                  this.ShowAlert(this.$t('AddedSuccess', [this.$t('Project')]), "success", true, this.$t("Alert"));
                  this.CloseAddView();
              }
             this.isLoading = true; 
          });
        },
        GetTemplatesByProjectId() {
            this.isLoading = true;
            this.Tablistingdata = [];
            var url = `TemplateId=${this.TemplateIndustryTypeId.TemplateId}&IndustryId=${this.TemplateIndustryTypeId.IndustryTypeId}&ProjectId=${this.ProjectId}`
            DataService.GetTemplatesByProjectId(url).then((response) => {                
                this.isLoading = false;
                if (response.data != '') {
                    
                    var Data = JSON.parse(response.data.result);
                    this.Tablistingdata = Data.DATA;
                    this.ExistTabsData=Data.EXISTTABDATA;
                    
                    this.Tablistingdata.forEach((element) => {                       
                        const existsInExistTabs = this.ExistTabsData.some(existTab => {                            
                            return (existTab.feature && element.feature && existTab.feature === element.feature) ||
                                   (existTab.FEATURE && element.feature && existTab.FEATURE === element.feature) ||
                                   (existTab.id && element.id && existTab.id === element.id) ||
                                   (existTab.feature_id && element.feature_id && existTab.feature_id === element.feature_id);
                        });                        
                        if (element.is_required) {
                            this.$set(element, 'isActive', true);
                            this.$set(element, 'isSelected', true);
                            this.$set(element, 'isMandatory', true);
                        }
                        else if (existsInExistTabs) {                           
                            this.$set(element, 'isActive', true);
                            this.$set(element, 'isSelected', true);
                        }
                        else {
                            this.$set(element, 'isActive', false);
                            this.$set(element, 'isSelected', false);
                        }

                    });
                } else {
                    this.Tablistingdata = [];
                }

            });
        },
    }
}
</script>

<style scoped>
.short-menu-item {
    display: flex;
    align-items: center;
    position: relative;
    width: 100%;
    min-height: 52px;
    padding: 10px 12px;
    border-radius: 8px;
    border: 1px solid #e3e7ee;
    background: #ffffff;
    text-decoration: none;
    color: inherit;
}



.short-item-name {
    flex: 1 1 auto;
    min-width: 0;
    padding-right: 4px;
    white-space: pre-line;
    line-height: 1.2;
    font-size: 14px;
    font-weight: 600;
    color: #2c3e50;
}

/* Selected/active tab visual */
.short-menu-item.gen-templateadded {
    padding: 10px 12px !important;
    border-radius: 8px;
    border: 1px solid #a9c8f6 !important;
    background: #f6faff !important;
}

.short-menu-item.gen-templateadded .left-icon-m {
    background: #e7f1ff !important;
    border: 1px solid #b7d0f5 !important;
}

/* Mandatory + active state only */
.short-menu-item.mandatoryy {
    padding: 10px 40px 10px 12px !important;
    border-radius: 8px;
    border: 1px solid #2f80ff !important;
    background: #ffffff !important;
    box-shadow: 0 0 0 1px rgba(47, 128, 255, 0.06);
}

.short-menu-item.mandatoryy .left-icon-m {
    background: #eaf4ff !important;
    border: 1px solid #2f80ff !important;
}

.state-check {
    position: absolute;
    top: 16px;
    right: 8px;
    width: 18px;
    height: 18px;
    border-radius: 999px;
    display: flex;
    align-items: center;
    justify-content: center;
    box-shadow: 0 0 0 2px #eef0ff;
}

.active-check {
    border: 1px solid #ff6d6d !important;
    background: #ff6d6d !important;
    color: #ffffff !important;
}

.mandatory-check {
    border: none !important;
    background: #56a3f5 !important;
    color: #ffffff !important;
}

.state-check .fa {
    font-size: 10px;
}

.shortcuts-menu li .short-menu-item{background: #fff!important;     border: 1px solid #adb1b7;}
.shortcuts-menu li .short-menu-item .short-item-name{ font-weight:400;}

.shortcuts-menu.newaddprojects li {
    max-width: 25% !important;
}
</style>