        bindComponentBoardChartDataa(dataa) {
    if (!dataa || dataa.length === 0) return;

    // Store full data for tooltip usage
    this.fullBaordData = dataa;

    // Prepare categories (board names)
    const categories = dataa.map(item => item.BOARD_NAME || "Board");

    // Calculate total task count for each board
    const values = dataa.map(item => {
        // Sum the task counts for each board's stages
        return item.board_statuses.reduce((sum, board_statuses) => sum + board_statuses.task_count, 0);
    });

    // Assign to boardSeries with total task count values
    this.boardSeries = [{
        name: "Task Count",
        data: values  // Using task count as bar height
    }];

    // Set categories for the x-axis
    this.$set(this.boardChartOptions.xaxis, 'categories', categories);

    // Trigger chart re-render
    this.chartKey++;
},
        bindComponentMilestoneChartDataa(data) {
            if (!data || !data.length) {
                this.mileseries = [];
                this.$set(this.milestoneChartOptions, 'labels', []);
                this.$set(this.milestoneChartOptions, 'colors', []);
                return;
