            data.forEach(item => {
                labels.push(
                    item.STATUS_NAME
                        ? item.STATUS_NAME.charAt(0).toUpperCase() + item.STATUS_NAME.slice(1).toLowerCase()
                        : "Milestone"
                );
                counts.push(Number(item.TOTAL) || 0);
                if (Array.isArray(item.MILESTONE_NAME)) {
                    milestoneDetails.push(item.MILESTONE_NAME.map(m => m.MILESTONE_NAME));
                } else {
                    milestoneDetails.push((item.MILESTONE_NAME || "").split(","));
                }
            });
            this.milestoneDetails = milestoneDetails;
            this.milestoneChartOptions = {
                ...this.milestoneChartOptions,
