        bindComponentAssignChartDataa(data) {

        if (!data || !data.length) {
            this.teamseries = [];
            this.$set(this.teamChartOptions.xaxis, 'categories', []);
            this.$set(this.teamChartOptions, 'colors', []);
            return;
        }

        const users = [...new Set(
            data
                .map(item => (item.USER_NAME || "").trim())
                .filter(name => name !== "")
        )];
        const statuses = [...new Set(data.map(item => item.STATUS_NAME))];

        const statusColorMap = {};
        data.forEach(item => {
            if (!statusColorMap[item.STATUS_NAME]) {
                statusColorMap[item.STATUS_NAME] = item.STATUS_BG_COLOR || "#008FFB";
            }
        });

        const series = statuses.map(status => {

            const statusData = data.filter(d => d.STATUS_NAME === status);

            return {
                name: status,
                data: users.map(user => {
                    const found = statusData.find(d => d.USER_NAME === user);
                    return found ? Number(found.TOTAL) : 0;
                })
            };
        });
        const statusColors = statuses.map(status => statusColorMap[status]);
        this.$set(this.teamChartOptions.xaxis, 'categories', users);
        this.$set(this.teamChartOptions, 'colors', statusColors);
        this.teamseries = series;
        this.chartKey++;
        },
        bindComponentExpenseChartDataa(data) {
