                this.weeklyseries = [];
                this.$set(this.budgetChartOptions.xaxis, 'categories', []);
                return;
            }
            const categories = data.map(item => item.CATEGORY_NAME);
            const totalAmounts = data.map(item => item.CATEGORY_TOTAL_AMOUNT);
            const usedAmounts = data.map(item => item.USED_AMOUNT);
            const series = [
                {
                    name: "Budget",
                    data: totalAmounts
                },
                {
                    name: "Spend",
                    data: usedAmounts
                }
            ];
            this.$set(this.budgetChartOptions.xaxis, 'categories', categories);
            this.budgetseries = series;
            this.$set(this.budgetChartOptions, 'colors', ['#008ffb', '#FF0000']);
            this.$set(this.budgetChartOptions.xaxis, 'labels', {
                rotate: -45,
                style: {
