<template>
<div class="my-popups">
    <loader :is-visible="isLoading"></loader>
    <div class="modal d-block">
        <div class="modal-dialog modal-dialog-centered mw-800">
            <div class="modal-content">
                <div class="modal-header theme-primary partition-full d-flex">
                    <h4 class="modal-title">New Discussion</h4>
                    <button type="button" class="close" v-on:click="Close">
                        <em class="fa fa-times" aria-hidden="true"></em>
                    </button>
                </div>
                <div class="modal-body">
                    <dynamic-form lang="en" :buttons="buttons" :schema="FormSchema" ref="DiscussionForm" :mandatorytext='MandatoryString'
                            v-on:OnSubmit="onSubmit">
                             <template v-slot:tgslot-DiscussionType="{ data }">
                                <div class="form-check mb-2">
                                    <input class="form-check-input" type="radio" name="discussiontype" id="publicChannel" value="public" v-model="discussiontype" />
                                    <div class="ml-2">
                                        <label class="form-check-label w-100" for="publicChannel">
                                            <div class="d-flex align-items-center">
                                                <em class="fa fa-globe mr-2"></em>
                                                {{ $t('Public') }}
                                            </div>
                                        </label>
                                        <small class="text-muted d-block ms-4">{{$t('Anyoneintheproject')}}</small>
                                    </div>
                                </div>
                                <div class="form-check">
                                    <input class="form-check-input" type="radio" name="discussiontype" id="privateChannel" value="private" v-model="discussiontype" />
                                    <div class="ml-2">
                                        <label class="form-check-label w-100" for="privateChannel">
                                            <div class="d-flex align-items-center">
                                                <em class="fa fa-lock mr-2"></em>
                                                {{$t('Private')}}
                                            </div>
                                        </label>
                                        <small class="text-muted d-block ms-4">{{$t('onlyselectedmembers')}}</small>
                                    </div>
                                </div>
                            </template>
                        </dynamic-form>   
                </div>
            </div>
        </div>
    </div>
</div>
</template>

<script>
import DataService from '../../services/DataService';
export default {
    props: {
        projectId: {
            type: Number,
            required: true,
        },
        DiscussionId: {
            type: Number,
            required: true,
        }
    },
    data() {
        return {
            isLoading: false,           
            discussiontype: 'public',
            DirectUserData: [],
            DiscussionId: 0,
            PageSize: 200,
            PageNumber: 1,
            MandatoryString:'Fields marked with an asterisk (*) are mandatory.',
            FormSchema: [               
                {
                    layoutType: "single",
                    Data: [
                        {
                            astype: "TextField",                                                
                            label: this.$t('Discussion Title'),
                            name: "Discussion Title",
                            value: "",                            
                            placeholder: this.$t('Enter Discussion Name'),
                            validationRules: { "required": true, max: 100 },
                        },
                        {
                            astype: "TextAreaField",                                                
                            label: this.$t('Description'),
                            name: "Description",
                            value: "",                           
                            placeholder: this.$t('Enter Description'),
                            validationRules: { "required": false, max: 4000 },
                            config: {
                                rows:3
                            }
                        },
                        {
                            astype: "SlotField",
                            label: this.$t('Discussion Type'),
                            name: "DiscussionType",
                            visibility: true,
                            value: "",
                            placeholder: "",
                            validationRules: {
                                "required": false
                            }
                        },  
                        {
                            astype: "MultiSelectField",                                                
                            label: this.$t('User'),
                            name: "User",
                            mode: "tag",
                            multiple:true,
                            visibility:false,      
                            value: [], 
                            config: {
                                options: []
                            },                           
                            placeholder: this.$t('Select Users'),
                            validationRules: { "required": false, max: 100 },
                        }                   
                    ]
                }                
            ],
            buttons: [
                {
                    type: "submit",
                    class: "btn btn-success",
                    text: "<i class='fa fa-save pr-2'></i>Save Discussion",
                    isVisible:true
                },            
                {
                    type: "button",
                    class: "btn btn-danger",
                    text: "<i class='fa fa-close pr-2'></i>Cancel",
                    onClick: this.Close,
                },
            ],
            UserName: '',
            UserType: ''
        }
    },
    watch: {       
        discussiontype(newVal) {
            const userField = this.FormSchema[0].Data[3];
            if (newVal === "private") {
                userField.visibility = true;
                userField.validationRules.required = true;
            } else {
                userField.visibility = false;
                userField.validationRules.required = false;
                // Clear the user field value when switching to public
                userField.value = [];
            }
        }
    },
    async created() {
        var vm = this
        vm.UserType = this.GetUserInfo.UserType;
        vm.UserName = this.GetUserInfo.Name;
        await this.FetchTeam();
        if (this.DiscussionId > 0) {
            this.GetProjectDiscussions();
        }
    },
    methods: {
        GetProjectDiscussions: async function () {
            var vm = this;
            var url = `DiscussionId=${this.DiscussionId}&ProjectId=${this.projectId}&SearchTitle=&DiscussionType=&statusId=`;
            await DataService.GetProjectDiscussions(url).then((response) => {
                if (response.status === 200) {
                    var data = response.data.result.data[0];
                    var item = data;
                    vm.FormSchema[0].Data[0].value = item.discussion_title;
                    vm.FormSchema[0].Data[1].value = item.discussion_description;                    
                    vm.discussiontype = item.discussion_type;
                    var selectedUsers = item.UserIds
                        .split(',')
                        .map(x => x.trim());
                    var options = vm.FormSchema[0].Data[3].config.options;
                    var userList = [];
                    
                    selectedUsers.forEach(id => {
                        var matched = options.find(opt => String(opt.value) === String(id));
                        if (matched) {
                            userList.push({
                                label: matched.name,
                                value: matched.value
                            });
                        }
                    });
                    vm.FormSchema[0].Data[3].value = userList;
                }
            });
        },
        onSubmit: async function () {            
            var vm = this;
            vm.isLoading = true;            
            var privateUserValue = "";
            if (vm.discussiontype === "private") {
                if (vm.FormSchema[0].Data[3].value && Array.isArray(vm.FormSchema[0].Data[3].value) && vm.FormSchema[0].Data[3].value.length > 0) {
                    privateUserValue = vm.FormSchema[0].Data[3].value.map(u => u.value || u).join(',');
                }
            } else {
                privateUserValue = "";
            }
            
            var jsonobj = {
                DiscussionId: vm.DiscussionId > 0 ? vm.DiscussionId : 0,
                ProjectId: vm.projectId,
                Title: vm.FormSchema[0].Data[0].value, 
                Description: vm.FormSchema[0].Data[1].value, 
                DiscussionType: vm.discussiontype,
                Avatar: '',            
                StatusId: 1001,
                PrivateUser: privateUserValue
            };            
            var params = JSON.stringify(jsonobj);
            await DataService.SaveProjectDiscussions(params).then((response) => {                
                if (response.data.code == '1' && response.data.status == 'Success') {
                    vm.isLoading = false;
                    var DiscussionMsg = vm.discussiontype === "private"?'Private Group':'Public Group';
                    if (response.data.result[0].message == 'INSERT_SUCCESS') {
                        vm.ShowAlert(vm.$t('AddedSuccess', [vm.$t(DiscussionMsg)]), "success", true, vm.$t("Alert"));
                        vm.$parent.GetProjectDiscussions();
                        vm.Close();
                    }
                    else if(response.data.result[0].message == 'UPDATE_SUCCESS') {
                        vm.ShowAlert(vm.$t('UpdatedSuccess', [vm.$t(DiscussionMsg)]), "success", true, vm.$t("Alert"));
                        vm.$parent.GetProjectDiscussions();
                        vm.Close();
                    }
                    else if (response.data.result[0].message == 'Discussion title already exists in this company') {
                        vm.ShowAlert(vm.$t('DiscussionAlreadyExist', [vm.$t('Discussion')]), "warning", true, vm.$t("Alert"));
                    } 
                    // else if (response.data.code == '1') {
                    //     vm.ShowAlert(vm.$t('DiscussionAlreadyExist', [vm.$t('Discussion')]), "warning", true, vm.$t("Alert"));
                    // }
                    // else {
                    //     //var DiscussionMsg = vm.discussiontype === "private"?'Private Group':'Public Group';
                    //     if (response.data.result[0].message == 'Discussion updated successfully') {
                    //         vm.ShowAlert(vm.$t('UpdatedSuccess', [vm.$t(DiscussionMsg)]), "success", true, vm.$t("Alert"));
                    //     } else {
                    //         vm.ShowAlert(vm.$t('AddedSuccess', [vm.$t(DiscussionMsg)]), "success", true, vm.$t("Alert"));
                    //     }
                      
                    // }
                }
            }).catch((error) => {
                vm.isLoading = false;
                console.error('Error saving discussion:', error);
                vm.ShowAlert(vm.$t('UnknownErrorOccur'), "failure", true, vm.$t('Alert'));
            });
        }, 
        GetPrivateUsers() {
            const userField = this.FormSchema[0].Data[3];
            userField.config.options = []; 
            const loggedInUserName = this.UserName; 
            this.DirectUserData.forEach(u => {
                if (u.UserName !== loggedInUserName) {
                    userField.config.options.push({
                        value: u.UserId,
                        name: u.UserName
                    });
                }
            });
        },
        FetchTeam: async function () {
            this.isLoading = true;
            const url = `projectId=${this.projectId}&projectName=&designationId=&sortBy=&sortExp=&pageSize=${this.PageSize}&pageNum=${this.PageNumber}`;
            await DataService.GetTeamListing(url).then((response) => {
                this.isLoading = false;
                const teamData = response?.data?.result?.data || [];
                if (teamData.length > 0) {
                    this.DirectUserData = teamData.map(user => ({
                    UserId: user.USER_ID,
                    UserName: user.USER_NAME || user.ALIASNAME,
                    ProjectId: user.PROJECT_ID,
                    ProjectName: user.PROJECT_NAME,
                    TeamProjectId: user.TEAM_PROJECT_ID,
                    UserType: user.USERTYPE,
                    DesignationId: user.DESIGNATION_ID,
                    DesignationName: user.DESIGNATION_NAME,
                    Department: user.DEPARTMENT || '',
                    isOnline: user.is_online || false,
                    UserMessageCount: user.MESSAGE_COUNT
                    }));
                    this.GetPrivateUsers();
                } else {
                    this.DirectUserData = []; 
                }
                })
                .catch((error) => {
                this.isLoading = false;
                this.DirectUserData = [];
            });
        },   
        Close() {
            this.$parent.showAddMessagePopup = false;
        }
    }
}
</script>