                        this.IsTaskType = response.data.result.TASKSTATUSDATA.length > 0 ? true : false;
                        this.bindComponentChartDataa(response.data.result.TASKSTATUSDATA);
                    }
                    if (response.data.result.SPRINTDATA != null) {
                        this.IsSprintType = response.data.result.SPRINTDATA.length > 0 ? true : false;
                        this.bindComponentSprintChartDataa(response.data.result.SPRINTDATA);
                    }
                    if (response.data.result.STAGEDATA != null) {
                        this.isStage = response.data.result.STAGEDATA.length > 0 ? true : false;
                        this.bindComponentStageChartDataa(response.data.result.STAGEDATA);
                    }
                    if (response.data.result.BACKLOCK != null) {
                        this.isBacklock = response.data.result.BACKLOCK.length > 0 ? true : false;
                        this.bindComponentBacklockChartDataa(response.data.result.BACKLOCK);
                    }
                    if (response.data.result.STAGEBYDAYS != null) {
                        this.isstagebydays = response.data.result.STAGEBYDAYS.length > 0 ? true : false;
                        this.bindComponenStageDayChartDataa(response.data.result.STAGEBYDAYS);
