        bindComponenStageDayChartDataa(dataa) {

        if (!dataa || dataa.length === 0) return;
        const categories = dataa.map(item =>
            item.STAGE_NAME || "Stage");
        const values = dataa.map(item =>
            Number(item.TOTAL_DAYS) || 0 );
