        this.$set(this.stageDayChartOptions.xaxis, 'categories', categories);
        this.$set(this.stageDayChartOptions, 'colors', colors);
        this.chartKey++; 
        },   
        bindComponentBacklockChartDataa(dataa) {
            if (!dataa || dataa.length === 0) return;
            const categories = dataa.map(item => 
                item.component_name || "Task"
            );
            const values = dataa.map(item => 
