        bindComponentStageChartDataa(phasedata) {
            if (!phasedata || phasedata.length === 0) return;
            const categories = phasedata.map(item => item.stage_name);
            const data = phasedata.map(item => Number(item.stage_progress));
            const colors = phasedata.map(item => item.status_bg_color);
            this.campaignseries = [{
                name: "Progress (%)",
                data: data
