        bindComponentSprintChartDataa(data) {
            if (!data || !Array.isArray(data) || data.length === 0) {
                this.sprintSeries = []
                this.sprintchartOptions.xaxis.categories = []
                this.sprintchartOptions.fullData = []
                return
            }
            const categories = data.map(item => {
                const name = item.sprint_name?.trim() || `Sprint ${item.id || '?'}`;
                return name.charAt(0).toUpperCase() + name.slice(1);
            });

            this.$set(this.sprintchartOptions.xaxis, 'categories', categories)
            this.$set(this.sprintchartOptions, 'fullData', data)

            this.sprintSeries = [
                { name: 'Total', data: data.map(i => Number(i.total_tasks) || 0) },
                { name: 'Active', data: data.map(i => Number(i.active_tasks) || 0) },
                { name: 'Closed', data: data.map(i => Number(i.closed_tasks) || 0) },
                { name: 'In Progress', data: data.map(i => Number(i.inprogress_tasks) || 0) },
                { name: 'Completed', data: data.map(i => Number(i.completed_tasks) || 0) },
                { name: 'Pending', data: data.map(i => Number(i.pending_tasks) || 0) },
                { name: 'InActive', data: data.map(i => Number(i.inactive_tasks) || 0) },
                { name: 'Cancelled', data: data.map(i => Number(i.cancel) || 0) },
                { name: 'Progress(%)', data: data.map(i => Number(i.completion_percentage) || 0) }
            ]
                        this.$nextTick(() => {
                if (this.$refs.sprintChart?.chart) {
                    this.$refs.sprintChart.chart.updateOptions(this.sprintchartOptions, true, true)
                    this.$refs.sprintChart.chart.updateSeries(this.sprintSeries, true)
                }
            })
