<template>
    <div class="my-popups">
        <loader :is-visible="isLoading"></loader>
        <div class="modal d-block">
            <div class="modal-dialog modal-dialog-centered">
                <div class="modal-content">
                    <div class="modal-header theme-primary partition-full  d-flex">
                        <h4 class="modal-title" v-if="!PhaseItem.PHASE_ID">{{ $t('Add') }} {{ $t(NewTabName) }} </h4>

                        <h4 class="modal-title" v-else>{{ $t('Edit') }} {{ $t(NewTabName) }} </h4>
                        
                        <button type="button" class="close" v-on:click="ClosePhase">
                            <em class="fa fa-times" aria-hidden="true"></em>
                        </button>
                    </div>
                    <div class="modal-body" v-if="!showAddEditPhaseModal">
                        <dynamic-form lang="en" :buttons="buttons" :schema="FormSchema" ref="AssignTagForm"
                            :mandatorytext='MandatoryString' v-on:OnSubmit="OnSubmit"></dynamic-form>
                    </div>
                    <div class="modal-body" v-if="showAddEditPhaseModal">
                        <div class="heading-border mb-3">
                            <h5 class="h5">
                                <span> {{ $t('Phase') }}</span>
                            </h5>
                        </div>
                        <Form ref="form" v-slot="{ values, meta }">
                            <div class="d-flex flex-wrap">
                                <div class="col-md-12 p-0">
                                    <div class="row">
                                        <div class="col-sm-12 col-md-12 col-lg-12 col-xl-12 float-left">
                                            <div class="listing">

                                                <div class="table-responsive overflow-visible">
                                                    <!-- table-fix-header -->
                                                    <table id="tblPhase"
                                                        class="table table-bordered dt-responsive nowrap mt-0 mb-0">
                                                        <thead class="thead-bg">
                                                            <tr>
                                                                <th style="width:50px !important;" id="nonresize">
                                                                    <div class="custom-control custom-checkbox">
                                                                        <input
                                                                            class="chkItems setcheckall custom-control-input"
                                                                            type="checkbox" id="chkAll" name="checkbox"
                                                                            data-parent="no" style="display: none;"
                                                                            v-model="selectAll"
                                                                            v-on:change="PhaseCheckAll($event)">
                                                                        <label
                                                                            class="custom-control-label universal-custom-control-label pt-1"
                                                                            for="chkAll"></label>
                                                                    </div>
                                                                </th>
                                                                <th class="d-none"><span href="javascript:;">Phase
                                                                        id</span></th>
                                                                <th><span
                                                                        href="javascript:;">{{ $t(NewTabName) }} {{ $t('Name')}}</span>
                                                                </th>
                                                                <th style="width:340px;"><span href="javascript:;">{{
                                                                        $t('ProjectStartDate') }}( {{ ProjectStartDate
                                                                        }})</span></th>
                                                                <th style="width:340px;"><span href="javascript:;">{{
                                                                        $t('ProjectEndDate') }} ( {{ ProjectEndDate
                                                                        }})</span></th>
                                                            </tr>
                                                        </thead>
                                                        <tbody>
                                                            <tr v-for="(item, index) in AddPhaseListing"
                                                                v-if="!noRecordForTab">
                                                                <td>
                                                                    <div class="custom-control custom-checkbox">
                                                                        <input
                                                                            class="chkItems setcheckall custom-control-input"
                                                                            :value="item.PHASE_ID"
                                                                            :disabled="item.DateDisabled"
                                                                            type="checkbox" :id="'chkAll_' + index"
                                                                            name="checkbox" data-parent="no"
                                                                            style="display: none;"
                                                                            v-model="item.selected"
                                                                            v-on:change="PhaseChange(item)">
                                                                        <label
                                                                            class="custom-control-label universal-custom-control-label pt-1"
                                                                            :for="'chkAll_' + index"></label>
                                                                    </div>
                                                                </td>
                                                                <td class="d-none"><span class="PhaseList_PhaseId"
                                                                        v-bind:value="item.PHASE_ID">{{ item.PHASE_ID
                                                                        }}</span></td>
                                                                <td><span class="nochk">{{ item.PHASE_NAME }}</span>
                                                                </td>
                                                                <td>
                                                                    <div class="input-group table_datepickerfix">
                                                                        <Field :name="'startdate' + index"
                                                                            :rules="{ required: item.selected == true ? true : false }"
                                                                            v-slot="{ errors, changed }">

                                                                            <v-date-picker :minute-increment="5"
                                                                                class="input-group"
                                                                                v-model="item.START_DATE"
                                                                                @update:modelValue="changed"
                                                                                :min-date="HideprojectStartDate"
                                                                                :max-date="HideprojectEndDate">
                                                                                <template
                                                                                    v-slot="{ inputValue, togglePopover }">
                                                                                    <input :placeholder="'MM/DD/YYYY'"
                                                                                        v-bind:class="{ 'form-control': true, 'is-invalid': errors[0] }"
                                                                                        :value="inputValue" />
                                                                                    <div @click="togglePopover()"
                                                                                        class="input-group-append"><span
                                                                                            class="input-group-text"><em
                                                                                                class="fa fa-calendar"></em></span>
                                                                                    </div>
                                                                                </template>
                                                                            </v-date-picker>
                                                                            <span v-if="errors[0]"
                                                                                :name="'startdate' + index"
                                                                                class="invalid-feedback d-block"> {{
                                                                                $t('StartDateReq') }}</span>
                                                                        </Field>
                                                                    </div>
                                                                </td>
                                                                <td>
                                                                    <div class="input-group table_datepickerfix">
                                                                        <Field :name="'enddate' + index"
                                                                            :rules="{ required: item.selected == true ? true : false }"
                                                                            v-slot="{ errors, changed }">
                                                                            <v-date-picker :minute-increment="5"
                                                                                class="input-group"
                                                                                v-model="item.END_DATE"
                                                                                @update:modelValue="changed"
                                                                                :min-date="item.START_DATE || HideprojectStartDate"
                                                                                :max-date="HideprojectEndDate">
                                                                                <template
                                                                                    v-slot="{ inputValue, togglePopover }">
                                                                                    <input :placeholder="'MM/DD/YYYY'"
                                                                                        v-bind:class="{ 'form-control': true, 'is-invalid': errors[0] }"
                                                                                        :value="inputValue" />
                                                                                    <div @click="togglePopover()"
                                                                                        class="input-group-append"><span
                                                                                            class="input-group-text"><em
                                                                                                class="fa fa-calendar"></em></span>
                                                                                    </div>
                                                                                </template>
                                                                            </v-date-picker>
                                                                            <span v-if="errors[0]"
                                                                                :name="'enddate' + index"
                                                                                class="invalid-feedback d-block"> {{
                                                                                $t('EndDateReq')
                                                                                }}</span>
                                                                        </Field>
                                                                    </div>
                                                                </td>
                                                            </tr>
                                                            <tr v-if="noRecordForTab">
                                                                <td colspan="4">
                                                                    <div class="text-center text-danger">{{
                                                                        $t('NoRecordfound') }}</div>
                                                                </td>
                                                            </tr>
                                                        </tbody>
                                                    </table>
                                                </div>

                                            </div>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </Form>
                        <div class="modal-footer">
                            <a href="javascript:;" v-on:click="SavePhase($event)" class="btn btn-success formbtn">
                                <i class="fa fa-save"></i> {{ $t('Save') }}
                            </a>
                        </div>
                    </div>

                </div>
            </div>
        </div>
    </div>
</template>
<script>
import DataService from '../../services/DataService';
import moment from 'moment';
export default {
    props: {
        phaseList: {
            type: Array,
            required: true
        },
        PhaseItem: {
            type: Array,
            required: false
        },
        NewTabName: {
            type: Number,
            required: true
        },
        TabsArray:{
          type:Array
        }
    },
     watch: {
        // Watch for NewTabName changes and update Buttons
        NewTabName: {
            handler(newTabName) {
            
                this.TabsArray.find(t => t.displayCode === "PROJECT_PHASE")?.displayName || 'Project  Phase';
                if (newTabName) {
                    this.UpdateFieldsText(newTabName);
                }
            },
            immediate: true
        }
    },
    data() {
        return {
            selectAll: false,
            showAddEditPhaseModal: false,
            noRecordForTab: false,
            enddate: '',
            startdate: '',
            AddPhaseListing: [],
            HideprojectStartDate: '',
            HideprojectEndDate: '',
            MandatoryString: 'Fields marked with an asterisk (*) are mandatory.',
            FormSchema: [
                {
                    layoutType: "double",
                    Data: [
                        {
                            astype: "TextField",
                            label: this.$t('PhaseName'),
                            name: "PhaseName",
                            value: "",
                            placeholder: this.$t('Enter Phase Name'),
                            validationRules: { "required": true, max: 100 },
                        },
                        {
                            astype: "TextField",
                            label: this.$t('Rate'),
                            name: "Rate",
                            value: "",
                            visibility: false,
                            placeholder: this.$t('Enter Rate'),
                            validationRules: { "required": true, max: 100 },
                        },
                        {
                            astype: "SelectField",
                            label: this.$t('Status'),
                            name: "Status",
                            value: "",
                            config: {
                                options: []
                            },
                            placeholder: this.$t('Select Status'),
                            validationRules: { "required": true, max: 100 },
                        }
                    ]
                },
                {
                    layoutType: "single",
                    Data: [
                        {
                            astype: "TextAreaField",
                            label: this.$t('Description'),
                            name: "Description",
                            value: "",
                            validationRules: { "required": false, max: 4000 },
                            config: {
                                rows: 5
                            }
                        }
                    ]
                }
            ],
            buttons: [
                {
                    type: "submit",
                    class: "btn btn-success",
                    text: "<i class='fa fa-save pr-2'></i>Save",
                    isVisible: true
                },
                {
                    type: "button",
                    class: "btn btn-danger",
                    text: "<i class='fa fa-close pr-2'></i>Cancel",
                    onClick: this.ClosePhase,
                },
            ],
            ProjectId: null,
            isLoading: false,
            ProjectEndDate: '',
            ProjectStartDate: '',
            ProjectName: '',
            selectedStage: '',
        }
    },
    created: async function () {
        var ths = this;
        ths.NewTabName=ths.TabsArray.find(t => t.displayCode === "PROJECT_PHASE")?.displayName || 'Project  Phase';
        ths.FormSchema[0].Data[1].label=ths.TabsArray.find(t => t.displayCode === "PROJECT_PHASE")?.displayName || 'Project  Phase';
        ths.ProjectId = ths.$route.params.projectId;
        ths.GetStatusList();
        ths.openAddPhaseDetailModel();
        ths.ProjectOverview();
        if (this.PhaseItem.PHASE_ID > 0) {
            this.FormSchema[0].Data[0].value = this.PhaseItem.PHASE_NAME;
            this.FormSchema[0].Data[1].value = this.PhaseItem.STATUS_ID;
            this.FormSchema[1].Data[0].value = this.PhaseItem.PHASE_DESC;     
        }

    },
    methods: {
         UpdateFieldsText(newTabName) {
            var vm = this;
            // Loop through FormSchema to find and update MilestoneNumber label
            vm.FormSchema.forEach((section) => {
                if (section.Data && Array.isArray(section.Data)) {
                    section.Data.forEach((field) => {
                        if (field.name === 'PhaseName') {
                            // Update the label based on newTabName                           

                            field.label = `${this.$t(this.NewTabName)}` + ' ' + 'Name';
                        }
                      
                    });
                }
            });
        },
        ProjectOverview: async function () {
            var vm = this;
            var params = `projectId=${this.ProjectId}`;
            await DataService.ProjectOverview(params).then(function (response) {
                if (response.data != null > 0) {
                    vm.ProjectStartDate = vm.formatDate(response.data.planneD_START_DATE);
                    vm.ProjectEndDate = vm.formatDate(response.data.planneD_END_DATE);
                    vm.ProjectName = response.data.projecT_NAME;
                    let startDate = new Date(vm.ProjectStartDate);
                    startDate.setDate(startDate.getDate() + 1);
                    vm.HideprojectStartDate = startDate.toISOString().split('T')[0];

                    let endDate = new Date(vm.ProjectEndDate);
                    endDate.setDate(endDate.getDate() + 1);
                    vm.HideprojectEndDate = endDate.toISOString().split('T')[0];
                    //  vm.HideprojectStartDate = new Date(vm.ProjectStartDate).toISOString().split('T')[0];
                    // vm.HideprojectEndDate = new Date(vm.ProjectEndDate).toISOString().split('T')[0];
                }
            });
        },
        ClosePhase: function () {
            this.$parent.isAddPhase = false;
        },

        formatDate(dateValue) {
            if (!dateValue) return '';

            // If it's already a Date object
            if (dateValue instanceof Date) {
                return dateValue.toLocaleDateString("en-US");
            }

            // If it's a string, try to parse it
            if (typeof dateValue === 'string') {
                // Remove time portion if it exists
                const dateOnly = dateValue.split('T')[0];
                return new Date(dateOnly).toLocaleDateString("en-US");
            }

            // For timestamps or other formats
            return new Date(dateValue).toLocaleDateString("en-US");
        },
        async GetStatusList() {            
            try {
                const params = `statusType=Project&hasglobal=false`;
                const response = await DataService.GetStatusList(params);
                response.data.forEach((itm) => {
                    (this.FormSchema)[0].Data[2].config.options.push({
                        name: itm.STATUS,
                        value: itm.STATUS_ID,
                    })
                });
                const statusField = this.FormSchema[0].Data[2];
                const activeOption = statusField.config.options.find(o => o.name.toLowerCase() === "active");
                if (activeOption) {
                    statusField.value = activeOption.value;
                } else if (statusField.config.options.length > 0) {
                    statusField.value = statusField.config.options[0].value;
                }
                this.$refs.AssignTagForm.UpdateKeyValue();
            }
            catch (err) {
                console.error("Error fetching status list:", err);
            }
        },
        OnSubmit: function () {
            var vm = this;
            var statusField = this.FormSchema[0].Data.find(f => f.name === "Tag");
            var data = {
                PHASEID: vm.PhaseItem.PHASE_ID > 0 ? vm.PhaseItem.PHASE_ID : 0,
                PhaseName: vm.FormSchema[0].Data[0].value,
                StatusId: vm.FormSchema[0].Data[2].value,
                PhaseDescription: vm.FormSchema[1].Data[0].value
            }
            var objectPostString = JSON.stringify(data);
            DataService.AddSavePhase(objectPostString).then((response) => {
                if (response.data.result.DATA.length > 0) {
                    if (response.data.result.DATA[0].VALUE == 'INSERT') {
                        vm.ShowAlert(vm.$t('AddedSuccess', [vm.$t(vm.NewTabName)]), "success", true, vm.$t("Alert"));
                        vm.showAddEditPhaseModal = true;
                        vm.openAddPhaseDetailModel();
                    } else if (response.data.result.DATA[0].VALUE == 'UPDATE') {
                        vm.ShowAlert(vm.$t('UpdateSuccess', [vm.$t(vm.NewTabName)]), "success", true, vm.$t("Alert"));
                        vm.showAddEditPhaseModal = true;
                        vm.openAddPhaseDetailModel();
                    }
                    else {
                        vm.ShowAlert(vm.$t('AlreadyExists', [vm.$t(vm.NewTabName)]), "warning", true, vm.$t("Alert"));
                    }
                }
            });
        },
        openAddPhaseDetailModel: function () {
            var ths = this;
            //ths.showAddEditPhaseModal=false;
            var url = `projectId=${ths.ProjectId}`;
            DataService.AddEditPhaseListing(url).then((response) => {
                if (response.data.result.DATA.length > 0) {
                    //ths.AddPhaseListing=response.data.result.DATA;
                    ths.AddPhaseListing = response.data.result.DATA.map(item => ({
                        ...item,
                        selected: false,
                    }));
                    //ths.showAddEditPhaseModal=false;
                    ths.AddPhaseListing.forEach(item => {
                        item.DateDisabled = false;
                        if (item.START_DATE != null) {
                            item.DateDisabled = true;
                            item.selected = false;
                        }
                        item.SCheckdate = false;
                        item.ECheckdate = false;
                    })
                } else {
                    ths.noRecordForTab = true;
                }
            })
        },
        PhaseCheckAll(evt) {
            const isChecked = evt.target.checked;
            this.AddPhaseListing.forEach(item => {
                if (!item.DateDisabled) {
                    item.selected = isChecked;
                }

            });
            this.selectAll = isChecked;
            // Trigger form validation to show required field messages
            this.$nextTick(() => {
                this.$refs.form.validate();
            });
            // var checkedarray = document.getElementsByClassName("chkItems setcheckall custom-control-input");
            // if(evt.target.checked){
            //     for (var i = 0; i < checkedarray.length; i++) {
            //         checkedarray[i].checked = true;
            //         checkedarray[i].DateDisabled = true;                    
            //     }
            // }else{
            //     for (var i = 0; i < checkedarray.length; i++) {
            //         checkedarray[i].checked = false;
            //         checkedarray[i].DateDisabled = true;
            //     }                
            // }
        },
        isDisabled(id) {
            this.selectedStage = this.stageList.some(p => p.PHASE_ID === id);
            return this.phaseList.some(p => p.PHASE_ID === id);
        },
        PhaseChange(item) {
            const allSelected = this.AddPhaseListing.filter(it => !it.DateDisabled).every(it => it.selected);
            this.selectAll = allSelected;
        },
        // PhaseChange: function (event, item) {
        //     if (event.target.checked){
        //         item.DateDisabled = true;
        //     }
        //     else {
        //         item.DateDisabled = false;
        //     }
        // },
        SavePhase: function (evt) {
            var vm = this;
            vm.$refs.form.validate().then((result) => {

                if (result) {
                    vm.isLoading = true;
                    const selecteddata = vm.AddPhaseListing.filter(
                        it => it.selected
                    );
                    var filteredArray = vm.AddPhaseListing.filter(item => item.selected || item.DateDisabled);
                    if (selecteddata.length === 0 && filteredArray.length === 0) {
                        vm.isLoading = false;
                        vm.ShowAlert("Please check at least one checkbox", "warning", true, vm.$t("Alert"));
                        return false; // stop execution here
                    }

                    const PSD = vm.ProjectStartDate;
                    const PED = vm.ProjectEndDate;
                    var postString = [];
                    var selectedPhases = [];
                    // $("#tblPhase input:not(.chkAll):checkbox:checked").each(function() {
                    //     selectedPhases.push($(this).val());
                    // });
                    // if (selectedPhases.length == 0) {
                    //     vm.isLoading=false;
                    //     vm.ShowAlert(vm.$t('OnePhaseMandatory'), "warning", true,  vm.$t("Alert")); 
                    //     return false;
                    // }
                    //if (selectedPhases.length> 0) {

                    // var filteredArray = vm.AddPhaseListing.filter(item => selectedPhases.includes(String(item.PHASE_ID)));
                    $.each(filteredArray, function (idx, item) {
                        var obj = {
                            PhaseId: item.PHASE_ID,
                            ProjectId: vm.ProjectId,
                            SD: item.START_DATE,
                            ED: item.END_DATE
                        }
                        // var STD=new Date(obj.SD);
                        // var EDT=new Date(obj.ED);

                        // if (STD > EDT) {                        
                        //     item.SCheckdate=true;
                        //     vm.ShowAlert(vm.$t('StartDateNotGreaterEndDate'), "failure", true,  vm.$t("Alert"));
                        //     vm.isLoading=false;
                        // }
                        // else {
                        //     if (obj.SD == '') {
                        //    // if (!obj.SD || STD.isBefore(PSD) || STD.isAfter(PED)) {
                        //         item.SCheckdate=true;                            
                        //         vm.isLoading=false;
                        //     } else {
                        //         item.SCheckdate=false;
                        //     }
                        //     if (obj.ED == '') {
                        //     //if (!obj.ED || EDT.isBefore(PSD) || EDT.isAfter(PED)) {
                        //         item.ECheckdate=true;
                        //         vm.isLoading=false;
                        //     } else {
                        item.ECheckdate = false;
                        postString.push(obj);
                        //   }
                        //}
                    })
                    let clashDates = false;
                    if (postString.length > 0) {
                        $.each(postString, function (idx, item) {
                            if (idx > 0) {
                                var chkData = $.grep(postString, function (element) {
                                    return (
                                        (new Date(element.SD).setHours(0, 0, 0, 0) >= new Date(item.SD).setHours(0, 0, 0, 0) &&
                                            new Date(element.SD).setHours(0, 0, 0, 0) <= new Date(item.ED).setHours(0, 0, 0, 0)) ||
                                        (new Date(element.SD).setHours(0, 0, 0, 0) <= new Date(item.SD).setHours(0, 0, 0, 0) &&
                                            new Date(element.ED).setHours(0, 0, 0, 0) >= new Date(item.ED).setHours(0, 0, 0, 0)) ||
                                        (new Date(element.ED).setHours(0, 0, 0, 0) >= new Date(item.SD).setHours(0, 0, 0, 0) &&
                                            new Date(element.ED).setHours(0, 0, 0, 0) <= new Date(item.ED).setHours(0, 0, 0, 0))
                                    );
                                });
                                if (chkData.length > 1) {
                                    clashDates = true;
                                }
                            }
                        });
                    }
                    if (!clashDates) {
                        var objectPostString = JSON.stringify(postString);
                        DataService.SavePhase(objectPostString).then((response) => {
                            if (response.data.result == 'success' && response.data != null) {
                                vm.isLoading = false;
                                vm.ShowAlert(vm.$t('AddedSuccess', [vm.$t(vm.NewTabName)]), "success", true, vm.$t("Alert"));
                                vm.$parent.FetchProjectPhaseList();
                                vm.ClosePhase();
                            }
                            else {
                                vm.isLoading = false;
                                vm.ClosePhase();
                                vm.ShowAlert(vm.$t('AddedError', [vm.$t(vm.NewTabName)]), "failure", true, vm.$t("Alert"));
                            }
                        })
                    } else {
                        vm.isLoading = false;
                        vm.ShowAlert(vm.$t('DateValidationOnStage'), "warning", true, vm.$t("Alert"));
                    }
                    //}

                }
                else {
                    vm.isLoading = false;
                    //vm.ShowAlert(vm.$t('DateValidationOnStage'), "warning", true, vm.$t("Alert"));   
                }
            });
        }
    }
}
</script>