        },
      ],
      stateList:[],
    }
},
methods:{
    GetCountry()
      {
        var vm=this;
        var url=`CountryId${id}`;
        DataService.GetStateListByCountryId(url).then((response)=>{
              vm.stateList=response;
        })
      },
      GetState(id)
      {
        var vm=this;
        var url=`CountryId${id}`;
        DataService.GetStateListByCountryId(url).then((response)=>{
              vm.stateList=response;
        })
      },
