       var vm=this;
      var companyName=vm.FormSchema[0].Data[0].value; 
      var firstName=vm.FormSchema[0].Data[1].value; 
      var lastName=vm.FormSchema[0].Data[2].value; 
      var email=vm.FormSchema[0].Data[3].value; 
      var password=vm.FormSchema[0].Data[4].value; 
