<template>
    <section>
        <div class="my-popups">
            <loader :is-visible="isLoading"></loader>
            <div class="modal d-block">                
                <div class="modal-dialog modal-dialog-centered">
                    <div class="modal-content">
                        <div class="modal-header theme-primary partition-full d-flex">
                            <h4 class="modal-title">{{ noteText }} {{ $t('Notes') }}</h4>                            
                            <button type="button" class="close" @click="Cancel">
                                <em class="fa fa-times" aria-hidden="true"></em>
                            </button>
                        </div>
                       <div class="modal-body">
                           <dynamic-form ref="validateManagenote" lang="en" :buttons="commentButtons" :schema="FormSchema" v-on:OnSubmit="SaveNote" :mandatorytext='MandatoryString'>                                                            
                            <template v-slot:tgslot-Description="{ data }">
                                    <ckeditor :editor="editor" @ready="onReady" v-model="data.fieldInfo.value">
                                    </ckeditor>
                                    <span name="Description" class="invalid-feedback d-block">{{ data.error }}</span>
                                </template>
                            </dynamic-form>
                         </div>                        
                    </div>
                </div>
            </div>
        </div>       
    </section>
</template>
<script>
import DataService from '../../services/DataService';

export default {
   props: {    
        NoteId: {
            type: Number,
            required: true
        },
        noteText: {
            type: String,
            required: true
        },
        modalNoteItem: {
            type: Object,
            required: true
        }
    },
    data() {
        return {
            noRecord: false,
            MandatoryString:'Fields marked with an asterisk (*) are mandatory.',
            TotalRecords: 0,
            noteId:0,
            isLoading: false,
            progress: 0,
            projectId:0,
            IsShowMileStoneDiv:false,
            IsShowTaskDiv:false,
            IsShowPercentDiv:false,
            editor: this.CLASSIC_EDITOR,            
            FormSchema: [
                {
                    layoutType: "double",
                    Data: [
                        {
                            astype: "SelectField",
                            label: this.$t('Visibility'),
                            name: "MilestoneCriteria",
                            value: "",
                            placeholder: "",
                            validationRules: {
                                required: true,
                            },
                            config: {  options: [
                            { value: "true", name: this.$t('Public') }, 
                            { value: "false", name: this.$t('Private') }
                            ] ,
                            onChange: this.changeMilestone},
                            disabled: false,
                        },
                        {
                            astype: "SelectField",
                            label: this.$t('Task'),
                            name: "Task",
                            value: "",
                            placeholder: "Select Task",
                            validationRules: {
                                required: true,
                            },
                            config: { options: [] ,onChange: this.changeMilestone},
                            disabled: false,
                        }
                    ]
                },
                {
                    layoutType: "single",
                    Data:  [
                        {
                            astype: "SlotField",
                            label: this.$t('Note Description'),
                            name: "Description",
                            value: "",
                            placeholder: "",
                            config: {
                                options: [],
                            },
                            settings: {
                                isInSlot: true
                            },
                            visibility: true,
                            validationRules: { "required": true, max: 5000 },
                        },
                    ]
                }
            ],
            commentButtons:[
            {
                    type: "submit",
                    class: "btn btn-success",
                    text: "<i class='fa fa-save pr-2'></i>Save",
                    isVisible:true
                },            
                {
                    type: "button",
                    class: "btn btn-danger",
                    text: "<i class='fa fa-close pr-2'></i>Cancel",
                    onClick: this.Cancel,
                }
            ],
              loginUserName:''
        }
    },
    created() {     
        var vm = this;       
        vm.projectId = vm.$route.params.projectId;
        vm.loginUserName=vm.GetUserInfo.Name;
        if(vm.modalNoteItem != null){
            vm.noteId=vm.modalNoteItem.NOTE_ID;
            vm.FormSchema[0].Data[0].value=vm.modalNoteItem.IS_PUBLIC;
            vm.FormSchema[0].Data[1].value=vm.modalNoteItem.TASK_ID;
            vm.FormSchema[1].Data[0].value=vm.modalNoteItem.NOTE_CONTENT;
        }
        vm.LoadTaskByProjectId();
    },
    methods: {
        onReady(editor) {
            editor.ui.getEditableElement().parentElement.insertBefore(
                editor.ui.view.toolbar.element,
                editor.ui.getEditableElement()
            );
            let mediaIcon = document.getElementsByClassName('ck-dropdown')[2]
            mediaIcon.remove();
            var divToRemove = document.querySelector('.ck-file-dialog-button');
            divToRemove.remove();
            let ArrowIcon = document.getElementsByClassName('ck ck-button ck-off')[8]
            ArrowIcon.remove();
        },
        SaveNote() {
            debugger
            var vm = this;            
            var objData = 
            {
                noteId:vm.noteId,
                moduleName:'PROJECT',
                projectId:vm.projectId,
                isPublic: vm.FormSchema[0].Data[0].value,
                taskId: vm.FormSchema[0].Data[1].value,
                description: vm.FormSchema[1].Data[0].value                 
            };
            var selectedTaskName='';
            vm.FormSchema[0].Data[1].config.options.forEach((element)=>{
                if(element.value==vm.FormSchema[0].Data[1].value)
                    {
                        selectedTaskName= element.name;
                    }
            })
            var objectPostString = JSON.stringify(objData);
            DataService.SaveNote(objectPostString).then(function (response) {
                debugger              
                if (response.data.status== "Success") {  
                 let payload = {
                 projectId: vm.projectId,
                 projectName: 'text',
                 projectContent:`${vm.loginUserName} ${vm.$t('addedanoteto')} ${selectedTaskName}`}
                 DataService.SendAddProjectNotification(JSON.stringify(payload)).then((res) => {
                 console.log("Notification Response:", res.data);
                 });      
                        
                    vm.ShowAlert(vm.$t('AddedSuccess',[vm.$t('Note')]), "success", true,  vm.$t("Alert"));
                    vm.$parent.FetchNoteListing();
                    vm.Cancel();                    
                }
                else {
                    vm.ShowAlert(vm.$t('UnknownErrorOccur'), "failure", true, vm.$t("Alert"));
                }
            }); 
        },       
        LoadTaskByProjectId:function(){   
            var vm= this;
            var url=`projectId=${vm.projectId}`;
            DataService.LoadTaskByProjectId(url).then(response => {
                if (response.status == 200) {
                    if (response.data.result.DATA != undefined || response.data.result.DATA != null) {
                        if (response.data.result.DATA.length > 0) {
                            response.data.result.DATA.forEach((element) => {
                                var obj = {
                                    value: element.TASK_ID,
                                    name: element.TASK_NAME

                                }
                                vm.FormSchema[0].Data[1].config.options.push(obj);
                                vm.$refs.validateManagenote.UpdateKeyValue();
                            })
                    }
                    }
                }
            })
        },      
        Cancel() {
            this.$parent.isAddNotes = false;
        }
        
    }
    
};

</script>


