<template>  
  <section>
    <form data-vv-scope="validateRegistration">
      <div class="heading-border">
        <h5 class="h5">
          <span>Event Publish Configuration</span>
        </h5>
      </div> 
      <div class="row mt-3">
        <div class="col-lg-4"><div class="form-group">
          <label>Publish Configuration Type:</label>
           <div class="form-group pl-0 border-0">
            <div class="form-check form-check-inline">
              <div class="custom-control custom-radio custom-control-inline">
                <input type="radio" name="configurationtype" id="rdo_0" v-model="selectedOption" value="api" class="form-check-input custom-control-input">
                <label class="custom-control-label" for="rdo_0"></label>
              </div> 
              <label for="configurationtype" class="form-check-label font-weight-normal">  API's
                 </label></div>
                  <div class="form-check form-check-inline">
                    <div class="custom-control custom-radio custom-control-inline">
                      <input type="radio" name="configurationtype" id="rdo_1" v-model="selectedOption" value="iframe" class="form-check-input custom-control-input">
                      <label class="custom-control-label" for="rdo_1"></label></div>
                       <label for="configurationtype" class="form-check-label font-weight-normal">Iframe
                        </label></div>
                         <div class="form-check form-check-inline">
                          <div class="custom-control custom-radio custom-control-inline">
                            <input type="radio" name="configurationtype" id="rdo_2" v-model="selectedOption" value="domain" class="form-check-input custom-control-input">
                            <label class="custom-control-label" for="rdo_2"></label>
                          </div> <label for="configurationtype" class="form-check-label font-weight-normal"> Enter Domain Name
                             </label>
                            </div>
                            </div>
                          </div>
                        </div> 
                        <div class="col-lg-4"><label>Domain URL:<span class="text-danger">*</span></label>
                           <div class="input-group"><div class="input-group-append">
                            <span class="input-group-text">Http://</span>
                          </div> 
                          <input data-vv-as="DomainUrl" id="domainurl" name="domainurl"  v-model="domainUrl"
                           :class="{'is-invalid': !isValid && triedSubmit}"
                             @input="validateDomain"
                           type="text" class="form-control" aria-required="true" aria-invalid="false"> 
                        </div>
                      </div>
                    </div> 
                    <div class="row flex-row-reverse">
                      <div class="col-lg-6 text-right mr-2">
                        <a @click="submitForm" href="javascript:;" title="" class="btn btn-success formbtn" data-toggle-tooltip="tooltip" data-original-title="Save">
                          <i class="fa fa-save"></i>{{ $t('Save') }}</a> 
                          <a href="javascript:;" class="btn btn-danger ml-2"><i class="fa fa-times"></i> {{ $t('Cancel') }}</a>
                        </div> 
                      </div>
                      <div class="text-left"><div class="py-2">
                          <span class="mandatory">Fields marked with an asterisk (*) are mandatory.</span>
                        </div>
                    </div>
                  </form>
  </section>
</template>

<script>
import DataService from '@/services/DataService';
export default {
  name: 'RegistrationPortion',
  props: { eventId: { type: [Number, String], required: true } },
  data() { 
    return { 
      settings: null,
      CompanyId: null,
      userId: 0,
      selectedOption: 'domain',
      domainUrl: 'dvdvv.com',
      isValid: true,
      triedSubmit: false 
    }; 
  },
  computed: { 
    settingsText() { 
      return this.settings ? JSON.stringify(this.settings, null, 2) : ''; 
    } 
  },
  created() {
    this.CompanyId = this.GetUserInfo.CompanyId;
    this.userId = this.GetUserInfo.ID;

    DataService.GetEventSettingDetails(
      `eventId=${this.eventId}&companyId=${this.CompanyId}&userId=${this.userId}`
    )
    .then(res => {
      this.settings = (res.data && res.data.result) ? res.data.result : null;
    })
    .catch(() => { this.settings = null; });
  },
  methods:{
    validateDomain() {
    this.triedSubmit = true;
    const urlPattern = /^(https?:\/\/)?([\w-]+\.)+[\w-]{2,}\/?$/;
    this.isValid = urlPattern.test(this.domainUrl.trim());
  },
    submitForm() {
      this.triedSubmit = true;
      if (!this.isValid) {
        this.ShowAlert(this.$t("Pleasecorrectthehighlightederrors"),'failure',true,this.$t('Alert'));
        
      }
    }
  }
};
</script>
<style>
.is-invalid {
  border-color: #dc3545 !important;
}
</style>