<template>
  <section>
    <div class="col-sm-12 col-md-12 col-lg-12 col-xl-12 float-left mainhandlefont p-0 border-0">
      <div class="col-sm-12 col-md-12 col-lg-12 col-xl-12 float-left panel1 p-0 border-0">
        <div class="card-view col-sm-12 col-md-12 col-lg-12 col-xl-12 float-left p-0">
          <div class="col-sm-12 col-md-12 col-lg-12 col-xl-12 float-left px-0">
            <div class="card-box float-left position-relative border-0 col p-0" style="min-height:382px;margin-bottom:10px;">
              <div data-v-00a1b2b3="" class="ticketsmallfix theme-primary partition p-actions-expand " style="overflow: visible;">
                <span data-v-00a1b2b3="" class="p-name text-white">{{ $t('FrequentlyAskedQuestions') }}</span>
                <span data-v-00a1b2b3="" class="p-actions float-right">
                  <a  @click="EditFAQ" data-v-00a1b2b3="" key="[object Object]" title="Back to list" href="javascript:;" class="p-action-btn text-white ">
                    <em data-v-00a1b2b3="" class="fa fa-plus action-icon pr-2"></em> 
                    <br data-v-00a1b2b3=""><span data-v-00a1b2b3="">{{ $t('Add') }}</span></a>
                  <a data-v-00a1b2b3="" key="[object Object]" title="Back to list" href="javascript:;" class="p-action-btn text-white ">
                    <em data-v-00a1b2b3="" class="fa fa fa-angle-double-left pr-2"></em> 
                    <br data-v-00a1b2b3=""><span data-v-00a1b2b3="">Back to list</span></a>
                  </span>
                  <span data-v-00a1b2b3="" class="action-list-box-ddl expand" style="z-index: 999; padding: 0px 10px; right: 0px; line-height: 16px; display: none; position: absolute; top: 50px; color: rgb(17, 17, 17); overflow: auto; width: 224px;">
                    <span data-v-00a1b2b3="" id="action-list" class="list-actions w-100 fsm-list" style="font-size: 14px;">
                      <a data-v-00a1b2b3=""><i data-v-00a1b2b3="" id="closeaction" aria-hidden="true" class="fa fa-times close close-action"></i>
                      </a></span></span><span data-v-00a1b2b3="" class="collapse-head-btns"><a data-v-00a1b2b3="" href="javascript:;" class="collapse-btns">
                        <i data-v-00a1b2b3="" class="fa fa-angle-down text-white fa-angle-down"></i></a></span></div>
              <!-- <div class="heading-border" v-if="showEdit">
                <h5 class="h5"><span>{{ $t('FrequentlyAskedQuestions') }}</span></h5>
              </div> -->
              <div class="cardv-body float-left pt-0 w-100 p-0">
                <div class="col-lg-12 p-0 mt-2" v-if="showReadOnly">
                  <div class="col-md-12 event-description text-center pt-2" v-if="!EventFaqQuestion || EventFaqQuestion === ''">
                    <span class="text-danger no-record">{{ $t('NoRecordfound') }}</span>
                  </div>
                  <div class="col-md-12 event-description p-0" v-else>
                    <div class="description faqtextview" v-html="EventFaqQuestion"></div>
                  </div>
                </div>
                <div class="col-lg-12 mt-3 p-0" v-if="showEdit">
                  <div class="w-100 float-left">
                    <textarea
                      v-model="EventFaqQuestion"
                      class="form-control p-0 border-0"
                      rows="8"
                      :placeholder="$t('FaqField')"
                    ></textarea>
                  </div>
                  <span v-show="ShowFaqErrorMessage" class="text-danger" style="font-size:80%;">{{ $t('FaqField') }}</span>
                </div>
              </div>
              <div class="text-right mt-3 p-0" v-if="showEdit">
                <a href="javascript:;" class="btn btn-success formbtn mr-2" :title="$t('Save')" @click="UpdateFAQQuestion">
                  <i class="fa fa-save pr-2"></i>{{ $t('Save') }}
                </a>
                <a href="javascript:;" class="btn btn-danger" :title="$t('Cancel')" @click="CancelEditFAQ">
                  <i class="fa fa-times"></i> {{ $t('Cancel') }}
                </a>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  </section>
</template>

<script>
import DataService from '@/services/DataService';

export default {
  name: 'FaqPortion',
  props: {
    eventId: {
      type: [Number, String],
      required: true
    }
  },
  data() {
    return {
      EventFaqQuestion: '',
      showEdit: false,
      showReadOnly: true,
      ShowFaqErrorMessage: false
    };
  },
  created() {
    this.fetchFAQ();
  },
  methods: {
    async fetchFAQ() {
      try {
        const response = await DataService.GetFAQQuestion(`eventId=${this.eventId}`);
        if (response.data && response.data.result != null) {
          this.EventFaqQuestion = response.data.result || '';
        } else {
          this.EventFaqQuestion = '';
        }
      } catch (err) {
        this.EventFaqQuestion = '';
      }
    },
    EditFAQ() {
      this.showEdit = true;
      this.showReadOnly = false;
      this.ShowFaqErrorMessage = false;
    },
    CancelEditFAQ() {
      this.showEdit = false;
      this.showReadOnly = true;
      this.fetchFAQ();
    },
    async UpdateFAQQuestion() {
      this.ShowFaqErrorMessage = false;
      if (!this.EventFaqQuestion || String(this.EventFaqQuestion).trim() === '') {
        this.ShowFaqErrorMessage = true;
        return;
      }
      try {
        const postString = JSON.stringify({
          eventId: this.eventId,
          faqContent: this.EventFaqQuestion
        });
        await DataService.UpdateFAQQuestion(postString);
        this.ShowAlert(this.$t('SavedSuccessfully'), 'success', true, this.$t('Alert'));
        this.showEdit = false;
        this.showReadOnly = true;
        this.fetchFAQ();
      } catch (err) {
        this.ShowAlert(this.$t('SaveError'), 'failure', true, this.$t('Alert'));
      }
    }
  }
};
</script>
